function previewMaterial(style, part) {
  const THREE = three.module;
  const color = style.colors[part] ?? style.colors.pipe;
  if (style.lineDrawing) {
    return new THREE.LineBasicMaterial({
      color,
      transparent: false,
      opacity: 1,
    });
  }

  const params = {
    color,
    transparent: style.opacity < 1,
    opacity: style.opacity,
    wireframe: style.wireframe,
    depthWrite: style.opacity >= 0.5,
  };

  if (style.basic) {
    return new THREE.MeshBasicMaterial(params);
  }

  const materialParams = {
    ...params,
    metalness: part === "bolt" ? Math.min(0.78, style.metalness + 0.12) : style.metalness,
    roughness: part === "gasket" ? Math.max(0.62, style.roughness + 0.16) : style.roughness,
    emissive: style.emissive ?? 0x000000,
    emissiveIntensity: style.emissiveIntensity ?? 0,
  };

  if (style.physical || style.clearcoat) {
    return new THREE.MeshPhysicalMaterial({
      ...materialParams,
      clearcoat: style.clearcoat ?? 0,
      clearcoatRoughness: style.clearcoatRoughness ?? 0.22,
    });
  }

  return new THREE.MeshStandardMaterial(materialParams);
}

function cylinderBetween(start, end, radius, material, radialSegments) {
  const THREE = three.module;
  const direction = end.clone().sub(start);
  const length = direction.length();
  const geometry = new THREE.CylinderGeometry(radius, radius, length, radialSegments, 1);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.copy(start).add(end).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction.normalize());
  return mesh;
}

function orientedBoxMesh(center, axisX, axisY, axisZ, sizeX, sizeY, sizeZ, material) {
  const THREE = three.module;
  const geometry = new THREE.BoxGeometry(sizeX, sizeY, sizeZ);
  const mesh = new THREE.Mesh(geometry, material);
  const matrix = new THREE.Matrix4().makeBasis(
    axisX.clone().normalize(),
    axisY.clone().normalize(),
    axisZ.clone().normalize(),
  );
  mesh.position.copy(center);
  mesh.quaternion.setFromRotationMatrix(matrix);
  return mesh;
}

function lineBetween(start, end, material) {
  const THREE = three.module;
  const geometry = new THREE.BufferGeometry().setFromPoints([start, end]);
  return new THREE.Line(geometry, material);
}

function curvedLineBetween(entry, joint, exit, material) {
  const THREE = three.module;
  const curve = new THREE.QuadraticBezierCurve3(entry, joint, exit);
  const geometry = new THREE.BufferGeometry().setFromPoints(curve.getPoints(18));
  return new THREE.Line(geometry, material);
}

function outlinePipeBetween(start, end, radius, material, caps = {}) {
  const THREE = three.module;
  const group = new THREE.Group();
  const axisVector = end.clone().sub(start);
  if (axisVector.length() < 0.0001) return group;

  const axis = axisVector.normalize();
  const basis = radialBasis(axis);
  const railOffsets = Array.from({ length: 6 }, (_, index) => {
    const angle = (Math.PI * 2 * index) / 6;
    return basis.u.clone()
      .multiplyScalar(Math.cos(angle) * radius)
      .add(basis.v.clone().multiplyScalar(Math.sin(angle) * radius));
  });

  for (const offset of railOffsets) {
    group.add(lineBetween(start.clone().add(offset), end.clone().add(offset), material));
  }

  if (caps.startCap) group.add(outlineFlatPipeCap(start, axis, radius, material));
  if (caps.endCap) group.add(outlineFlatPipeCap(end, axis, radius, material));

  return group;
}

function outlineFlatPipeCap(position, direction, radius, material) {
  const THREE = three.module;
  const group = new THREE.Group();
  const basis = radialBasis(direction);
  const points = [
    position.clone().add(basis.u.clone().multiplyScalar(radius)),
    position.clone().add(basis.v.clone().multiplyScalar(radius)),
    position.clone().add(basis.u.clone().multiplyScalar(-radius)),
    position.clone().add(basis.v.clone().multiplyScalar(-radius)),
    position.clone().add(basis.u.clone().multiplyScalar(radius)),
  ];
  group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), material));
  return group;
}

function outlineElbowBetween(entry, joint, exit, radius, material) {
  const THREE = three.module;
  const group = new THREE.Group();
  const curve = new THREE.QuadraticBezierCurve3(entry, joint, exit);
  const incoming = entry.clone().sub(joint).normalize();
  const outgoing = exit.clone().sub(joint).normalize();
  const bendNormal = incoming.clone().cross(outgoing);

  if (bendNormal.length() < 0.0001) {
    return outlinePipeBetween(entry, exit, radius, material);
  }

  bendNormal.normalize();
  const centerPoints = curve.getPoints(30);
  const rails = Array.from({ length: 6 }, () => []);
  for (let index = 0; index < centerPoints.length; index += 1) {
    const previous = centerPoints[Math.max(0, index - 1)];
    const next = centerPoints[Math.min(centerPoints.length - 1, index + 1)];
    const tangent = next.clone().sub(previous).normalize();
    const side = bendNormal.clone().cross(tangent).normalize();
    const point = centerPoints[index];

    for (let railIndex = 0; railIndex < rails.length; railIndex += 1) {
      const angle = (Math.PI * 2 * railIndex) / rails.length;
      rails[railIndex].push(
        point.clone()
          .addScaledVector(side, Math.cos(angle) * radius)
          .addScaledVector(bendNormal, Math.sin(angle) * radius),
      );
    }
  }

  for (const points of rails) {
    group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), material));
  }

  return group;
}

function outlineBandMarker(position, direction, radius, material, width = 0.18) {
  const THREE = three.module;
  const group = new THREE.Group();
  const axis = direction.clone().normalize();
  for (const offset of [-width * 0.5, width * 0.5]) {
    group.add(outlineRing(position.clone().addScaledVector(axis, offset), axis, radius, material));
  }
  return group;
}

function outlineRollGrooveMarker(position, direction, radius, material, width = 0.12) {
  const group = new three.module.Group();
  const axis = direction.clone().normalize();
  const basis = radialBasis(axis);
  const visualWidth = clampNumber(width, 0.016, 0.032);
  const grooveWidth = visualWidth * 0.42;
  const ringOffsets = [
    -visualWidth * 0.5,
    -grooveWidth * 0.5,
    grooveWidth * 0.5,
    visualWidth * 0.5,
  ];
  for (const offset of ringOffsets) {
    group.add(outlineRing(position.clone().addScaledVector(axis, offset), axis, radius * 1.006, material));
  }

  for (const radial of [
    basis.u,
    basis.u.clone().multiplyScalar(-1),
    basis.v,
    basis.v.clone().multiplyScalar(-1),
  ]) {
    group.add(lineBetween(
      position.clone().addScaledVector(axis, -grooveWidth * 0.5).add(radial.clone().multiplyScalar(radius * 0.992)),
      position.clone().addScaledVector(axis, grooveWidth * 0.5).add(radial.clone().multiplyScalar(radius * 0.992)),
      material,
    ));
  }

  return group;
}

function outlineFlangeMarker(position, direction, radius, pipeSizeOrNb, flangeMode, flangeStandard, material) {
  const THREE = three.module;
  const group = new THREE.Group();
  const axis = direction.clone().normalize();
  const isSingle = normalizeFlangeMode(flangeMode) === "single";
  const drilling = flangeDrillingDimensions(flangeStandard, pipeSizeOrNb, radius);
  const { outerRadius, plateThickness, boltCircleRadius, boltHoleRadius, boltCount } = drilling;
  const gasketThickness = flangeGasketThickness(drilling);
  const plateOffset = plateThickness * 0.5 + gasketThickness * 0.5;
  const plateCenters = isSingle
    ? [position.clone()]
    : [-1, 1].map((side) => position.clone().addScaledVector(axis, side * plateOffset));

  for (const plateCenter of plateCenters) {
    group.add(outlineFlangePlate(
      plateCenter,
      axis,
      outerRadius,
      radius * 1.07,
      plateThickness,
      boltCount,
      boltCircleRadius,
      boltHoleRadius,
      material,
    ));
  }

  if (!isSingle) {
    const gasketOuterRadius = Math.max(radius * 1.12, Math.min(outerRadius * 0.82, boltCircleRadius - boltHoleRadius * 1.25));
    group.add(outlineRing(position, axis, gasketOuterRadius, material));
    group.add(outlineRing(position, axis, radius * 1.05, material));
  }

  return group;
}

function outlineFlangePlate(position, axis, outerRadius, innerRadius, thickness, boltCount, boltCircleRadius, boltHoleRadius, material) {
  const THREE = three.module;
  const group = new THREE.Group();
  const basis = radialBasis(axis);
  const faces = [-0.5, 0.5].map((side) => position.clone().addScaledVector(axis, side * thickness));

  for (const face of faces) {
    group.add(outlineRing(face, axis, outerRadius, material));
    group.add(outlineRing(face, axis, innerRadius, material));

    for (let index = 0; index < boltCount; index += 1) {
      const angle = (Math.PI * 2 * index) / boltCount + Math.PI / boltCount;
      const boltCenter = face.clone()
        .add(basis.u.clone().multiplyScalar(Math.cos(angle) * boltCircleRadius))
        .add(basis.v.clone().multiplyScalar(Math.sin(angle) * boltCircleRadius));
      group.add(outlineRing(boltCenter, axis, boltHoleRadius, material));
    }
  }

  for (const radial of [
    basis.u,
    basis.u.clone().multiplyScalar(-1),
    basis.v,
    basis.v.clone().multiplyScalar(-1),
  ]) {
    group.add(lineBetween(
      faces[0].clone().add(radial.clone().multiplyScalar(outerRadius)),
      faces[1].clone().add(radial.clone().multiplyScalar(outerRadius)),
      material,
    ));
    group.add(lineBetween(
      faces[0].clone().add(radial.clone().multiplyScalar(innerRadius)),
      faces[1].clone().add(radial.clone().multiplyScalar(innerRadius)),
      material,
    ));
  }

  return group;
}

function outlineButterflyValveMarker(position, direction, radius, nominalBore, material) {
  const THREE = three.module;
  const group = new THREE.Group();
  const axis = direction.clone().normalize();
  const basis = radialBasis(axis);
  const bodyRadius = radius * 1.62;
  const bodyLength = clampNumber(radius * 2.25, 0.18, 0.42);
  const boltCount = Math.min(8, Math.max(4, boltCountForNb(nominalBore)));
  const faces = [-0.5, 0.5].map((side) => position.clone().addScaledVector(axis, bodyLength * side));

  for (const face of faces) {
    group.add(outlineRing(face, axis, bodyRadius, material));
    group.add(outlineRing(face, axis, radius * 1.05, material));
  }
  for (const radial of [basis.u, basis.u.clone().multiplyScalar(-1), basis.v, basis.v.clone().multiplyScalar(-1)]) {
    group.add(lineBetween(
      faces[0].clone().add(radial.clone().multiplyScalar(bodyRadius)),
      faces[1].clone().add(radial.clone().multiplyScalar(bodyRadius)),
      material,
    ));
  }

  for (let index = 0; index < boltCount; index += 1) {
    const angle = (Math.PI * 2 * index) / boltCount;
    const radial = basis.u.clone().multiplyScalar(Math.cos(angle))
      .add(basis.v.clone().multiplyScalar(Math.sin(angle)))
      .normalize();
    const lugCenter = position.clone().add(radial.clone().multiplyScalar(bodyRadius * 1.08));
    group.add(lineBetween(
      lugCenter.clone().addScaledVector(axis, -bodyLength * 0.66),
      lugCenter.clone().addScaledVector(axis, bodyLength * 0.66),
      material,
    ));
    group.add(outlineRing(lugCenter, axis, clampNumber(radius * 0.16, 0.016, 0.045), material));
  }

  const stemBase = position.clone().add(basis.v.clone().multiplyScalar(bodyRadius * 0.82));
  const stemTop = position.clone().add(basis.v.clone().multiplyScalar(bodyRadius * 1.9));
  group.add(lineBetween(stemBase, stemTop, material));
  group.add(lineBetween(
    stemTop.clone().addScaledVector(axis, -bodyRadius * 0.42),
    stemTop.clone().addScaledVector(axis, bodyRadius * 0.42),
    material,
  ));
  return group;
}

function butterflyValveAssembly(position, direction, pipeRadius, nominalBore, valveMaterial, boltMaterial, style) {
  const THREE = three.module;
  const axis = direction.clone().normalize();
  const basis = radialBasis(axis);
  const group = new THREE.Group();
  const bodyLength = clampNumber(pipeRadius * 1.85, 0.16, 0.38);
  const bodyRadius = pipeRadius * 1.62;
  const boreRadius = pipeRadius * 0.94;
  const faceRadius = pipeRadius * 1.72;
  const boltCount = Math.min(8, Math.max(4, boltCountForNb(nominalBore)));
  const lugRadius = clampNumber(pipeRadius * 0.16, 0.016, 0.048);
  const lugDistance = bodyRadius * 1.1;
  const shaftRadius = clampNumber(pipeRadius * 0.095, 0.01, 0.032);
  const opacity = style.opacity ?? 1;
  const darkMaterial = style.basic
    ? new THREE.MeshBasicMaterial({ color: 0x1d2426, transparent: opacity < 1, opacity })
    : new THREE.MeshStandardMaterial({
      color: 0x1d2426,
      metalness: Math.min(0.5, style.metalness ?? 0.35),
      roughness: Math.max(0.34, style.roughness ?? 0.36),
      transparent: opacity < 1,
      opacity,
    });
  const discMaterial = style.basic
    ? new THREE.MeshBasicMaterial({ color: 0x4f5554, transparent: opacity < 1, opacity })
    : new THREE.MeshStandardMaterial({
      color: style.detailModel ? 0x74766f : 0x42494b,
      metalness: Math.min(0.58, style.metalness ?? 0.35),
      roughness: Math.max(0.24, style.roughness ?? 0.36),
      transparent: opacity < 1,
      opacity,
    });

  const body = flangePlate(
    position,
    axis,
    bodyRadius,
    boreRadius,
    bodyLength,
    0,
    0,
    0,
    valveMaterial,
  );
  body.castShadow = true;
  body.receiveShadow = true;
  group.add(body);

  const discThickness = clampNumber(pipeRadius * 0.16, 0.014, 0.044);
  const disc = cylinderBetween(
    position.clone().addScaledVector(axis, -discThickness * 0.5),
    position.clone().addScaledVector(axis, discThickness * 0.5),
    boreRadius * 0.86,
    discMaterial,
    40,
  );
  disc.castShadow = true;
  disc.receiveShadow = true;
  group.add(disc);

  const discRib = cylinderBetween(
    position.clone().add(basis.u.clone().multiplyScalar(-boreRadius * 0.72)),
    position.clone().add(basis.u.clone().multiplyScalar(boreRadius * 0.72)),
    clampNumber(pipeRadius * 0.035, 0.005, 0.014),
    boltMaterial,
    10,
  );
  discRib.castShadow = true;
  group.add(discRib);

  for (const offset of [-bodyLength * 0.54, bodyLength * 0.54]) {
    group.add(torusRing(position.clone().addScaledVector(axis, offset), axis, faceRadius, clampNumber(pipeRadius * 0.05, 0.006, 0.016), valveMaterial, 10, 52));
    group.add(torusRing(position.clone().addScaledVector(axis, offset), axis, boreRadius, clampNumber(pipeRadius * 0.028, 0.004, 0.01), darkMaterial, 8, 42));
  }

  for (let index = 0; index < boltCount; index += 1) {
    const angle = (Math.PI * 2 * index) / boltCount;
    const radial = basis.u.clone().multiplyScalar(Math.cos(angle))
      .add(basis.v.clone().multiplyScalar(Math.sin(angle)))
      .normalize();
    const lugCenter = position.clone().add(radial.clone().multiplyScalar(lugDistance));
    const lug = cylinderBetween(
      lugCenter.clone().addScaledVector(axis, -bodyLength * 0.72),
      lugCenter.clone().addScaledVector(axis, bodyLength * 0.72),
      lugRadius,
      valveMaterial,
      16,
    );
    lug.castShadow = true;
    lug.receiveShadow = true;
    group.add(lug);

    const bolt = cylinderBetween(
      lugCenter.clone().addScaledVector(axis, -bodyLength * 0.76),
      lugCenter.clone().addScaledVector(axis, bodyLength * 0.76),
      lugRadius * 0.46,
      darkMaterial,
      12,
    );
    bolt.castShadow = true;
    group.add(bolt);
  }

  const stemBase = position.clone().add(basis.v.clone().multiplyScalar(-bodyRadius * 0.86));
  const stemTop = position.clone().add(basis.v.clone().multiplyScalar(bodyRadius * 1.62));
  const stem = cylinderBetween(stemBase, stemTop, shaftRadius, boltMaterial, 16);
  stem.castShadow = true;
  group.add(stem);

  const actuator = orientedBoxMesh(
    stemTop.clone().add(basis.v.clone().multiplyScalar(bodyRadius * 0.18)),
    basis.u,
    axis,
    basis.v,
    bodyRadius * 1.08,
    Math.max(bodyLength * 0.92, pipeRadius * 0.8),
    bodyRadius * 0.4,
    valveMaterial,
  );
  actuator.castShadow = true;
  actuator.receiveShadow = true;
  group.add(actuator);

  const handle = cylinderBetween(
    stemTop.clone().add(basis.u.clone().multiplyScalar(-bodyRadius * 0.78)).add(basis.v.clone().multiplyScalar(bodyRadius * 0.5)),
    stemTop.clone().add(basis.u.clone().multiplyScalar(bodyRadius * 0.78)).add(basis.v.clone().multiplyScalar(bodyRadius * 0.5)),
    clampNumber(pipeRadius * 0.055, 0.007, 0.02),
    boltMaterial,
    12,
  );
  handle.castShadow = true;
  group.add(handle);

  return group;
}

function outlineReducerMarker(position, direction, radius, material) {
  const THREE = three.module;
  const group = new THREE.Group();
  const axis = direction.clone().normalize();
  const basis = radialBasis(axis);
  const start = position.clone().addScaledVector(axis, -0.17);
  const end = position.clone().addScaledVector(axis, 0.17);
  const startRadius = radius;
  const endRadius = radius * 0.72;
  const railDirections = [
    basis.u,
    basis.u.clone().multiplyScalar(-1),
    basis.v,
    basis.v.clone().multiplyScalar(-1),
  ];

  group.add(outlineRing(start, axis, startRadius, material));
  group.add(outlineRing(end, axis, endRadius, material));
  for (const railDirection of railDirections) {
    group.add(lineBetween(
      start.clone().add(railDirection.clone().multiplyScalar(startRadius)),
      end.clone().add(railDirection.clone().multiplyScalar(endRadius)),
      material,
    ));
  }
  return group;
}

function socketAssembly(position, direction, pipeRadius, fitting, material, style) {
  const THREE = three.module;
  const group = new THREE.Group();
  const radial = socketRadialDirection(direction, fitting);
  const socketRadius = socketRadiusMetres(fitting);
  const socketLength = Math.max(0.12, socketRadius * 3.2);
  const start = position.clone().addScaledVector(radial, pipeRadius * 0.72);
  const end = position.clone().addScaledVector(radial, pipeRadius + socketLength);

  if (style.lineDrawing) {
    group.add(lineBetween(start, end, material));
    group.add(outlineRing(start, radial, socketRadius * 1.05, material));
    group.add(outlineRing(end, radial, socketRadius, material));
    return group;
  }

  const socket = cylinderBetween(start, end, socketRadius, material, 18);
  socket.castShadow = true;
  socket.receiveShadow = true;
  group.add(socket);

  const weld = cylinderBetween(
    position.clone().addScaledVector(radial, pipeRadius * 0.65),
    position.clone().addScaledVector(radial, pipeRadius * 0.86),
    socketRadius * 1.22,
    material,
    18,
  );
  weld.castShadow = true;
  group.add(weld);
  return group;
}

function rollGrooveAssembly(position, direction, pipeRadius, material, style) {
  const THREE = three.module;
  const axis = direction.clone().normalize();
  const markerLength = clampNumber(
    Math.max(ROLL_GROOVE_VISUAL_WIDTH_MM / 1000, pipeRadius * 0.075),
    0.016,
    0.03,
  );
  const grooveSpacing = markerLength * 0.38;

  if (style.lineDrawing) {
    return outlineRollGrooveMarker(position, axis, pipeRadius, material, markerLength);
  }

  const group = new THREE.Group();
  const brightColor = 0xdce3e6;
  const highlightColor = 0xf7fafb;
  const darkColor = 0x15191b;
  const baseMaterialParams = {
    transparent: true,
    opacity: Math.min(0.96, Math.max(0.72, style.opacity ?? 1)),
    metalness: Math.min(0.9, Math.max(0.58, style.metalness ?? 0.35)),
    roughness: Math.min(0.3, Math.max(0.12, style.roughness ?? 0.24)),
  };
  const darkBandMaterial = style.basic
    ? new THREE.MeshBasicMaterial({ color: darkColor, transparent: true, opacity: Math.min(0.92, style.opacity ?? 1) })
    : new THREE.MeshStandardMaterial({
      transparent: true,
      opacity: Math.min(0.92, style.opacity ?? 1),
      color: darkColor,
      metalness: 0.36,
      roughness: 0.46,
    });
  const bandMaterial = style.basic
    ? new THREE.MeshBasicMaterial({ color: brightColor, transparent: baseMaterialParams.transparent, opacity: baseMaterialParams.opacity })
    : new THREE.MeshPhysicalMaterial({
      ...baseMaterialParams,
      color: brightColor,
      clearcoat: 0.76,
      clearcoatRoughness: 0.1,
    });
  const lipMaterial = style.basic
    ? new THREE.MeshBasicMaterial({ color: highlightColor, transparent: baseMaterialParams.transparent, opacity: 1 })
    : new THREE.MeshPhysicalMaterial({
      ...baseMaterialParams,
      color: highlightColor,
      opacity: 1,
      metalness: 0.86,
      roughness: 0.11,
      clearcoat: 0.86,
      clearcoatRoughness: 0.08,
    });
  const lineMaterial = new THREE.LineBasicMaterial({
    color: highlightColor,
    transparent: style.opacity < 1,
    opacity: Math.min(0.94, (style.opacity ?? 1) + 0.08),
  });

  const polishedBand = cylinderBetween(
    position.clone().addScaledVector(axis, -markerLength * 0.5),
    position.clone().addScaledVector(axis, markerLength * 0.5),
    pipeRadius * 1.006,
    bandMaterial,
    48,
  );
  polishedBand.castShadow = true;
  polishedBand.receiveShadow = true;
  group.add(polishedBand);

  const grooveTube = clampNumber(pipeRadius * 0.036, 0.0045, 0.013);
  const lipTube = clampNumber(pipeRadius * 0.014, 0.0025, 0.006);
  for (const offset of [-grooveSpacing * 0.5, grooveSpacing * 0.5]) {
    group.add(torusRing(position.clone().addScaledVector(axis, offset), axis, pipeRadius * 1.012, grooveTube, darkBandMaterial, 8, 48));
  }
  for (const offset of [-markerLength * 0.5, markerLength * 0.5]) {
    group.add(torusRing(position.clone().addScaledVector(axis, offset), axis, pipeRadius * 1.018, lipTube, lipMaterial, 8, 48));
  }
  for (const offset of [-grooveSpacing * 0.5, grooveSpacing * 0.5]) {
    group.add(outlineRing(position.clone().addScaledVector(axis, offset), axis, pipeRadius * 1.026, lineMaterial));
  }
  return group;
}

function socketRadialDirection(direction, fitting = null) {
  const basis = radialBasis(direction);
  const angle = fittingSocketAngle(fitting) * Math.PI / 180;
  const radial = basis.v.clone()
    .multiplyScalar(Math.cos(angle))
    .add(basis.u.clone().multiplyScalar(Math.sin(angle)));
  return radial.normalize();
}

function socketRadiusMetres(fitting) {
  const size = pipeSizeByNb(fittingSocketSizeNb(fitting), "carbon40");
  const maxOd = maxPipeOdMm();
  return Math.max(0.035, (0.055 + (size.od / maxOd) * 0.255) * 0.72);
}

function autoReducerAssembly(reducer, modelPoints, material, style, elbowTrims = null) {
  const THREE = three.module;
  const group = new THREE.Group();
  const joint = modelPoints[reducer.nodeIndex];
  const largeOther = modelPoints[reducer.largeOtherIndex];
  const smallOther = modelPoints[reducer.smallOtherIndex];
  if (!joint || !largeOther || !smallOther) return group;

  const largeDirection = largeOther.clone().sub(joint);
  const smallDirection = smallOther.clone().sub(joint);
  const placementDirection = reducerPlacementSide(reducer) === "large" ? largeDirection.clone() : smallDirection.clone();
  if (largeDirection.length() < 0.0001 || smallDirection.length() < 0.0001) return group;

  const placementLength = placementDirection.length();
  largeDirection.normalize();
  smallDirection.normalize();
  placementDirection.normalize();
  const modelLength = reducerRenderLengthMetres(reducer);
  const halfLength = modelLength * 0.5;
  const startsAtJoint = reducerStartsAtJoint(reducer);
  const startsAfterBend = reducer.kind === "bend";
  let start;
  let end;
  if (startsAfterBend) {
    const placementSegment = reducerPlacementSegment(reducer);
    const renderedBendOffset = elbowTrims?.segment?.get(`${placementSegment.index}:${reducer.nodeIndex}`) ?? (reducerLegOffsetMm(reducer) / 1000);
    const offset = clampNumber(renderedBendOffset, 0.015, Math.max(0.015, placementLength - modelLength));
    start = joint.clone().addScaledVector(placementDirection, offset);
    end = start.clone().addScaledVector(placementDirection, modelLength);
  } else if (startsAtJoint) {
    const offset = clampNumber(
      teeReducerStartOffsetMetres(reducer),
      0.015,
      Math.max(0.015, placementLength - modelLength),
    );
    start = joint.clone().addScaledVector(smallDirection, offset);
    end = joint.clone().addScaledVector(smallDirection, modelLength);
    end.addScaledVector(smallDirection, offset);
  } else {
    start = joint.clone().addScaledVector(largeDirection, halfLength);
    end = joint.clone().addScaledVector(smallDirection, halfLength);
  }
  const largeRadius = pipeRadiusMetres(reducer.largeSegment);
  const smallRadius = pipeRadiusMetres(reducer.smallSegment);
  const startRadius = startsAfterBend && reducerPlacementSide(reducer) === "large"
    ? smallRadius
    : largeRadius;
  const endRadius = startsAfterBend && reducerPlacementSide(reducer) === "large"
    ? largeRadius
    : smallRadius;

  const reducerObject = style.lineDrawing
    ? outlineReducerBetween(start, end, startRadius, endRadius, material)
    : taperedCylinderBetween(start, end, startRadius, endRadius, material, 32);
  if (!style.lineDrawing) {
    reducerObject.castShadow = true;
    const axis = end.clone().sub(start);
    if (axis.length() > 0.0001) {
      axis.normalize();
      const shoulderTube = clampNumber(Math.max(startRadius, endRadius) * 0.045, 0.004, 0.018);
      group.add(torusRing(start, axis, startRadius * 1.01, shoulderTube, material, 8, 44));
      group.add(torusRing(end, axis, endRadius * 1.01, shoulderTube, material, 8, 44));
      const edgeMaterial = new THREE.LineBasicMaterial({
        color: material?.color?.getHex?.() ?? 0x7a4dc2,
        transparent: true,
        opacity: 0.9,
      });
      group.add(outlineRing(start, axis, startRadius, edgeMaterial));
      group.add(outlineRing(end, axis, endRadius, edgeMaterial));
    }
  }
  group.add(reducerObject);
  return group;
}

function outlineReducerBetween(start, end, startRadius, endRadius, material) {
  const THREE = three.module;
  const group = new THREE.Group();
  const axis = end.clone().sub(start);
  if (axis.length() < 0.0001) return group;
  axis.normalize();
  const basis = radialBasis(axis);
  const railDirections = [
    basis.u,
    basis.u.clone().multiplyScalar(-1),
    basis.v,
    basis.v.clone().multiplyScalar(-1),
  ];

  group.add(outlineRing(start, axis, startRadius, material));
  group.add(outlineRing(end, axis, endRadius, material));
  for (const railDirection of railDirections) {
    group.add(lineBetween(
      start.clone().add(railDirection.clone().multiplyScalar(startRadius)),
      end.clone().add(railDirection.clone().multiplyScalar(endRadius)),
      material,
    ));
  }
  return group;
}

function connectionDirections(position, connected, modelPoints) {
  const directions = [];
  for (const connection of connected) {
    const target = modelPoints[connection.other];
    if (!target) continue;
    const direction = target.clone().sub(position);
    if (direction.length() < 0.0001) continue;
    direction.normalize();
    if ([direction.x, direction.y, direction.z].every(Number.isFinite)) {
      directions.push(direction);
    }
  }
  return directions;
}

function connectionRenderEntries(position, connected, modelPoints, segmentData = []) {
  const segmentByIndex = new Map(segmentData.map((segment) => [segment.index, segment]));
  return connected
    .map((connection) => {
      const target = modelPoints[connection.other];
      if (!target) return null;
      const direction = target.clone().sub(position);
      if (direction.length() < 0.0001) return null;
      direction.normalize();
      return {
        connection,
        direction,
        segment: segmentByIndex.get(connection.segmentIndex) ?? null,
      };
    })
    .filter(Boolean)
    .map((entry) => ({
      ...entry,
      radius: entry.segment ? pipeRadiusMetres(entry.segment) : pipeRadiusMetres(),
    }));
}

function mostOppositeRenderEntryPair(entries) {
  if (entries.length < 2) return null;

  let best = null;
  let bestDot = Infinity;
  for (let i = 0; i < entries.length; i += 1) {
    for (let j = i + 1; j < entries.length; j += 1) {
      const dot = entries[i].direction.dot(entries[j].direction);
      if (dot < bestDot) {
        bestDot = dot;
        best = [entries[i], entries[j]];
      }
    }
  }
  return best;
}

function teeNodeAssembly(position, connected, modelPoints, radius, material, segmentData = []) {
  const THREE = three.module;
  const group = new THREE.Group();
  const entries = connectionRenderEntries(position, connected, modelPoints, segmentData);
  const mainPair = mostOppositeRenderEntryPair(entries);
  const coreRadius = Math.max(radius, ...entries.map((entry) => entry.radius));
  const length = Math.max(coreRadius * 3.0, 0.16);

  if (mainPair) {
    const mainRadius = Math.max(...mainPair.map((entry) => entry.radius));
    const main = cylinderBetween(
      position.clone().addScaledVector(mainPair[0].direction, length),
      position.clone().addScaledVector(mainPair[1].direction, length),
      mainRadius,
      material,
      28,
    );
    main.castShadow = true;
    main.receiveShadow = true;
    group.add(main);
  }

  for (const entry of entries) {
    if (mainPair && mainPair.includes(entry)) continue;
    const branchRadius = entry.radius;
    const branchLength = Math.max(length, branchRadius * 4.0, 0.16);
    const branch = cylinderBetween(
      position.clone().addScaledVector(entry.direction, -branchRadius * 0.04),
      position.clone().addScaledVector(entry.direction, branchLength),
      branchRadius,
      material,
      28,
    );
    branch.castShadow = true;
    branch.receiveShadow = true;
    group.add(branch);
  }

  const core = new THREE.Mesh(new THREE.SphereGeometry(coreRadius * 0.64, 24, 16), material);
  core.position.copy(position);
  core.castShadow = true;
  core.receiveShadow = true;
  group.add(core);

  if (mainPair) {
    const ringTube = clampNumber(coreRadius * 0.045, 0.004, 0.014);
    for (const entry of entries) {
      if (mainPair.includes(entry)) continue;
      group.add(torusRing(
        position.clone().addScaledVector(entry.direction, entry.radius * 0.18),
        entry.direction,
        entry.radius * 1.02,
        ringTube,
        material,
        8,
        36,
      ));
    }
  }

  return group;
}

function outlineTeeMarker(position, connected, modelPoints, radius, material, segmentData = []) {
  const THREE = three.module;
  const group = new THREE.Group();
  const entries = connectionRenderEntries(position, connected, modelPoints, segmentData);
  const mainPair = mostOppositeRenderEntryPair(entries);
  const coreRadius = Math.max(radius, ...entries.map((entry) => entry.radius));
  const length = Math.max(coreRadius * 3.8, 0.2);

  if (mainPair) {
    const mainRadius = Math.max(...mainPair.map((entry) => entry.radius));
    group.add(outlinePipeBetween(
      position.clone().addScaledVector(mainPair[0].direction, length),
      position.clone().addScaledVector(mainPair[1].direction, length),
      mainRadius,
      material,
    ));
  }

  for (const entry of entries) {
    if (mainPair && mainPair.includes(entry)) continue;
    const branchRadius = entry.radius;
    const branchLength = Math.max(length, branchRadius * 4.0, 0.2);
    const branchStart = position.clone().addScaledVector(entry.direction, branchRadius * 0.2);
    const branchEnd = position.clone().addScaledVector(entry.direction, branchLength);

    group.add(outlineRing(branchStart, entry.direction, branchRadius, material));
    group.add(outlinePipeBetween(
      branchStart,
      branchEnd,
      branchRadius,
      material,
      { endCap: true },
    ));
  }

  return group;
}

function branchNodeAssembly(nodeIndex, position, connected, modelPoints, segmentData, material) {
  const THREE = three.module;
  const group = new THREE.Group();
  const info = branchNodeInfo(nodeIndex, connected, segmentData);
  const branchSegmentIndexes = new Set((info?.branchEntries ?? []).map((entry) => entry.segment.index));
  if (!branchSegmentIndexes.size) return group;
  const segmentByIndex = new Map(segmentData.map((segment) => [segment.index, segment]));

  for (const connection of connected) {
    if (!branchSegmentIndexes.has(connection.segmentIndex)) continue;
    const segment = segmentByIndex.get(connection.segmentIndex);
    const target = modelPoints[connection.other];
    if (!segment || !target) continue;

    const direction = target.clone().sub(position);
    if (direction.length() < 0.0001) continue;
    direction.normalize();
    const radius = pipeRadiusMetres(segment);
    const collarLength = Math.max(radius * 2.25, 0.055);
    const collar = cylinderBetween(
      position.clone().addScaledVector(direction, radius * 0.02),
      position.clone().addScaledVector(direction, collarLength),
      radius * 1.0,
      material,
      24,
    );
    collar.castShadow = true;
    collar.receiveShadow = true;
    group.add(collar);

    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(radius * 1.015, Math.max(radius * 0.045, 0.003), 8, 28),
      material,
    );
    ring.position.copy(position).addScaledVector(direction, radius * 0.08);
    ring.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), direction);
    ring.castShadow = true;
    ring.receiveShadow = true;
    group.add(ring);
  }

  return group;
}

function outlineBranchMarker(nodeIndex, position, connected, modelPoints, segmentData, material) {
  const group = new three.module.Group();
  const info = branchNodeInfo(nodeIndex, connected, segmentData);
  const branchSegmentIndexes = new Set((info?.branchEntries ?? []).map((entry) => entry.segment.index));
  if (!branchSegmentIndexes.size) return group;
  const segmentByIndex = new Map(segmentData.map((segment) => [segment.index, segment]));

  for (const connection of connected) {
    if (!branchSegmentIndexes.has(connection.segmentIndex)) continue;
    const segment = segmentByIndex.get(connection.segmentIndex);
    const target = modelPoints[connection.other];
    if (!segment || !target) continue;

    const direction = target.clone().sub(position);
    if (direction.length() < 0.0001) continue;
    direction.normalize();
    const radius = pipeRadiusMetres(segment);
    const length = Math.max(radius * 3.1, 0.095);
    const start = position.clone().addScaledVector(direction, radius * 0.16);
    const end = position.clone().addScaledVector(direction, length);
    group.add(outlineRing(start, direction, radius * 1.03, material));
    group.add(outlinePipeBetween(start, end, radius, material, { endCap: true }));
  }

  return group;
}

function mostOppositeDirectionPair(directions) {
  if (directions.length < 2) return null;

  let best = null;
  let bestDot = Infinity;
  for (let i = 0; i < directions.length; i += 1) {
    for (let j = i + 1; j < directions.length; j += 1) {
      const dot = directions[i].dot(directions[j]);
      if (dot < bestDot) {
        bestDot = dot;
        best = [directions[i], directions[j]];
      }
    }
  }
  return best;
}

function outlineRing(position, direction, radius, material) {
  const THREE = three.module;
  const curve = new THREE.EllipseCurve(0, 0, radius, radius, 0, Math.PI * 2, false, 0);
  const points = curve.getPoints(36).map((point) => new THREE.Vector3(point.x, point.y, 0));
  const geometry = new THREE.BufferGeometry().setFromPoints(points);
  const ring = new THREE.LineLoop(geometry, material);
  ring.position.copy(position);
  ring.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), direction.clone().normalize());
  return ring;
}

function torusRing(position, direction, radius, tubeRadius, material, radialSegments = 10, tubularSegments = 48) {
  const THREE = three.module;
  const ring = new THREE.Mesh(
    new THREE.TorusGeometry(radius, tubeRadius, radialSegments, tubularSegments),
    material,
  );
  ring.position.copy(position);
  ring.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), direction.clone().normalize());
  ring.castShadow = true;
  ring.receiveShadow = true;
  return ring;
}

function flangeAssembly(position, direction, pipeRadius, pipeSizeOrNb, flangeMode, flangeStandard, materials) {
  const THREE = three.module;
  const axis = direction.clone().normalize();
  const isSingle = normalizeFlangeMode(flangeMode) === "single";
  const endMount = isSingle && materials?.endMount === true;
  const drilling = flangeDrillingDimensions(flangeStandard, pipeSizeOrNb, pipeRadius);
  const { outerRadius, plateThickness, boltCircleRadius, boltHoleRadius, boltCount } = drilling;
  const gasketThickness = flangeGasketThickness(drilling);
  const plateOffset = plateThickness * 0.5 + gasketThickness * 0.5;
  const totalHalfDepth = isSingle ? plateThickness * 0.5 : plateThickness + gasketThickness * 0.5;
  const innerRadius = pipeRadius * 1.07;
  const boltBodyRadius = boltHoleRadius * 0.72;
  const boltHeadRadius = boltBodyRadius * 1.55;
  const boltHeadDepth = boltBodyRadius * 1.1;
  const gasketOuterRadius = Math.max(pipeRadius * 1.12, Math.min(outerRadius * 0.82, boltCircleRadius - boltHoleRadius * 1.25));
  const raisedFaceOuterRadius = Math.max(pipeRadius * 1.12, Math.min(pipeRadius * 1.38, boltCircleRadius - boltHoleRadius * 1.3));
  const basis = radialBasis(axis);
  const group = new THREE.Group();

  const plateCenters = isSingle ? [position.clone()] : [-1, 1].map((side) => position.clone().addScaledVector(axis, side * plateOffset));
  for (const plateCenter of plateCenters) {
    group.add(
      flangePlate(
        plateCenter,
        axis,
        outerRadius,
        innerRadius,
        plateThickness,
        boltCount,
        boltCircleRadius,
        boltHoleRadius,
        materials.flange,
      ),
    );
  }

  if (isSingle) {
    if (endMount) {
      const neckStart = position.clone().addScaledVector(axis, -plateThickness * 0.52);
      const neckEnd = position.clone().addScaledVector(axis, plateThickness * 0.2);
      const neck = cylinderBetween(neckStart, neckEnd, pipeRadius * 1.035, materials.flange, 32);
      neck.castShadow = true;
      neck.receiveShadow = true;
      group.add(neck);
    }
    group.add(
      flangePlate(
        endMount ? position.clone().addScaledVector(axis, plateThickness * 0.08) : position,
        axis,
        raisedFaceOuterRadius,
        pipeRadius * 1.06,
        boltHeadDepth,
        0,
        0,
        0,
        materials.flange,
      ),
    );
  } else {
    for (const side of [-1, 1]) {
      const faceCenter = position.clone().addScaledVector(axis, side * (totalHalfDepth + boltHeadDepth * 0.5));
      group.add(
        flangePlate(
          faceCenter,
          axis,
          raisedFaceOuterRadius,
          pipeRadius * 1.06,
          boltHeadDepth,
          0,
          0,
          0,
          materials.flange,
        ),
      );
    }

    group.add(
      flangePlate(
        position,
        axis,
        gasketOuterRadius,
        pipeRadius * 1.05,
        gasketThickness,
        0,
        0,
        0,
        materials.gasket,
      ),
    );
  }

  if (!isSingle) {
    for (let index = 0; index < boltCount; index += 1) {
      const angle = (Math.PI * 2 * index) / boltCount + Math.PI / boltCount;
      const radialOffset = basis.u.clone().multiplyScalar(Math.cos(angle) * boltCircleRadius)
        .add(basis.v.clone().multiplyScalar(Math.sin(angle) * boltCircleRadius));
      const boltCenter = position.clone().add(radialOffset);
      const boltDepth = totalHalfDepth + boltHeadDepth;
      const boltStart = boltCenter.clone().addScaledVector(axis, -boltDepth);
      const boltEnd = boltCenter.clone().addScaledVector(axis, boltDepth);
      const bolt = cylinderBetween(boltStart, boltEnd, boltBodyRadius, materials.bolt, 12);
      bolt.castShadow = true;
      group.add(bolt);

      for (const side of [-1, 1]) {
        const headCenter = boltCenter.clone().addScaledVector(axis, side * (totalHalfDepth + boltHeadDepth * 0.42));
        const head = cylinderBetween(
          headCenter.clone().addScaledVector(axis, -side * boltHeadDepth * 0.45),
          headCenter.clone().addScaledVector(axis, side * boltHeadDepth * 0.45),
          boltHeadRadius,
          materials.bolt,
          12,
        );
        head.castShadow = true;
        group.add(head);
      }
    }
  }

  return group;
}

function flangePlate(position, direction, outerRadius, innerRadius, thickness, boltCount, boltCircleRadius, boltHoleRadius, material) {
  const THREE = three.module;
  const shape = new THREE.Shape();
  shape.absarc(0, 0, outerRadius, 0, Math.PI * 2, false);

  const pipeHole = new THREE.Path();
  pipeHole.absarc(0, 0, innerRadius, 0, Math.PI * 2, true);
  shape.holes.push(pipeHole);

  for (let index = 0; index < boltCount; index += 1) {
    const angle = (Math.PI * 2 * index) / boltCount + Math.PI / boltCount;
    const boltHole = new THREE.Path();
    boltHole.absarc(
      Math.cos(angle) * boltCircleRadius,
      Math.sin(angle) * boltCircleRadius,
      boltHoleRadius,
      0,
      Math.PI * 2,
      true,
    );
    shape.holes.push(boltHole);
  }

  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth: thickness,
    bevelEnabled: false,
    curveSegments: 48,
    steps: 1,
  });
  geometry.translate(0, 0, -thickness / 2);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.copy(position);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), direction.clone().normalize());
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function radialBasis(direction) {
  const THREE = three.module;
  const axis = direction.clone().normalize();
  const reference = Math.abs(axis.z) > 0.82 ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 0, 1);
  const u = reference.clone().cross(axis).normalize();
  const v = axis.clone().cross(u).normalize();
  return { u, v };
}

function boltCountForNb(nominalBore) {
  const match = FLANGE_BOLT_COUNTS.find((item) => nominalBore <= item.maxNb);
  return match ? match.count : FLANGE_BOLT_COUNTS[FLANGE_BOLT_COUNTS.length - 1].count;
}

function clampNumber(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function taperedCylinderBetween(start, end, startRadius, endRadius, material, radialSegments) {
  const THREE = three.module;
  const direction = end.clone().sub(start);
  const length = direction.length();
  const geometry = new THREE.CylinderGeometry(endRadius, startRadius, length, radialSegments, 1);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.copy(start).add(end).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction.normalize());
  return mesh;
}

function liftPointMarker3d(position, style) {
  const THREE = three.module;
  const group = new THREE.Group();
  const material = new THREE.LineBasicMaterial({ color: 0xc1121f });
  const length = 0.2;
  group.add(lineBetween(
    position.clone().add(new THREE.Vector3(-length, -length, 0)),
    position.clone().add(new THREE.Vector3(length, length, 0)),
    material,
  ));
  group.add(lineBetween(
    position.clone().add(new THREE.Vector3(length, -length, 0)),
    position.clone().add(new THREE.Vector3(-length, length, 0)),
    material,
  ));
  group.add(lineBetween(
    position.clone().add(new THREE.Vector3(-length, 0, -length)),
    position.clone().add(new THREE.Vector3(length, 0, length)),
    material,
  ));
  group.add(lineBetween(
    position.clone().add(new THREE.Vector3(length, 0, -length)),
    position.clone().add(new THREE.Vector3(-length, 0, length)),
    material,
  ));
  return group;
}

function lugPointMarker3d(position, style) {
  const THREE = three.module;
  const group = new THREE.Group();
  const color = 0x0f766e;

  if (style.lineDrawing) {
    const material = new THREE.LineBasicMaterial({ color });
    const size = 0.16;
    const points = [
      position.clone().add(new THREE.Vector3(0, -size, 0)),
      position.clone().add(new THREE.Vector3(size, 0, 0)),
      position.clone().add(new THREE.Vector3(0, size, 0)),
      position.clone().add(new THREE.Vector3(-size, 0, 0)),
      position.clone().add(new THREE.Vector3(0, -size, 0)),
    ];
    group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), material));
    return group;
  }

  const material = new THREE.MeshStandardMaterial({
    color,
    metalness: 0.32,
    roughness: 0.42,
  });
  const lug = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.2, 0.06), material);
  lug.position.copy(position);
  lug.rotation.z = Math.PI * 0.25;
  lug.castShadow = true;
  group.add(lug);
  return group;
}

function clear3dPipeLabels() {
  three.labels = [];
  previewLabelLayer.innerHTML = "";
  previewLabelLayer.hidden = state.show3dLabels === false;
}

function build3dPipeLabels(segmentData, modelPoints) {
  clear3dPipeLabels();
  previewLabelLayer.hidden = state.show3dLabels === false;
  if (!three.ready || state.show3dLabels === false) return;

  for (const segment of segmentData) {
    const midpoint = modelPoints[segment.from].clone().lerp(modelPoints[segment.to], 0.5);
    const label = document.createElement("div");
    label.className = "pipe-size-label";
    for (const [index, line] of pipePreviewLabelLines(segment).entries()) {
      const element = document.createElement(index === 0 ? "span" : "small");
      element.textContent = line;
      label.append(element);
    }
    previewLabelLayer.append(label);
    three.labels.push({ element: label, point: midpoint });
  }

  const quantities = quantitySummary(segmentData);
  const liftPoint = centreOfGravityData(quantities);
  if (state.showLiftingPoints && liftPoint) {
    const modelPoint = toModelUnits(liftPoint.point);
    const label = document.createElement("div");
    label.className = "pipe-size-label lift-point-label";
    for (const [index, line] of ["COG", formatPointCompact(liftPoint.point)].entries()) {
      const element = document.createElement(index === 0 ? "span" : "small");
      element.textContent = line;
      label.append(element);
    }
    previewLabelLayer.append(label);
    three.labels.push({ element: label, point: new three.module.Vector3(modelPoint.x, modelPoint.y, modelPoint.z) });
  }
  const lugPlan = suggestedLugPlan(quantities, liftPoint);
  if (state.showLiftingPoints && lugPlan) {
    for (const lug of lugPlan.points) {
      const modelPoint = toModelUnits(lug.point);
      const label = document.createElement("div");
      label.className = "pipe-size-label lug-point-label";
      for (const [index, line] of [`LUG ${lug.number}`, `Run ${lug.segment.index + 1}`, `${formatMass(lug.loadKg ?? 0)} kg`].entries()) {
        const element = document.createElement(index === 0 ? "span" : "small");
        element.textContent = line;
        label.append(element);
      }
      previewLabelLayer.append(label);
      three.labels.push({ element: label, point: new three.module.Vector3(modelPoint.x, modelPoint.y, modelPoint.z) });
    }
  }

  update3dLabelPositions();
}

function pipePreviewLabelLines(segment) {
  return [pipeSizeSpecLabel(pipeSizeForSegment(segment))];
}

function update3dLabelPositions(options = {}) {
  if (!three.ready || state.show3dLabels === false || !three.labels.length) return;
  if (three.interacting && options.force !== true) {
    three.labelFrameSkip = (three.labelFrameSkip + 1) % 6;
    if (three.labelFrameSkip !== 0) return;
  }

  const rect = previewStage.getBoundingClientRect();
  for (const label of three.labels) {
    const projected = label.point.clone().project(three.camera);
    const visible = projected.z > -1 && projected.z < 1;
    label.element.hidden = !visible;
    if (!visible) continue;
    const labelWidth = label.element.offsetWidth || 90;
    const labelHeight = label.element.offsetHeight || 24;
    const rawX = (projected.x * 0.5 + 0.5) * rect.width;
    const rawY = (-projected.y * 0.5 + 0.5) * rect.height;
    const x = clampNumber(rawX, labelWidth * 0.5 + 8, Math.max(labelWidth * 0.5 + 8, rect.width - labelWidth * 0.5 - 8));
    const y = clampNumber(rawY, labelHeight * 0.5 + 8, Math.max(labelHeight * 0.5 + 8, rect.height - labelHeight * 0.5 - 8));
    label.element.style.left = `${x}px`;
    label.element.style.top = `${y}px`;
  }
}

function curvedElbowBetween(entry, joint, exit, radius, material, radialSegments = 32) {
  const THREE = three.module;
  const curve = new THREE.QuadraticBezierCurve3(entry, joint, exit);
  const geometry = new THREE.TubeGeometry(curve, 28, radius, radialSegments, false);
  return new THREE.Mesh(geometry, material);
}

function nodeConnections(segmentData) {
  const connections = new Map();
  for (const segment of segmentData) {
    for (const [node, other] of [[segment.from, segment.to], [segment.to, segment.from]]) {
      if (!connections.has(node)) connections.set(node, []);
      connections.get(node).push({ segmentIndex: segment.index, other });
    }
  }
  return connections;
}

function computeGraphElbowTrims(modelPoints, segmentData, connections) {
  const segmentTrims = new Map();
  const elbows = [];
  const smoothNodes = new Set();
  const segmentByIndex = new Map(segmentData.map((segment) => [segment.index, segment]));

  for (const [nodeIndex, connected] of connections.entries()) {
    if (connected.length !== 2) continue;

    const joint = modelPoints[nodeIndex];
    const first = connected[0];
    const second = connected[1];
    const firstSegment = segmentByIndex.get(first.segmentIndex);
    const secondSegment = segmentByIndex.get(second.segmentIndex);
    if (!firstSegment || !secondSegment) continue;
    const radius = Math.max(pipeRadiusMetres(firstSegment), pipeRadiusMetres(secondSegment));

    const firstDirection = modelPoints[first.other].clone().sub(joint);
    const secondDirection = modelPoints[second.other].clone().sub(joint);
    const firstLength = firstDirection.length();
    const secondLength = secondDirection.length();
    if (firstLength < 0.001 || secondLength < 0.001) continue;

    const angle = firstDirection.clone().normalize().angleTo(secondDirection.clone().normalize());
    if (Math.abs(Math.PI - angle) < 0.04) continue;

    const trim = Math.min(Math.max(radius * 4.5, 0.12), firstLength * 0.38, secondLength * 0.38);
    const firstUnit = firstDirection.normalize();
    const secondUnit = secondDirection.normalize();
    segmentTrims.set(`${first.segmentIndex}:${nodeIndex}`, trim);
    segmentTrims.set(`${second.segmentIndex}:${nodeIndex}`, trim);
    elbows.push({
      entry: joint.clone().addScaledVector(firstUnit, trim),
      joint: joint.clone(),
      exit: joint.clone().addScaledVector(secondUnit, trim),
      radius,
    });
    smoothNodes.add(nodeIndex);
  }

  return { segment: segmentTrims, elbows, smoothNodes };
}

function radiusForNode(nodeIndex, connections, segmentByIndex) {
  const connected = connections.get(nodeIndex) ?? [];
  if (!connected.length) return pipeRadiusMetres();

  return Math.max(
    ...connected.map((connection) => {
      const segment = segmentByIndex.get(connection.segmentIndex);
      return segment ? pipeRadiusMetres(segment) : pipeRadiusMetres();
    }),
  );
}

function frameThreeCamera(options = {}) {
  if (!three.ready) return;

  const THREE = three.module;
  const rect = previewStage.getBoundingClientRect();
  const aspect = rect.width / Math.max(1, rect.height);
  const box = new THREE.Box3();

  if (three.spoolGroup && three.spoolGroup.children.length) {
    box.setFromObject(three.spoolGroup);
  } else {
    box.setFromCenterAndSize(new THREE.Vector3(0, 0, 0), new THREE.Vector3(4, 4, 4));
  }

  const size = box.getSize(new THREE.Vector3());
  const center = box.getCenter(new THREE.Vector3());
  const maxDim = Math.max(size.x, size.y, size.z, 5);
  const halfHeight = maxDim * 0.78;
  const halfWidth = halfHeight * aspect;
  const preserveView = three.userMovedCamera && options.reset !== true && three.controls;
  const previousTarget = preserveView ? three.controls.target.clone() : null;
  const previousOffset = preserveView ? three.camera.position.clone().sub(previousTarget) : null;
  const previousTargetOffset = preserveView && three.modelCenter
    ? previousTarget.clone().sub(three.modelCenter)
    : new THREE.Vector3(0, 0, 0);
  const previousZoom = preserveView ? three.camera.zoom : 1;
  const target = preserveView ? center.clone().add(previousTargetOffset) : center.clone();

  three.camera.left = -halfWidth;
  three.camera.right = halfWidth;
  three.camera.top = halfHeight;
  three.camera.bottom = -halfHeight;
  three.camera.near = 0.1;
  three.camera.far = maxDim * 20 + 100;
  if (preserveView && previousOffset.length() > 0.001) {
    const distance = Math.max(previousOffset.length(), maxDim * 1.35);
    three.camera.position.copy(target).add(previousOffset.normalize().multiplyScalar(distance));
    three.camera.zoom = clampNumber(previousZoom, three.controls.minZoom ?? 0.35, three.controls.maxZoom ?? 8);
  } else {
    three.camera.position.copy(target).add(new THREE.Vector3(-maxDim * 1.25, -maxDim * 1.25, -maxDim * 1.25));
    three.camera.zoom = 1;
  }
  three.camera.lookAt(target);
  three.camera.updateProjectionMatrix();

  if (three.controls) {
    three.controls.target.copy(target);
    three.controls.update();
  }
  three.modelCenter = center.clone();
}

function disposeObject3d(object) {
  object.traverse((child) => {
    if (child.geometry) child.geometry.dispose();
    if (child.material) {
      if (Array.isArray(child.material)) {
        child.material.forEach((material) => material.dispose());
      } else {
        child.material.dispose();
      }
    }
  });
}

function renderFallbackPreview() {
  if (fallbackCanvas.hidden) return;

  const style = fallbackPreviewStyle();
  const { ctx, width, height } = resizeCanvas(fallbackCanvas);
  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = style.background;
  ctx.fillRect(0, 0, width, height);

  const projected = state.points.map(projectPreviewPoint);
  const minX = Math.min(...projected.map((point) => point.x));
  const maxX = Math.max(...projected.map((point) => point.x));
  const minY = Math.min(...projected.map((point) => point.y));
  const maxY = Math.max(...projected.map((point) => point.y));
  const span = Math.max(maxX - minX, maxY - minY, 1);
  const scale = Math.min(width, height) / (span * 1.55);
  const offset = {
    x: width * 0.5 - ((minX + maxX) * 0.5) * scale,
    y: height * 0.55 - ((minY + maxY) * 0.5) * scale,
  };
  const toScreen = (point) => ({
    x: point.x * scale + offset.x,
    y: point.y * scale + offset.y,
    depth: point.depth,
  });

  drawFallbackGrid(ctx, width, height, style);

  const pipeWidth = Math.max(12, visualPipeWidth() * 1.02);
  const connectionCounts = nodeConnections(segments());
  const fallbackSegments = segments()
    .map((segment) => ({
      ...segment,
      start2: toScreen(projectPreviewPoint(segment.start)),
      end2: toScreen(projectPreviewPoint(segment.end)),
      depth: (projectPreviewPoint(segment.start).depth + projectPreviewPoint(segment.end).depth) * 0.5,
    }))
    .sort((a, b) => a.depth - b.depth);

  ctx.save();
  ctx.lineCap = "butt";
  ctx.lineJoin = "round";

  for (const segment of fallbackSegments) {
    const segmentPipeWidth = Math.max(12, visualPipeWidth(segment) * 1.02);
    drawFallbackPreviewPipe(ctx, segment, segmentPipeWidth, style);

    if (state.show3dLabels !== false) {
      drawFallbackPipeSizeLabel(ctx, segment, {
        x: (segment.start2.x + segment.end2.x) * 0.5,
        y: (segment.start2.y + segment.end2.y) * 0.5,
      });
    }
  }

  drawFallbackFlushEndCaps(ctx, fallbackSegments, connectionCounts, style);

  for (const fitting of state.fittings) {
    const segment = segments().find((item) => item.index === fitting.segmentIndex);
    if (!segment) continue;
    const start2 = toScreen(projectPreviewPoint(segment.start));
    const end2 = toScreen(projectPreviewPoint(segment.end));
    const point2 = toScreen(projectPreviewPoint(fittingDisplayPoint(segment, fitting)));
    drawFitting3dFallback(ctx, fitting, start2, end2, point2, pipeWidth, style);
  }

  drawAutoReducersFallback(ctx, fallbackSegments, connectionCounts, style);
  drawFallbackTeeMarkers(ctx, fallbackSegments, connectionCounts, style, pipeWidth);
  if (state.showLiftingPoints) {
    drawSuggestedLugsFallback(ctx, toScreen, quantitySummary(), style);
    drawFallbackLiftPoint(ctx, toScreen, quantitySummary(), style);
  }

  for (const [index, point] of state.points.entries()) {
    const connectionCount = connectionCounts.get(index)?.length ?? 0;
    if ((connectionCount === 2 || connectionCount >= 3) && index !== activePointIndex()) continue;
    if (connectionCount <= 1 && index !== activePointIndex() && index !== state.selectedPoint) continue;

    const point2 = toScreen(projectPreviewPoint(point));
    ctx.beginPath();
    ctx.fillStyle = style.nodeFill;
    ctx.strokeStyle = style.nodeStroke;
    ctx.lineWidth = 2;
    ctx.arc(point2.x, point2.y, pipeWidth * 0.38, 0, Math.PI * 2);
    if (!style.outline) ctx.fill();
    ctx.stroke();
  }

  ctx.restore();
}

function projectPreviewPoint(point) {
  return {
    x: (point.x - point.y) * ISO_COS,
    y: (point.x + point.y) * ISO_SIN - point.z,
    depth: (point.x + point.y) * ISO_COS + point.z * 0.35,
  };
}

function drawFallbackGrid(ctx, width, height, style = {}) {
  ctx.save();
  ctx.strokeStyle = style.gridStroke ?? "rgba(99, 115, 109, 0.16)";
  ctx.lineWidth = 1;
  const spacing = 32;
  for (let x = -width; x < width * 2; x += spacing) {
    drawLine(ctx, { x, y: height * 0.78 }, { x: x + height, y: 0 });
  }
  for (let x = -width; x < width * 2; x += spacing) {
    drawLine(ctx, { x, y: height * 0.78 }, { x: x - height, y: 0 });
  }
  ctx.restore();
}

function fallbackPreviewStyle() {
  const mode = normalizePreviewMode(state.previewMode);
  const stainless = normalizePipeSpec(state.pipeSpec) !== "carbon40";
  const darkTheme = isDarkAppTheme();
  const carbonStyle = {
    background: darkTheme ? "#071018" : "#f8fbfb",
    shadow: darkTheme ? "rgba(0, 0, 0, 0.42)" : "rgba(31, 42, 47, 0.1)",
    gridStroke: darkTheme ? "rgba(0, 174, 255, 0.13)" : undefined,
    pipeStops: ["#22282a", "#596164", "#171b1d"],
    highlight: darkTheme ? "rgba(19, 216, 255, 0.45)" : "rgba(255, 255, 255, 0.56)",
    fittingStroke: darkTheme ? "#6f8490" : "#3f484b",
    fittingFill: darkTheme ? "#1a2730" : "#eef2f0",
    nodeFill: darkTheme ? "#111d25" : "#4b5355",
    nodeStroke: darkTheme ? "#22c7ff" : "#1d2325",
    outline: false,
    ghost: false,
  };
  const stainlessStyle = {
    background: darkTheme ? "#071018" : "#fcfefe",
    shadow: darkTheme ? "rgba(0, 0, 0, 0.34)" : "rgba(83, 98, 102, 0.07)",
    gridStroke: darkTheme ? "rgba(0, 174, 255, 0.13)" : undefined,
    pipeStops: ["#d6dee1", "#ffffff", "#c4cdd1"],
    highlight: "rgba(255, 255, 255, 1)",
    fittingStroke: darkTheme ? "#dce8ee" : "#aab5b9",
    fittingFill: darkTheme ? "#e6eef2" : "#ffffff",
    nodeFill: darkTheme ? "#f8fbfb" : "#f8fbfb",
    nodeStroke: darkTheme ? "#9fdfff" : "#a0abb0",
    outline: false,
    ghost: false,
  };
  const styles = {
    carbon: stainless ? stainlessStyle : carbonStyle,
    black: carbonStyle,
    workshop: {
      background: "#e8e3d7",
      shadow: "rgba(54, 49, 40, 0.13)",
      gridStroke: "rgba(109, 101, 84, 0.1)",
      pipeStops: ["#9f9b90", "#efeadf", "#85867f"],
      highlight: "rgba(255, 255, 255, 0.72)",
      fittingStroke: "#746d5d",
      fittingFill: "#c9bfaa",
      nodeFill: "#b8ad93",
      nodeStroke: "#504a40",
      outline: false,
      ghost: false,
    },
    stainless: stainlessStyle,
    red: {
      background: "#fff8f7",
      shadow: "rgba(127, 29, 29, 0.12)",
      pipeStops: ["#7f1d1d", "#ef4444", "#991b1b"],
      highlight: "rgba(255, 226, 222, 0.72)",
      fittingStroke: "#991b1b",
      fittingFill: "#fee2e2",
      nodeFill: "#ef4444",
      nodeStroke: "#7f1d1d",
      outline: false,
      ghost: false,
    },
    ghost: {
      background: "#f8fbfb",
      shadow: "rgba(31, 42, 47, 0.04)",
      pipeStops: ["rgba(129, 151, 148, 0.34)", "rgba(192, 214, 211, 0.46)", "rgba(104, 123, 121, 0.34)"],
      highlight: "rgba(255, 255, 255, 0.52)",
      fittingStroke: "rgba(82, 102, 99, 0.72)",
      fittingFill: "rgba(238, 242, 240, 0.38)",
      nodeFill: "rgba(129, 151, 148, 0.38)",
      nodeStroke: "rgba(64, 78, 76, 0.65)",
      outline: false,
      ghost: true,
    },
    outline: {
      background: "#fffafa",
      shadow: "rgba(0, 0, 0, 0)",
      pipeStops: ["#c1121f", "#c1121f", "#c1121f"],
      highlight: "#c1121f",
      fittingStroke: "#c1121f",
      fittingFill: "rgba(255, 255, 255, 0)",
      nodeFill: "rgba(255, 255, 255, 0)",
      nodeStroke: "#c1121f",
      outline: true,
      ghost: false,
    },
    cad: {
      background: "#050706",
      shadow: "rgba(0, 0, 0, 0)",
      gridStroke: "rgba(51, 255, 102, 0.16)",
      pipeStops: ["#33ff66", "#33ff66", "#33ff66"],
      highlight: "#33ff66",
      fittingStroke: "#33ff66",
      fittingFill: "rgba(0, 0, 0, 0)",
      nodeFill: "rgba(0, 0, 0, 0)",
      nodeStroke: "#d4d28a",
      weldStroke: "#6be6ff",
      outline: true,
      ghost: false,
    },
  };
  return styles[mode] ?? styles.carbon;
}

function drawFallbackPreviewPipe(ctx, segment, segmentPipeWidth, style) {
  if (style.outline) {
    const dx = segment.end2.x - segment.start2.x;
    const dy = segment.end2.y - segment.start2.y;
    const length = Math.hypot(dx, dy);
    if (length < 0.001) return;
    const along = { x: dx / length, y: dy / length };
    const normal = { x: -along.y, y: along.x };
    const halfWidth = segmentPipeWidth * 0.5;

    ctx.strokeStyle = style.pipeStops[0];
    ctx.lineCap = "round";
    ctx.lineWidth = 2.5;
    drawLine(
      ctx,
      { x: segment.start2.x + normal.x * halfWidth, y: segment.start2.y + normal.y * halfWidth },
      { x: segment.end2.x + normal.x * halfWidth, y: segment.end2.y + normal.y * halfWidth },
    );
    drawLine(
      ctx,
      { x: segment.start2.x - normal.x * halfWidth, y: segment.start2.y - normal.y * halfWidth },
      { x: segment.end2.x - normal.x * halfWidth, y: segment.end2.y - normal.y * halfWidth },
    );
    ctx.globalAlpha = 0.55;
    ctx.lineWidth = 1.5;
    drawLine(
      ctx,
      { x: segment.start2.x + normal.x * halfWidth * 0.42, y: segment.start2.y + normal.y * halfWidth * 0.42 },
      { x: segment.end2.x + normal.x * halfWidth * 0.42, y: segment.end2.y + normal.y * halfWidth * 0.42 },
    );
    ctx.globalAlpha = 1;
    ctx.lineCap = "butt";

    drawFallbackPipeSectionRing(ctx, segment.start2, Math.atan2(dy, dx), halfWidth, 0.22);
    drawFallbackPipeSectionRing(ctx, segment.end2, Math.atan2(dy, dx), halfWidth, 0.22);
    const sectionCount = Math.min(4, Math.floor(length / 155));
    for (let index = 1; index <= sectionCount; index += 1) {
      const t = index / (sectionCount + 1);
      drawFallbackPipeSectionRing(ctx, {
        x: segment.start2.x + dx * t,
        y: segment.start2.y + dy * t,
      }, Math.atan2(dy, dx), halfWidth, 0.14);
    }
    return;
  }

  ctx.lineWidth = segmentPipeWidth + 7;
  ctx.strokeStyle = style.shadow;
  drawLine(ctx, { x: segment.start2.x + 4, y: segment.start2.y + 6 }, { x: segment.end2.x + 4, y: segment.end2.y + 6 });

  const gradient = ctx.createLinearGradient(segment.start2.x, segment.start2.y, segment.end2.x, segment.end2.y);
  gradient.addColorStop(0, style.pipeStops[0]);
  gradient.addColorStop(0.52, style.pipeStops[1]);
  gradient.addColorStop(1, style.pipeStops[2]);
  ctx.lineWidth = segmentPipeWidth;
  ctx.strokeStyle = gradient;
  drawLine(ctx, segment.start2, segment.end2);

  ctx.lineWidth = Math.max(2, segmentPipeWidth * 0.18);
  ctx.strokeStyle = style.highlight;
  drawLine(ctx, segment.start2, segment.end2);
}

function drawFallbackFlushEndCaps(ctx, fallbackSegments, connections, style) {
  ctx.save();
  ctx.lineCap = "butt";
  ctx.strokeStyle = style.pipeStops[0];

  for (const segment of fallbackSegments) {
    const segmentPipeWidth = Math.max(12, visualPipeWidth(segment) * 1.02);
    const capLineWidth = style.outline ? 2.5 : Math.max(2, segmentPipeWidth * 0.2);
    const capHalf = style.outline ? segmentPipeWidth * 0.52 : segmentPipeWidth * 0.52;

    for (const [nodeIndex, point, other] of [[segment.from, segment.start2, segment.end2], [segment.to, segment.end2, segment.start2]]) {
      if ((connections.get(nodeIndex)?.length ?? 0) !== 1) continue;
      const angle = Math.atan2(point.y - other.y, point.x - other.x);
      const normal = { x: -Math.sin(angle), y: Math.cos(angle) };

      if (style.outline) {
        drawFallbackPipeEndRing(ctx, point, angle, capHalf, Math.max(4, capHalf * 0.38));
      } else {
        ctx.lineWidth = capLineWidth;
        drawLine(
          ctx,
          { x: point.x + normal.x * capHalf, y: point.y + normal.y * capHalf },
          { x: point.x - normal.x * capHalf, y: point.y - normal.y * capHalf },
        );
      }
    }
  }

  ctx.restore();
}

function drawFallbackPipeEndRing(ctx, point, angle, radius, minorRadius) {
  drawFallbackPipeSectionRing(ctx, point, angle, radius, 1, minorRadius, 2.5);
}

function drawFallbackPipeSectionRing(ctx, point, angle, radius, alpha = 1, minorRadius = Math.max(4, radius * 0.36), lineWidth = 1.5) {
  ctx.save();
  ctx.translate(point.x, point.y);
  ctx.rotate(angle);
  ctx.globalAlpha *= alpha;
  ctx.lineWidth = lineWidth;
  ctx.beginPath();
  ctx.ellipse(0, 0, minorRadius, radius, 0, 0, Math.PI * 2);
  ctx.stroke();
  ctx.restore();
}

function drawAutoReducersFallback(ctx, fallbackSegments, connections, style) {
  const reducerData = autoReducerTransitions(segments());
  if (!reducerData.length) return;

  const screenSegments = new Map(fallbackSegments.map((segment) => [segment.index, segment]));
  ctx.save();
  ctx.lineCap = "butt";
  ctx.lineJoin = "round";
  ctx.strokeStyle = style.fittingStroke;
  ctx.fillStyle = style.fittingFill;
  ctx.lineWidth = style.outline ? 3 : 4;

  for (const reducer of reducerData) {
    const largeSegment = screenSegments.get(reducer.largeSegment.index);
    const smallSegment = screenSegments.get(reducer.smallSegment.index);
    const firstSegment = screenSegments.get(reducer.firstSegmentIndex);
    if (!largeSegment || !smallSegment || !firstSegment) continue;

    const joint = firstSegment.from === reducer.nodeIndex ? firstSegment.start2 : firstSegment.end2;
    const largeOther = largeSegment.from === reducer.nodeIndex ? largeSegment.end2 : largeSegment.start2;
    const smallOther = smallSegment.from === reducer.nodeIndex ? smallSegment.end2 : smallSegment.start2;
    const placementOther = reducerPlacementSide(reducer) === "large" ? largeOther : smallOther;
    const startsAtJoint = reducerStartsAtJoint(reducer);
    const startsAfterBend = reducer.kind === "bend";
    const along = startsAtJoint || startsAfterBend
      ? normalizeScreenVector({ x: placementOther.x - joint.x, y: placementOther.y - joint.y })
      : normalizeScreenVector({ x: smallOther.x - largeOther.x, y: smallOther.y - largeOther.y });
    const normal = { x: -along.y, y: along.x };
    const length = 30;
    const largeWidth = Math.max(10, visualPipeWidth(reducer.largeSegment));
    const smallWidth = Math.max(7, visualPipeWidth(reducer.smallSegment));
    const startWidth = startsAfterBend && reducerPlacementSide(reducer) === "large" ? smallWidth : largeWidth;
    const endWidth = startsAfterBend && reducerPlacementSide(reducer) === "large" ? largeWidth : smallWidth;
    let start;
    let end;
    if (startsAfterBend) {
      const offset = reducerScreenOffsetPixels(reducer, joint, placementOther, length);
      start = { x: joint.x + along.x * offset, y: joint.y + along.y * offset };
      end = { x: start.x + along.x * length, y: start.y + along.y * length };
    } else if (startsAtJoint) {
      start = { x: joint.x + along.x * 2, y: joint.y + along.y * 2 };
      end = { x: joint.x + along.x * length, y: joint.y + along.y * length };
    } else {
      start = { x: joint.x - along.x * length * 0.5, y: joint.y - along.y * length * 0.5 };
      end = { x: joint.x + along.x * length * 0.5, y: joint.y + along.y * length * 0.5 };
    }

    ctx.beginPath();
    ctx.moveTo(start.x + normal.x * startWidth * -0.5, start.y + normal.y * startWidth * -0.5);
    ctx.lineTo(end.x + normal.x * endWidth * -0.5, end.y + normal.y * endWidth * -0.5);
    ctx.lineTo(end.x + normal.x * endWidth * 0.5, end.y + normal.y * endWidth * 0.5);
    ctx.lineTo(start.x + normal.x * startWidth * 0.5, start.y + normal.y * startWidth * 0.5);
    ctx.closePath();
    if (!style.outline) ctx.fill();
    ctx.stroke();
  }

  ctx.restore();
}

function drawFallbackLiftPoint(ctx, toScreen, quantities, style) {
  const liftPoint = centreOfGravityData(quantities);
  if (!liftPoint) return;

  const point = toScreen(projectPreviewPoint(liftPoint.point));

  ctx.save();
  ctx.strokeStyle = "#c1121f";
  ctx.lineWidth = 4;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(point.x - 11, point.y - 11);
  ctx.lineTo(point.x + 11, point.y + 11);
  ctx.moveTo(point.x + 11, point.y - 11);
  ctx.lineTo(point.x - 11, point.y + 11);
  ctx.stroke();

  if (state.show3dLabels !== false) {
    ctx.font = "900 12px Inter, system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.lineWidth = 5;
    ctx.strokeStyle = style.background;
    ctx.fillStyle = "#c1121f";
    ctx.strokeText("COG", point.x, point.y - 24);
    ctx.fillText("COG", point.x, point.y - 24);
  }
  ctx.restore();
}

function drawSuggestedLugsFallback(ctx, toScreen, quantities, style) {
  const lugPlan = suggestedLugPlan(quantities);
  if (!lugPlan) return;

  if (state.show3dLabels !== false) {
    const dimensionLayout = {
      labels: [],
      lines: [],
      viewport: dimensionViewport(ctx, 18),
      pipes: quantities.segments.map(({ segment }) => ({
        index: segment.index,
        start: toScreen(projectPreviewPoint(segment.start)),
        end: toScreen(projectPreviewPoint(segment.end)),
      })),
    };

    for (const [index, lug] of lugPlan.points.entries()) {
      const start = toScreen(projectPreviewPoint(lug.segment.start));
      const point = toScreen(projectPreviewPoint(lug.point));
      const distanceMm = Number.isFinite(lug.distanceFromRunStartMm)
        ? lug.distanceFromRunStartMm
        : pointLength(subtractPoints(lug.point, lug.segment.start));
      drawLugDimensionLine(ctx, start, point, lug.segment.index, `LUG ${lug.number ?? index + 1} ${formatLength(distanceMm)} mm`, dimensionLayout, index);
    }
  }

  ctx.save();
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.font = "900 11px Inter, system-ui, sans-serif";

  for (const lug of lugPlan.points) {
    const point = toScreen(projectPreviewPoint(lug.point));
    ctx.fillStyle = style.outline ? "rgba(255, 255, 255, 0)" : "#d8f1ed";
    ctx.strokeStyle = "#0f766e";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(point.x, point.y - 11);
    ctx.lineTo(point.x + 11, point.y);
    ctx.lineTo(point.x, point.y + 11);
    ctx.lineTo(point.x - 11, point.y);
    ctx.closePath();
    if (!style.outline) ctx.fill();
    ctx.stroke();

    if (state.show3dLabels !== false) {
      const label = `LUG ${lug.number}`;
      ctx.lineWidth = 5;
      ctx.strokeStyle = style.background;
      ctx.fillStyle = "#0f766e";
      ctx.strokeText(label, point.x, point.y - 25);
      ctx.fillText(label, point.x, point.y - 25);
    }
  }

  ctx.restore();
}

function drawFallbackTeeMarkers(ctx, fallbackSegments, connections, style, pipeWidth) {
  const segmentByIndex = new Map(fallbackSegments.map((segment) => [segment.index, segment]));
  ctx.save();
  ctx.lineCap = "butt";
  ctx.lineJoin = "round";
  ctx.strokeStyle = style.pipeStops[0];
  ctx.lineWidth = style.outline ? 3 : Math.max(7, pipeWidth * 0.48);

  for (const [nodeIndex, connected] of connections.entries()) {
    if (connected.length < 3) continue;
    const firstSegment = segmentByIndex.get(connected[0].segmentIndex);
    if (!firstSegment) continue;
    const joint = firstSegment.from === nodeIndex ? firstSegment.start2 : firstSegment.end2;

    if (nodeConnectionType(nodeIndex) === "branch") {
      const info = branchNodeInfo(nodeIndex, connected, segments());
      const branchSegmentIndexes = new Set((info?.branchEntries ?? []).map((entry) => entry.segment.index));
      ctx.strokeStyle = style.weldStroke ?? style.fittingStroke;
      ctx.lineWidth = style.outline ? 3 : Math.max(3, pipeWidth * 0.22);

      for (const connection of connected) {
        if (!branchSegmentIndexes.has(connection.segmentIndex)) continue;
        const segment = segmentByIndex.get(connection.segmentIndex);
        if (!segment) continue;
        const other = segment.from === nodeIndex ? segment.end2 : segment.start2;
        const vector = normalizeScreenVector({ x: other.x - joint.x, y: other.y - joint.y });
        const normal = { x: -vector.y, y: vector.x };
        const weldHalf = Math.max(7, visualPipeWidth(segment) * 0.68);
        const weldOffset = Math.max(5, visualPipeWidth(segment) * 0.24);
        drawLine(
          ctx,
          { x: joint.x + vector.x * weldOffset + normal.x * -weldHalf, y: joint.y + vector.y * weldOffset + normal.y * -weldHalf },
          { x: joint.x + vector.x * weldOffset + normal.x * weldHalf, y: joint.y + vector.y * weldOffset + normal.y * weldHalf },
        );
        drawLine(ctx, joint, { x: joint.x + vector.x * 22, y: joint.y + vector.y * 22 });
      }

      ctx.strokeStyle = style.pipeStops[0];
      ctx.lineWidth = style.outline ? 3 : Math.max(7, pipeWidth * 0.48);
      continue;
    }

    for (const connection of connected) {
      const segment = segmentByIndex.get(connection.segmentIndex);
      if (!segment) continue;
      const other = segment.from === nodeIndex ? segment.end2 : segment.start2;
      const vector = normalizeScreenVector({ x: other.x - joint.x, y: other.y - joint.y });
      drawLine(
        ctx,
        { x: joint.x - vector.x * 2, y: joint.y - vector.y * 2 },
        { x: joint.x + vector.x * 24, y: joint.y + vector.y * 24 },
      );
    }

    if (!style.outline) {
      ctx.strokeStyle = style.highlight;
      ctx.lineWidth = Math.max(2, pipeWidth * 0.16);
      for (const connection of connected) {
        const segment = segmentByIndex.get(connection.segmentIndex);
        if (!segment) continue;
        const other = segment.from === nodeIndex ? segment.end2 : segment.start2;
        const vector = normalizeScreenVector({ x: other.x - joint.x, y: other.y - joint.y });
        drawLine(ctx, joint, { x: joint.x + vector.x * 20, y: joint.y + vector.y * 20 });
      }
      ctx.strokeStyle = style.pipeStops[0];
      ctx.lineWidth = Math.max(7, pipeWidth * 0.48);
    }
  }

  ctx.restore();
}

function drawFitting3dFallback(ctx, fitting, start, end, point, pipeWidth, style = fallbackPreviewStyle()) {
  const angle = Math.atan2(end.y - start.y, end.x - start.x);
  const along = { x: Math.cos(angle), y: Math.sin(angle) };
  const normal = { x: -Math.sin(angle), y: Math.cos(angle) };

  ctx.save();
  ctx.translate(point.x, point.y);
  ctx.strokeStyle = style.fittingStroke;
  ctx.fillStyle = style.fittingFill;
  ctx.lineWidth = 4;

  if (fitting.type === "valve") {
    const body = Math.max(18, pipeWidth * 0.92);
    const length = Math.max(20, pipeWidth * 0.82);
    ctx.beginPath();
    ctx.ellipse(0, 0, length * 0.56, body * 0.62, angle, 0, Math.PI * 2);
    if (!style.outline) {
      ctx.fill();
    }
    ctx.stroke();
    for (const offset of [-length * 0.52, length * 0.52]) {
      ctx.beginPath();
      ctx.moveTo(along.x * offset + normal.x * body * -0.7, along.y * offset + normal.y * body * -0.7);
      ctx.lineTo(along.x * offset + normal.x * body * 0.7, along.y * offset + normal.y * body * 0.7);
      ctx.stroke();
    }
    ctx.lineWidth = 2.4;
    for (const side of [-1, 1]) {
      for (const offset of [-0.42, 0.42]) {
        ctx.beginPath();
        ctx.arc(along.x * length * offset + normal.x * body * side * 0.52, along.y * length * offset + normal.y * body * side * 0.52, 2.4, 0, Math.PI * 2);
        if (style.outline) ctx.stroke();
        else ctx.fill();
      }
    }
    ctx.beginPath();
    ctx.moveTo(normal.x * body * 0.58, normal.y * body * 0.58);
    ctx.lineTo(normal.x * body * 1.32, normal.y * body * 1.32);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(normal.x * body * 1.32 + along.x * body * -0.38, normal.y * body * 1.32 + along.y * body * -0.38);
    ctx.lineTo(normal.x * body * 1.32 + along.x * body * 0.38, normal.y * body * 1.32 + along.y * body * 0.38);
    ctx.stroke();
  } else if (fitting.type === "reducer") {
    ctx.beginPath();
    ctx.moveTo(along.x * -15 + normal.x * pipeWidth * -0.7, along.y * -15 + normal.y * pipeWidth * -0.7);
    ctx.lineTo(along.x * 15 + normal.x * pipeWidth * -0.38, along.y * 15 + normal.y * pipeWidth * -0.38);
    ctx.lineTo(along.x * 15 + normal.x * pipeWidth * 0.38, along.y * 15 + normal.y * pipeWidth * 0.38);
    ctx.lineTo(along.x * -15 + normal.x * pipeWidth * 0.7, along.y * -15 + normal.y * pipeWidth * 0.7);
    ctx.closePath();
    if (!style.outline) ctx.fill();
    ctx.stroke();
  } else if (fitting.type === "flange") {
    const offsets = fittingFlangeMode(fitting) === "single" ? [0] : [-8, 8];
    for (const offset of offsets) {
      ctx.beginPath();
      ctx.moveTo(along.x * offset + normal.x * pipeWidth * -0.8, along.y * offset + normal.y * pipeWidth * -0.8);
      ctx.lineTo(along.x * offset + normal.x * pipeWidth * 0.8, along.y * offset + normal.y * pipeWidth * 0.8);
      ctx.stroke();
    }
    ctx.fillStyle = style.nodeStroke;
    for (const offset of offsets) {
      for (const side of [-0.52, 0.52]) {
        ctx.beginPath();
        ctx.arc(along.x * offset + normal.x * pipeWidth * side, along.y * offset + normal.y * pipeWidth * side, 2.5, 0, Math.PI * 2);
        if (style.outline) ctx.stroke();
        else ctx.fill();
      }
    }
  } else if (fitting.type === "rollGroove") {
    const grooveHalfSpan = Math.max(4, pipeWidth * 0.16);
    const shoulderHalfSpan = grooveHalfSpan * 1.9;
    const halfWidth = pipeWidth * 0.7;
    ctx.lineCap = "butt";
    const silverStroke = style.outline ? style.fittingStroke : "#d9e0e3";
    const darkStroke = style.outline ? style.fittingStroke : "#171d20";
    ctx.strokeStyle = silverStroke;
    ctx.lineWidth = style.outline ? 2.4 : 3.2;
    for (const offset of [-shoulderHalfSpan, shoulderHalfSpan]) {
      ctx.beginPath();
      ctx.moveTo(along.x * offset + normal.x * -halfWidth, along.y * offset + normal.y * -halfWidth);
      ctx.lineTo(along.x * offset + normal.x * halfWidth, along.y * offset + normal.y * halfWidth);
      ctx.stroke();
    }
    ctx.strokeStyle = darkStroke;
    ctx.lineWidth = style.outline ? 3 : 3.8;
    for (const offset of [-grooveHalfSpan, grooveHalfSpan]) {
      ctx.beginPath();
      ctx.moveTo(along.x * offset + normal.x * -halfWidth, along.y * offset + normal.y * -halfWidth);
      ctx.lineTo(along.x * offset + normal.x * halfWidth, along.y * offset + normal.y * halfWidth);
      ctx.stroke();
    }
    ctx.font = "900 9px Inter, system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.lineWidth = 4;
    ctx.strokeStyle = style.background;
    ctx.fillStyle = style.outline ? style.fittingStroke : "#526067";
    const labelX = normal.x * (pipeWidth * 0.95 + 8);
    const labelY = normal.y * (pipeWidth * 0.95 + 8);
    ctx.strokeText("RG", labelX, labelY);
    ctx.fillText("RG", labelX, labelY);
  } else if (fitting.type === "socket") {
    const socketAngle = fittingSocketAngle(fitting) * Math.PI / 180;
    const branch = normalizeScreenVector({
      x: normal.x * Math.cos(socketAngle) + along.x * Math.sin(socketAngle),
      y: normal.y * Math.cos(socketAngle) + along.y * Math.sin(socketAngle),
    });
    const branchLength = Math.max(22, pipeWidth * 1.18);
    const socketRadius = Math.max(5, pipeWidth * 0.28);
    ctx.lineCap = "butt";
    ctx.lineWidth = style.outline ? 3 : 4;
    drawLine(
      ctx,
      { x: branch.x * pipeWidth * 0.25, y: branch.y * pipeWidth * 0.25 },
      { x: branch.x * branchLength, y: branch.y * branchLength },
    );
    ctx.beginPath();
    ctx.arc(branch.x * (branchLength + socketRadius * 0.25), branch.y * (branchLength + socketRadius * 0.25), socketRadius, 0, Math.PI * 2);
    if (!style.outline) ctx.fill();
    ctx.stroke();
  } else {
    const offsets = [-4, 4];
    for (const offset of offsets) {
      ctx.beginPath();
      ctx.moveTo(along.x * offset + normal.x * pipeWidth * -0.72, along.y * offset + normal.y * pipeWidth * -0.72);
      ctx.lineTo(along.x * offset + normal.x * pipeWidth * 0.72, along.y * offset + normal.y * pipeWidth * 0.72);
      ctx.stroke();
    }
  }

  ctx.restore();
}

function drawFallbackPipeSizeLabel(ctx, segment, point) {
  const lines = pipePreviewLabelLines(segment);
  ctx.save();
  ctx.font = "900 11px Inter, system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  const width = Math.max(...lines.map((line) => ctx.measureText(line).width)) + 12;
  const height = lines.length > 1 ? 31 : 20;
  roundRect(ctx, point.x - width / 2, point.y - height / 2 - 18, width, height, 5);
  ctx.fillStyle = "rgba(255, 253, 248, 0.92)";
  ctx.strokeStyle = "rgba(31, 42, 47, 0.18)";
  ctx.lineWidth = 1;
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = "#263538";
  if (lines.length === 1) {
    ctx.fillText(lines[0], point.x, point.y - 18);
  } else {
    ctx.fillText(lines[0], point.x, point.y - 23);
    ctx.font = "800 10px Inter, system-ui, sans-serif";
    ctx.fillStyle = "#667077";
    ctx.fillText(lines[1], point.x, point.y - 11);
  }
  ctx.restore();
}

function downloadCanvas(canvas, filename) {
  const link = document.createElement("a");
  link.download = filename;
  link.href = canvas.toDataURL("image/png");
  link.click();
}

function downloadTextFile(text, filename, type = "application/json") {
  const blob = new Blob([text], { type });
  downloadBlob(blob, filename);
}

function downloadBlob(blob, filename) {
  const link = document.createElement("a");
  link.download = filename;
  link.href = URL.createObjectURL(blob);
  link.click();
  setTimeout(() => URL.revokeObjectURL(link.href), 1000);
}

function downloadBytes(bytes, filename, type) {
  downloadBlob(new Blob([bytes], { type }), filename);
}

function safeFilePart(value, fallback) {
  const cleaned = String(value ?? "")
    .trim()
    .replace(/[^a-z0-9_-]+/gi, "-")
    .replace(/^-+|-+$/g, "");
  return cleaned || fallback;
}

function supabaseConfigured() {
  return Boolean(SUPABASE_URL && SUPABASE_PUBLISHABLE_KEY);
}

function cloudSaveTimestampMs(value) {
  const time = new Date(value).getTime();
  return Number.isFinite(time) ? time : 0;
}

function formatCloudSaveTime(value, options = {}) {
  const time = cloudSaveTimestampMs(value);
  if (!time) return "";
  const date = new Date(time);
  return options.full
    ? date.toLocaleString()
    : date.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
}

function readCloudSaveMetaStore() {
  try {
    const raw = JSON.parse(localStorage.getItem(CLOUD_SAVE_META_KEY));
    return raw && typeof raw === "object" && !Array.isArray(raw) ? raw : {};
  } catch {
    return {};
  }
}

function writeCloudSaveMetaStore(store) {
  try {
    const entries = Object.entries(store)
      .filter(([id, meta]) => id && meta && typeof meta === "object")
      .sort(([, first], [, second]) => {
        const firstDate = String(first.savedAt ?? first.remoteUpdatedAt ?? "");
        const secondDate = String(second.savedAt ?? second.remoteUpdatedAt ?? "");
        return secondDate.localeCompare(firstDate);
      })
      .slice(0, 120);
    localStorage.setItem(CLOUD_SAVE_META_KEY, JSON.stringify(Object.fromEntries(entries)));
  } catch (error) {
    console.warn("Could not store cloud save status.", error);
  }
}

function resetCloudSaveTracking() {
  cloudSaveDirty = false;
  cloudSaveConflict = false;
  cloudSaveError = "";
  cloudLastSavedAt = "";
  cloudLastRemoteUpdatedAt = "";
  cloudSaveTrackedProjectId = normalizeProjectId(state.projectId);
}

function loadCloudSaveMetaForCurrentProject(projectId = state.projectId) {
  const id = normalizeProjectId(projectId);
  cloudSaveTrackedProjectId = id;
  cloudSaveDirty = false;
  cloudSaveConflict = false;
  cloudSaveError = "";
  if (!id) {
    cloudLastSavedAt = "";
    cloudLastRemoteUpdatedAt = "";
    return;
  }

  const meta = readCloudSaveMetaStore()[id] ?? {};
  cloudLastSavedAt = String(meta.savedAt ?? "");
  cloudLastRemoteUpdatedAt = String(meta.remoteUpdatedAt ?? "");
}

function ensureCloudSaveTrackingProject() {
  const id = normalizeProjectId(state.projectId);
  if (id !== cloudSaveTrackedProjectId) loadCloudSaveMetaForCurrentProject(id);
}

function currentProjectHasCloudRecord() {
  const id = normalizeProjectId(state.projectId);
  if (!id) return false;
  return Boolean(
    normalizeUuid(currentCloudProjectOwnerId)
      || normalizeUuid(currentCloudProjectCompanyId)
      || cloudLastRemoteUpdatedAt
      || cloudLastSavedAt
      || (cloudProjectCache ?? []).some((project) => project.id === id)
  );
}

function cloudSaveTitle(defaultTitle) {
  const lines = [defaultTitle].filter(Boolean);
  if (cloudUser?.email) lines.push(cloudUser.email);
  if (cloudUser) lines.push(cloudLicenseText());
  if (activeCompany && activeCompanyMembership?.status === "approved") lines.push(`Team: ${activeCompany.name}`);
  if (state.projectId) lines.push(`Project: ${projectDisplayName()}`);
  if (cloudLastSavedAt) lines.push(`Last cloud save: ${formatCloudSaveTime(cloudLastSavedAt, { full: true })}`);
  if (cloudSaveDirty) lines.push("This drawing has changes waiting to save.");
  if (cloudSaveConflict) lines.push("A newer cloud copy was detected. Press Save to choose whether to overwrite it.");
  if (cloudSaveError) lines.push(cloudSaveError);
  return lines.join("\n");
}

function markCloudSaveDirty() {
  if (cloudDirtySuppressed) return;
  ensureCloudSaveTrackingProject();
  if (!hasDrawingContent()) {
    cloudSaveDirty = false;
    cloudSaveConflict = false;
    cloudSaveError = "";
    updateCloudStatus();
    return;
  }
  if (!cloudUser || !hasActiveCloudLicense()) {
    updateCloudStatus();
    return;
  }
  cloudSaveDirty = true;
  if (!cloudSaveConflict) cloudSaveError = "";
  updateCloudStatus();
}

function markCloudSaveClean(remoteUpdatedAt, options = {}) {
  const id = normalizeProjectId(state.projectId);
  const updatedAt = String(remoteUpdatedAt || new Date().toISOString());
  cloudSaveTrackedProjectId = id;
  cloudSaveDirty = false;
  cloudSaveConflict = false;
  cloudSaveError = "";
  cloudLastSavedAt = updatedAt;
  cloudLastRemoteUpdatedAt = updatedAt;

  if (id && options.writeMeta !== false) {
    const store = readCloudSaveMetaStore();
    store[id] = {
      savedAt: cloudLastSavedAt,
      remoteUpdatedAt: cloudLastRemoteUpdatedAt,
      ownerId: normalizeUuid(currentCloudProjectOwnerId),
      companyId: normalizeUuid(currentCloudProjectCompanyId),
      name: projectDisplayName(),
    };
    writeCloudSaveMetaStore(store);
  }
  if (options.updateStatus !== false) updateCloudStatus();
}

function markCloudSaveFailed(error) {
  cloudSaveError = error?.message ? `Cloud save failed: ${error.message}` : "Cloud save failed.";
  updateCloudStatus("Cloud save failed", "error");
}

function remoteCloudProjectIsNewer(remoteUpdatedAt) {
  const remoteTime = cloudSaveTimestampMs(remoteUpdatedAt);
  const baselineTime = cloudSaveTimestampMs(cloudLastRemoteUpdatedAt || cloudLastSavedAt);
  return Boolean(remoteTime && baselineTime && remoteTime > baselineTime + 1500);
}

async function fetchCloudProjectMeta(projectId = state.projectId) {
  const id = normalizeProjectId(projectId);
  if (!supabaseClient || !cloudUser || !id) return null;
  const { data, error } = await supabaseClient
    .from(CLOUD_PROJECTS_TABLE)
    .select("id,owner_id,company_id,updated_at")
    .eq("id", id)
    .limit(1);
  if (error) throw error;
  const row = Array.isArray(data) ? data[0] : null;
  if (!row) return null;
  return {
    id: normalizeProjectId(row.id),
    ownerId: normalizeUuid(row.owner_id),
    companyId: normalizeUuid(row.company_id),
    updatedAt: String(row.updated_at ?? ""),
  };
}

async function ensureCloudProjectCanOverwrite(options = {}) {
  if (!currentProjectHasCloudRecord()) return true;
  const remote = await fetchCloudProjectMeta();
  if (!remote?.updatedAt) return true;

  if (!cloudLastRemoteUpdatedAt && !cloudLastSavedAt) {
    cloudLastRemoteUpdatedAt = remote.updatedAt;
    return true;
  }

  if (!remoteCloudProjectIsNewer(remote.updatedAt)) {
    cloudLastRemoteUpdatedAt = remote.updatedAt;
    return true;
  }

  cloudSaveDirty = true;
  cloudSaveConflict = true;
  cloudSaveError = "";
  const when = formatCloudSaveTime(remote.updatedAt, { full: true }) || "recently";
  updateCloudStatus("Cloud newer copy", "conflict");
  if (options.autosave) return false;

  const overwrite = await confirmAppAction(
    `This spool was saved from another device at ${when}. Overwrite that cloud copy with this drawing?`,
    {
      title: "Cloud copy is newer",
      confirmLabel: "Overwrite cloud",
      tone: "warning",
    },
  );
  if (!overwrite) return false;

  cloudSaveConflict = false;
  cloudLastRemoteUpdatedAt = remote.updatedAt;
  updateCloudStatus("Saving cloud...", "saving");
  return true;
}

function withCloudDirtySuppressed(callback) {
  const previous = cloudDirtySuppressed;
  cloudDirtySuppressed = true;
  try {
    return callback();
  } finally {
    cloudDirtySuppressed = previous;
  }
}

function updateCloudStatus(message = null, mode = "") {
  ensureCloudSaveTrackingProject();
  const signedIn = Boolean(cloudUser);
  const active = signedIn && hasActiveCloudLicense();
  const teamSuffix = activeCompany && activeCompanyMembership?.status === "approved"
    ? ` / ${activeCompany.name}`
    : activeCompany && activeCompanyMembership?.status === "pending"
    ? " / team pending"
    : "";
  const hasCloudRecord = currentProjectHasCloudRecord();
  const defaultMessage = signedIn
    ? active
      ? cloudAutosaveBusy
        ? "Saving to cloud..."
        : cloudSaveConflict
        ? "Cloud conflict"
        : cloudSaveError
        ? "Cloud save failed"
        : cloudSaveDirty
        ? state.projectId
          ? "Unsaved changes"
          : "Not cloud saved"
        : hasCloudRecord && cloudLastSavedAt
        ? `Saved ${formatCloudSaveTime(cloudLastSavedAt)}`
        : hasDrawingContent()
        ? "Not cloud saved"
        : "Cloud ready"
      : cloudProfile
      ? "Trial expired"
      : "Cloud setup needed"
    : "Local only";
  const text = message || defaultMessage;
  const inferredMode = mode
    || (message && /conflict|newer/i.test(message) ? "conflict" : "")
    || (message && /failed|unavailable/i.test(message) ? "error" : "")
    || (message && /saving|loading|connecting|resending|creating|signing/i.test(message) ? "saving" : "")
    || (message && /saved|opened|resent/i.test(message) ? "saved" : "")
    || (!signedIn || !active ? (signedIn ? "warning" : "local") : "")
    || (cloudAutosaveBusy ? "saving" : "")
    || (cloudSaveConflict ? "conflict" : "")
    || (cloudSaveError ? "error" : "")
    || (cloudSaveDirty ? "dirty" : "")
    || (hasCloudRecord && cloudLastSavedAt ? "saved" : "signed-in");

  if (cloudSyncStatus) {
    cloudSyncStatus.textContent = text;
    cloudSyncStatus.title = cloudSaveTitle(signedIn && cloudUser?.email ? `${cloudUser.email}${teamSuffix}` : "Not signed in");
    cloudSyncStatus.classList.toggle("signed-in", inferredMode === "signed-in");
    cloudSyncStatus.classList.toggle("saving", inferredMode === "saving");
    cloudSyncStatus.classList.toggle("saved", inferredMode === "saved");
    cloudSyncStatus.classList.toggle("dirty", inferredMode === "dirty");
    cloudSyncStatus.classList.toggle("conflict", inferredMode === "conflict");
    cloudSyncStatus.classList.toggle("error", inferredMode === "error");
    cloudSyncStatus.classList.toggle("warning", inferredMode === "warning");
  }
  if (accountButtonLabel) {
    accountButtonLabel.textContent = signedIn ? "Account" : "Sign in";
  }
  if (authDialogStatus) {
    authDialogStatus.textContent = signedIn
      ? `${cloudUser.email || "Signed in"} - ${cloudLicenseText()}${teamSuffix}`
      : authMode === "signup"
      ? "Create an account to start a free trial and save spool projects to the cloud."
      : "Sign in to save and open spool projects from the cloud.";
  }
  if (authEmailInput && signedIn) authEmailInput.value = cloudUser.email || "";
  if (authSignOutButton) authSignOutButton.hidden = !signedIn;
  if (authSignInButton) authSignInButton.disabled = signedIn;
  if (authSignUpButton) authSignUpButton.disabled = signedIn;
  setAuthMode(authMode, { keepStatus: true });
  if (saveBrowserProjectButton) {
    saveBrowserProjectButton.title = signedIn && active
      ? "Save project to cloud and this browser"
      : "Save project in this browser";
  }
  if (openBrowserProjectButton) {
    openBrowserProjectButton.title = signedIn && active
      ? "Open cloud saved project"
      : "Open saved project from this browser";
  }
}

function cloudLicenseText(profile = cloudProfile) {
  if (!cloudUser) return "Local only";
  if (!profile) return "No licence profile";
  const status = String(profile.license_status ?? "trial").toLowerCase();
  if (status === "full") return "Full licence";
  if (status === "paid") return "Paid licence";
  const trialEnds = profile.trial_ends_at ? new Date(profile.trial_ends_at) : null;
  if (status === "trial" && trialEnds && trialEnds > new Date()) {
    const days = Math.max(1, Math.ceil((trialEnds - new Date()) / 86400000));
    return `Trial ${days} day${days === 1 ? "" : "s"} left`;
  }
  return "Trial expired";
}

function hasActiveCloudLicense(profile = cloudProfile) {
  if (!cloudUser || !profile) return false;
  const status = String(profile.license_status ?? "trial").toLowerCase();
  if (status === "full" || status === "paid") return true;
  if (status !== "trial") return false;
  const trialEnds = profile.trial_ends_at ? new Date(profile.trial_ends_at) : null;
  return Boolean(trialEnds && trialEnds > new Date());
}

function activeCompanyIsApproved() {
  return Boolean(activeCompany && activeCompanyMembership?.status === "approved");
}

function activeCompanyCanAdmin() {
  return activeCompanyIsApproved() && ["owner", "admin"].includes(activeCompanyMembership?.role);
}

function activeCompanyCanManageRoles() {
  return activeCompanyIsApproved() && activeCompanyMembership?.role === "owner";
}

function companyMembershipForCurrentUser(companyId) {
  const id = normalizeUuid(companyId);
  if (!id || !cloudUser) return null;
  return cloudCompanyMemberships.find((member) => member.companyId === id && member.userId === cloudUser.id) ||
    (activeCompanyMembership?.companyId === id ? activeCompanyMembership : null);
}

function currentUserIsCompanyMember(companyId) {
  const membership = companyMembershipForCurrentUser(companyId);
  return membership?.status === "approved";
}

function currentUserCanAdminCompany(companyId) {
  const membership = companyMembershipForCurrentUser(companyId);
  return membership?.status === "approved" && ["owner", "admin"].includes(membership.role);
}

function projectPermission(project, options = {}) {
  const source = project?.source ?? options.source ?? projectLibrarySource;
  if (source !== "cloud") {
    return {
      canView: true,
      canComment: false,
      canEdit: true,
      canIssue: true,
      canDelete: true,
      label: "Local editable",
    };
  }

  const ownerId = normalizeUuid(project?.ownerId);
  const companyId = normalizeUuid(project?.companyId);
  const ownsProject = Boolean(cloudUser?.id && ownerId === cloudUser.id);
  const companyMember = currentUserIsCompanyMember(companyId);
  const companyAdmin = currentUserCanAdminCompany(companyId);
  const canEdit = ownsProject || companyAdmin;

  return {
    canView: ownsProject || companyMember,
    canComment: ownsProject || companyMember,
    canEdit,
    canIssue: canEdit,
    canDelete: ownsProject || companyAdmin,
    label: canEdit
      ? ownsProject
        ? "Owner editable"
        : "Team admin editable"
      : companyMember
      ? "Member view/comment"
      : "Cloud read only",
  };
}

function currentDrawingProjectPermission() {
  if (!currentProjectHasCloudRecord()) return projectPermission({ source: "browser" });
  return projectPermission({
    source: "cloud",
    id: state.projectId,
    ownerId: currentCloudProjectOwnerId,
    companyId: currentCloudProjectCompanyId,
    projectInfo: state.projectInfo,
    state: statePayload({ includeRevisionHistory: false }),
  });
}

function companyNameForId(companyId) {
  const id = normalizeUuid(companyId);
  if (!id) return "";
  return cloudCompanies.find((company) => company.id === id)?.name || "";
}

function currentProjectCompanyId() {
  const cached = (cloudProjectCache ?? []).find((project) => project.id === state.projectId);
  return normalizeUuid(currentCloudProjectCompanyId) || normalizeUuid(cached?.companyId) || (activeCompanyIsApproved() ? activeCompany.id : null);
}

function clearTeamWorkspace() {
  cloudCompanies = [];
  cloudCompanyMemberships = [];
  activeCompany = null;
  activeCompanyMembership = null;
  companyMembers = [];
  projectComments = [];
  projectCommentsProjectId = null;
  teamMessages = [];
  teamMessagesCompanyId = null;
  teamMessagesError = "";
  renderTeamWorkspace();
  renderProjectLibraryComms(projectLibraryProjects);
  renderProjectComments();
}

function storedActiveCompanyId() {
  try {
    return normalizeUuid(localStorage.getItem(ACTIVE_COMPANY_KEY));
  } catch {
    return null;
  }
}

function storeActiveCompanyId(companyId) {
  try {
    const id = normalizeUuid(companyId);
    if (id) {
      localStorage.setItem(ACTIVE_COMPANY_KEY, id);
    } else {
      localStorage.removeItem(ACTIVE_COMPANY_KEY);
    }
  } catch {
    // Team selection still works for this session if local storage is blocked.
  }
}

function setActiveCompanyFromId(companyId) {
  const id = normalizeUuid(companyId);
  const membership = id
    ? cloudCompanyMemberships.find((member) => member.companyId === id && member.userId === cloudUser?.id) ||
      activeCompanyMembership?.companyId === id && activeCompanyMembership
    : null;
  const company = id ? cloudCompanies.find((item) => item.id === id) : null;
  if (!company || !membership) return false;
  activeCompany = company;
  activeCompanyMembership = membership;
  storeActiveCompanyId(id);
  renderTeamWorkspace();
  updateCloudStatus();
  return true;
}

async function activateCompanyFromId(companyId) {
  if (!setActiveCompanyFromId(companyId) || !activeCompany) return false;
  companyMembers = await loadCompanyMembers(activeCompany.id, cloudCompanyMemberships);
  renderTeamWorkspace();
  updateCloudStatus();
  return true;
}

async function loadTeamWorkspace(options = {}) {
  if (!supabaseClient || !cloudUser || !hasActiveCloudLicense()) {
    clearTeamWorkspace();
    return;
  }

  try {
    const { data: membershipRows, error: membershipError } = await supabaseClient
      .from(CLOUD_COMPANY_MEMBERS_TABLE)
      .select("company_id,user_id,email,role,status,created_at,updated_at")
      .eq("user_id", cloudUser.id)
      .order("updated_at", { ascending: false });
    if (membershipError) throw membershipError;

    const memberships = (membershipRows ?? [])
      .map(normalizeCompanyMember)
      .filter(Boolean);
    cloudCompanyMemberships = memberships;
    const companyIds = [...new Set(memberships.map((member) => member.companyId))];
    let companies = [];
    if (companyIds.length) {
      const { data: companyRows, error: companyError } = await supabaseClient
        .from(CLOUD_COMPANIES_TABLE)
        .select("id,name,invite_code,created_by,created_at,updated_at")
        .in("id", companyIds);
      if (companyError) throw companyError;
      companies = (companyRows ?? []).map(normalizeCompany).filter(Boolean);
    }

    cloudCompanies = companies;
    const savedCompanyId = storedActiveCompanyId();
    activeCompanyMembership =
      memberships.find((member) => member.status === "approved" && member.companyId === savedCompanyId) ||
      memberships.find((member) => member.status === "approved") ||
      memberships.find((member) => member.companyId === savedCompanyId) ||
      memberships[0] ||
      null;
    activeCompany = activeCompanyMembership
      ? companies.find((company) => company.id === activeCompanyMembership.companyId) ?? null
      : null;
    if (activeCompany) {
      storeActiveCompanyId(activeCompany.id);
    } else {
      storeActiveCompanyId(null);
    }

    companyMembers = activeCompany ? await loadCompanyMembers(activeCompany.id, memberships) : [];
    if (projectLibraryCommsVisible && activeCompanyIsApproved()) {
      await loadTeamMessages({ silent: true });
    }
    renderTeamWorkspace();
    updateCloudStatus();
  } catch (error) {
    console.warn("Could not load team workspace.", error);
    if (!options.silent) showAppNotice(error?.message || "Could not load team workspace.");
    renderTeamWorkspace("Could not load team workspace.");
  }
}

async function loadCompanyMembers(companyId, fallbackMemberships = []) {
  const id = normalizeUuid(companyId);
  if (!supabaseClient || !id) return [];
  try {
    const { data, error } = await supabaseClient
      .from(CLOUD_COMPANY_MEMBERS_TABLE)
      .select("company_id,user_id,email,role,status,created_at,updated_at")
      .eq("company_id", id)
      .order("created_at", { ascending: true });
    if (error) throw error;
    return (data ?? []).map(normalizeCompanyMember).filter(Boolean);
  } catch (error) {
    console.warn("Could not load company members.", error);
    return fallbackMemberships.filter((member) => member.companyId === id);
  }
}

function renderTeamWorkspace(errorMessage = "") {
  if (!teamWorkspacePanel) return;
  const signedIn = Boolean(cloudUser);
  teamWorkspacePanel.hidden = !signedIn;
  if (!signedIn) return;

  const active = hasActiveCloudLicense();
  if (teamCreateButton) teamCreateButton.disabled = !active;
  if (teamJoinButton) teamJoinButton.disabled = !active;
  if (teamRefreshButton) teamRefreshButton.disabled = !active;

  if (teamWorkspaceStatus) {
    if (errorMessage) {
      teamWorkspaceStatus.textContent = errorMessage;
    } else if (!active) {
      teamWorkspaceStatus.textContent = "An active trial or licence is required for team projects.";
    } else if (!activeCompany) {
      teamWorkspaceStatus.textContent = "No team workspace yet. Create one or join with an invite code.";
    } else if (activeCompanyMembership?.status === "pending") {
      teamWorkspaceStatus.textContent = `Join request for ${activeCompany.name} is waiting for approval.`;
    } else if (activeCompanyMembership?.status === "rejected") {
      teamWorkspaceStatus.textContent = `Join request for ${activeCompany.name} was rejected.`;
    } else {
      const invite = activeCompany.inviteCode ? ` Invite code: ${activeCompany.inviteCode}.` : "";
      const roleText = activeCompanyMembership?.role ? ` Your role: ${activeCompanyMembership.role}.` : "";
      teamWorkspaceStatus.textContent = `Using ${activeCompany.name} for shared cloud projects.${roleText}${invite}`;
    }
  }

  if (!teamMembersList) return;
  teamMembersList.innerHTML = "";
  if (!activeCompany) {
    const empty = document.createElement("div");
    empty.className = "team-empty";
    empty.textContent = "Create a team, then share its invite code with the people you want to approve.";
    teamMembersList.append(empty);
    return;
  }

  const members = companyMembers.length ? companyMembers : activeCompanyMembership ? [activeCompanyMembership] : [];
  if (!members.length) {
    const empty = document.createElement("div");
    empty.className = "team-empty";
    empty.textContent = "No members loaded yet.";
    teamMembersList.append(empty);
    return;
  }

  const canAdmin = activeCompanyCanAdmin();
  const canManageRoles = activeCompanyCanManageRoles();
  for (const member of members) {
    const row = document.createElement("div");
    row.className = "team-member-row";
    row.classList.toggle("pending", member.status === "pending");

    const main = document.createElement("div");
    main.className = "team-member-main";

    const title = document.createElement("strong");
    title.textContent = member.email || (member.userId === cloudUser?.id ? "You" : "Team member");

    const detail = document.createElement("span");
    detail.textContent = `${member.role} / ${member.status}`;
    main.append(title, detail);
    row.append(main);

    const actions = document.createElement("div");
    actions.className = "team-member-actions";
    if (canManageRoles && member.status === "approved" && member.userId !== cloudUser?.id && member.role !== "owner") {
      const roleSelect = document.createElement("select");
      roleSelect.dataset.teamMemberRole = member.userId;
      roleSelect.title = "Change this user's team role";
      for (const [value, label] of [["member", "Member"], ["admin", "Admin"]]) {
        const option = document.createElement("option");
        option.value = value;
        option.textContent = label;
        option.selected = member.role === value;
        roleSelect.append(option);
      }
      actions.append(roleSelect);
    }
    if (canAdmin && member.status === "pending" && member.userId !== cloudUser?.id) {
      const approve = document.createElement("button");
      approve.type = "button";
      approve.textContent = "Approve";
      approve.dataset.teamMemberAction = "approve";
      approve.dataset.teamMemberUserId = member.userId;
      const reject = document.createElement("button");
      reject.type = "button";
      reject.className = "danger";
      reject.textContent = "Reject";
      reject.dataset.teamMemberAction = "reject";
      reject.dataset.teamMemberUserId = member.userId;
      actions.append(approve, reject);
    }
    row.append(actions);
    teamMembersList.append(row);
  }
}

async function createTeamCompany() {
  if (!(await ensureSupabaseClient()) || !cloudUser) return;
  if (!hasActiveCloudLicense()) {
    showAppNotice("An active trial or licence is required to create a team.");
    return;
  }

  const companyName = String(teamCompanyNameInput?.value ?? "").trim() || "SpoolMate Company";
  if (teamCreateButton) teamCreateButton.disabled = true;
  try {
    const { data, error } = await supabaseClient.rpc("create_company", { company_name: companyName });
    if (error) throw error;
    await loadTeamWorkspace({ silent: true });
    const created = Array.isArray(data) ? data[0] : data;
    if (created?.company_id) await activateCompanyFromId(created.company_id);
    if (teamCompanyNameInput) teamCompanyNameInput.value = "";
    showAppNotice(`Team created.${activeCompany?.inviteCode ? ` Invite code: ${activeCompany.inviteCode}` : ""}`);
  } catch (error) {
    console.warn("Could not create team.", error);
    showAppNotice(error?.message || "Could not create team.");
  } finally {
    if (teamCreateButton) teamCreateButton.disabled = !hasActiveCloudLicense();
  }
}

async function joinTeamCompany() {
  if (!(await ensureSupabaseClient()) || !cloudUser) return;
  if (!hasActiveCloudLicense()) {
    showAppNotice("An active trial or licence is required to join a team.");
    return;
  }

  const joinCode = String(teamInviteCodeInput?.value ?? "").trim().toUpperCase();
  if (!joinCode) {
    showAppNotice("Enter the team invite code.");
    return;
  }

  if (teamJoinButton) teamJoinButton.disabled = true;
  try {
    const { data, error } = await supabaseClient.rpc("join_company_by_code", { join_code: joinCode });
    if (error) throw error;
    await loadTeamWorkspace({ silent: true });
    const joined = Array.isArray(data) ? data[0] : data;
    if (joined?.company_id) await activateCompanyFromId(joined.company_id);
    if (teamInviteCodeInput) teamInviteCodeInput.value = "";
    showAppNotice(joined?.status === "approved" ? "You are already approved for that team." : "Join request sent. A team admin can approve it.");
  } catch (error) {
    console.warn("Could not join team.", error);
    showAppNotice(error?.message || "Could not join team.");
  } finally {
    if (teamJoinButton) teamJoinButton.disabled = !hasActiveCloudLicense();
  }
}

async function reviewTeamMember(userId, approved) {
  if (!supabaseClient || !activeCompanyCanAdmin()) return;
  const memberId = normalizeUuid(userId);
  if (!memberId || !activeCompany) return;

  const { error } = await supabaseClient
    .from(CLOUD_COMPANY_MEMBERS_TABLE)
    .update({ status: approved ? "approved" : "rejected", role: "member" })
    .eq("company_id", activeCompany.id)
    .eq("user_id", memberId);
  if (error) {
    showAppNotice(error?.message || "Could not update team member.");
    throw error;
  }
  await loadTeamWorkspace({ silent: true });
}

async function updateTeamMemberRole(userId, role) {
  if (!supabaseClient || !activeCompanyCanManageRoles()) {
    showAppNotice("Only the team owner can change member roles.");
    return;
  }
  const memberId = normalizeUuid(userId);
  const nextRole = role === "admin" ? "admin" : "member";
  if (!memberId || !activeCompany || memberId === cloudUser?.id) return;

  const { error } = await supabaseClient
    .from(CLOUD_COMPANY_MEMBERS_TABLE)
    .update({ role: nextRole, status: "approved" })
    .eq("company_id", activeCompany.id)
    .eq("user_id", memberId)
    .neq("role", "owner");
  if (error) throw error;
  await loadTeamWorkspace({ silent: true });
}

function projectCommentMentionChoices() {
  const seen = new Set();
  const choices = [];
  for (const member of companyMembers) {
    if (member.status !== "approved" || !member.email) continue;
    const token = member.email.split("@")[0].replace(/[^a-z0-9._-]/gi, "").slice(0, 48);
    if (!token || seen.has(token.toLowerCase())) continue;
    seen.add(token.toLowerCase());
    choices.push({ token, email: member.email });
  }
  return choices.slice(0, 18);
}

function projectCommentMentions(body) {
  const mentions = [];
  const seen = new Set();
  for (const match of String(body ?? "").matchAll(/@([a-z0-9._-]+)/gi)) {
    const token = String(match[1] ?? "").toLowerCase();
    if (!token || seen.has(token)) continue;
    seen.add(token);
    mentions.push(token);
  }
  return mentions.slice(0, 24);
}

function currentUserMentionTokens() {
  const email = String(cloudUser?.email ?? "").toLowerCase();
  const local = email.split("@")[0].replace(/[^a-z0-9._-]/g, "");
  return new Set([email, local].filter(Boolean));
}

function projectCommentMentionsCurrentUser(comment) {
  const mine = currentUserMentionTokens();
  return Array.isArray(comment?.mentions) && comment.mentions.some((mention) => mine.has(String(mention).toLowerCase()));
}

function renderProjectCommentMentionPicks() {
  if (!projectCommentMentionPicks) return;
  const choices = projectCommentMentionChoices();
  projectCommentMentionPicks.innerHTML = choices.length
    ? `<span>Mention:</span>${choices.map((choice) => `<button type="button" data-comment-mention="${escapeHtml(choice.token)}" title="Mention ${escapeHtml(choice.email)}">@${escapeHtml(choice.token)}</button>`).join("")}`
    : "";
  projectCommentMentionPicks.hidden = !choices.length;
}

function appendProjectCommentBody(element, body) {
  const text = String(body ?? "");
  const pattern = /@[a-z0-9._-]+/gi;
  let index = 0;
  for (const match of text.matchAll(pattern)) {
    const start = match.index ?? 0;
    if (start > index) element.append(document.createTextNode(text.slice(index, start)));
    const mention = document.createElement("span");
    mention.className = "comment-mention";
    mention.textContent = match[0];
    element.append(mention);
    index = start + match[0].length;
  }
  if (index < text.length) element.append(document.createTextNode(text.slice(index)));
}

function clearPendingProjectCommentPhoto() {
  if (pendingProjectCommentPhotoUrl) URL.revokeObjectURL(pendingProjectCommentPhotoUrl);
  pendingProjectCommentPhoto = null;
  pendingProjectCommentPhotoUrl = "";
  if (projectCommentPhotoInput) projectCommentPhotoInput.value = "";
  if (projectCommentPhotoPreview) projectCommentPhotoPreview.hidden = true;
  if (projectCommentPhotoPreviewImage) projectCommentPhotoPreviewImage.removeAttribute("src");
}

function setPendingProjectCommentPhoto(file) {
  clearPendingProjectCommentPhoto();
  if (!(file instanceof File)) return;
  if (!/^image\/(jpeg|png|webp)$/i.test(file.type)) {
    showAppNotice("Use a JPG, PNG or WebP workshop photo.");
    return;
  }
  if (file.size > 8 * 1024 * 1024) {
    showAppNotice("Workshop photos must be 8 MB or smaller.");
    return;
  }
  pendingProjectCommentPhoto = file;
  pendingProjectCommentPhotoUrl = URL.createObjectURL(file);
  if (projectCommentPhotoPreviewImage) projectCommentPhotoPreviewImage.src = pendingProjectCommentPhotoUrl;
  if (projectCommentPhotoPreviewName) projectCommentPhotoPreviewName.textContent = file.name || "Workshop photo";
  if (projectCommentPhotoPreview) projectCommentPhotoPreview.hidden = false;
}

async function projectCommentPhotoUrl(path) {
  const key = String(path ?? "").trim();
  if (!key || !supabaseClient) return "";
  const cached = projectCommentPhotoUrlCache.get(key);
  if (cached && Date.now() - cached.createdAt < 45 * 60 * 1000) return cached.url;
  const { data, error } = await supabaseClient.storage.from(CLOUD_PROJECT_PHOTOS_BUCKET).createSignedUrl(key, 3600);
  if (error) throw error;
  const url = String(data?.signedUrl ?? "");
  if (url) projectCommentPhotoUrlCache.set(key, { url, createdAt: Date.now() });
  return url;
}

async function hydrateProjectCommentPhoto(image, path) {
  try {
    const url = await projectCommentPhotoUrl(path);
    if (!image.isConnected || !url) return;
    image.src = url;
    image.classList.add("loaded");
  } catch (error) {
    console.warn("Could not load workshop photo.", error);
    if (image.isConnected) image.alt = "Workshop photo unavailable";
  }
}

async function uploadProjectCommentPhoto(file) {
  if (!file || !supabaseClient || !cloudUser || !state.projectId) return "";
  const extension = file.type === "image/png" ? "png" : file.type === "image/webp" ? "webp" : "jpg";
  const scope = normalizeUuid(currentProjectCompanyId()) || normalizeUuid(cloudUser.id);
  const projectKey = String(state.projectId).replace(/[^a-z0-9_-]/gi, "-").slice(0, 100);
  const path = `${scope}/${projectKey}/${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}.${extension}`;
  const { error } = await supabaseClient.storage
    .from(CLOUD_PROJECT_PHOTOS_BUCKET)
    .upload(path, file, { contentType: file.type, cacheControl: "3600", upsert: false });
  if (error) throw error;
  return path;
}

async function insertProjectCommentRecord(body, options = {}) {
  const text = String(body ?? "").trim().slice(0, 1000);
  if (!supabaseClient || !cloudUser || !state.projectId || !text) return false;
  const { error } = await supabaseClient
    .from(CLOUD_PROJECT_COMMENTS_TABLE)
    .insert({
      project_id: state.projectId,
      company_id: currentProjectCompanyId(),
      author_id: cloudUser.id,
      author_email: cloudUser.email ?? "",
      body: text,
      mentions: projectCommentMentions(text),
      photo_path: String(options.photoPath ?? "").trim() || null,
    });
  if (error) throw error;
  return true;
}

async function toggleProjectCommentResolved(commentId, resolved) {
  if (!supabaseClient || !cloudUser) return;
  projectCommentsBusy = true;
  renderProjectComments();
  try {
    const { error } = await supabaseClient.rpc("set_project_comment_resolved", {
      comment_id_value: commentId,
      resolved_value: resolved === true,
    });
    if (error) throw error;
    await loadProjectComments({ silent: true });
  } finally {
    projectCommentsBusy = false;
    renderProjectComments();
  }
}

function renderProjectComments(errorMessage = "") {
  if (!projectCommentsList) return;
  projectCommentsList.innerHTML = "";
  renderProjectCommentMentionPicks();

  if (projectCommentAddButton) {
    projectCommentAddButton.disabled = !cloudUser || !hasActiveCloudLicense() || projectCommentsBusy || (!String(projectCommentInput?.value ?? "").trim() && !pendingProjectCommentPhoto);
  }
  if (projectCommentRefreshButton) {
    projectCommentRefreshButton.disabled = !cloudUser || !hasActiveCloudLicense() || projectCommentsBusy || !state.projectId;
  }
  if (projectCommentPhotoButton) {
    projectCommentPhotoButton.disabled = !cloudUser || !hasActiveCloudLicense() || projectCommentsBusy;
  }

  const empty = (message) => {
    const item = document.createElement("div");
    item.className = "team-empty";
    item.textContent = message;
    projectCommentsList.append(item);
  };

  if (errorMessage) {
    empty(errorMessage);
    return;
  }
  if (!cloudUser) {
    empty("Sign in to use cloud comments.");
    return;
  }
  if (!hasActiveCloudLicense()) {
    empty("An active trial or licence is required for cloud comments.");
    return;
  }
  if (!state.projectId) {
    empty("Save this spool to the cloud before adding comments.");
    return;
  }
  if (projectCommentsProjectId !== state.projectId) {
    empty("Press Refresh to load comments for this spool.");
    return;
  }
  if (!projectComments.length) {
    empty("No comments yet.");
    return;
  }

  for (const comment of projectComments) {
    const item = document.createElement("div");
    item.className = "team-comment";
    item.classList.toggle("resolved", comment.resolved);
    item.classList.toggle("mentions-me", projectCommentMentionsCurrentUser(comment));

    const header = document.createElement("div");
    header.className = "team-comment-head";
    const author = document.createElement("strong");
    author.textContent = comment.authorEmail || "Team member";
    header.append(author);
    if (comment.resolved) {
      const badge = document.createElement("span");
      badge.className = "team-comment-resolved-badge";
      badge.textContent = "Resolved";
      header.append(badge);
    } else if (projectCommentMentionsCurrentUser(comment)) {
      const badge = document.createElement("span");
      badge.className = "team-comment-mention-badge";
      badge.textContent = "Mentioned you";
      header.append(badge);
    }

    const body = document.createElement("p");
    appendProjectCommentBody(body, comment.body);

    let photo = null;
    if (comment.photoPath) {
      photo = document.createElement("img");
      photo.className = "team-comment-photo";
      photo.alt = "Workshop photo attached to this spool message";
      photo.loading = "lazy";
      hydrateProjectCommentPhoto(photo, comment.photoPath);
    }

    const meta = document.createElement("span");
    meta.className = "team-comment-meta";
    const created = comment.createdAt ? new Date(comment.createdAt).toLocaleString() : "Just now";
    const resolved = comment.resolved && comment.resolvedAt
      ? ` / resolved ${new Date(comment.resolvedAt).toLocaleString()}`
      : "";
    meta.textContent = `${created}${resolved}`;

    const actions = document.createElement("div");
    actions.className = "team-comment-actions";
    const resolveButton = document.createElement("button");
    resolveButton.type = "button";
    resolveButton.dataset.projectCommentAction = comment.resolved ? "reopen" : "resolve";
    resolveButton.dataset.projectCommentId = comment.id;
    resolveButton.textContent = comment.resolved ? "Reopen" : "Resolve";
    resolveButton.disabled = projectCommentsBusy;
    actions.append(resolveButton);

    item.append(header, body);
    if (photo) item.append(photo);
    item.append(meta, actions);
    projectCommentsList.append(item);
  }
}

async function loadProjectComments(options = {}) {
  if (!supabaseClient || !cloudUser || !hasActiveCloudLicense() || !state.projectId) {
    projectComments = [];
    projectCommentsProjectId = state.projectId ?? null;
    renderProjectComments();
    return [];
  }

  projectCommentsBusy = true;
  renderProjectComments();
  try {
    const { data, error } = await supabaseClient
      .from(CLOUD_PROJECT_COMMENTS_TABLE)
      .select("id,project_id,company_id,author_id,author_email,body,mentions,photo_path,resolved,resolved_at,resolved_by,created_at,updated_at")
      .eq("project_id", state.projectId)
      .order("created_at", { ascending: true })
      .limit(100);
    if (error) throw error;
    projectComments = (data ?? []).map(normalizeProjectComment).filter(Boolean);
    projectCommentsProjectId = state.projectId;
    renderProjectComments();
    return projectComments;
  } catch (error) {
    console.warn("Could not load project comments.", error);
    if (!options.silent) showAppNotice(error?.message || "Could not load comments.");
    renderProjectComments("Could not load comments.");
    return [];
  } finally {
    projectCommentsBusy = false;
    renderProjectComments();
  }
}

async function addProjectComment() {
  if (!(await ensureSupabaseClient()) || !cloudUser) return;
  if (!hasActiveCloudLicense()) {
    showAppNotice("An active trial or licence is required for cloud comments.");
    return;
  }

  const body = String(projectCommentInput?.value ?? "").trim() || (pendingProjectCommentPhoto ? "Workshop photo" : "");
  if (!body && !pendingProjectCommentPhoto) {
    showAppNotice("Type a message or add a workshop photo first.");
    return;
  }

  if (!state.projectId) {
    state.projectId = createProjectId();
  }
  if (!currentProjectHasCloudRecord()) {
    const saved = await saveCloudProject({ silent: true });
    if (!saved) {
      showAppNotice("Save the spool to the cloud before adding a message.");
      return;
    }
  }

  projectCommentsBusy = true;
  renderProjectComments();
  let uploadedPhotoPath = "";
  try {
    if (pendingProjectCommentPhoto) {
      uploadedPhotoPath = await uploadProjectCommentPhoto(pendingProjectCommentPhoto);
    }
    await insertProjectCommentRecord(body, { photoPath: uploadedPhotoPath });
    if (projectCommentInput) projectCommentInput.value = "";
    clearPendingProjectCommentPhoto();
    await loadProjectComments({ silent: true });
  } catch (error) {
    if (uploadedPhotoPath) {
      supabaseClient.storage.from(CLOUD_PROJECT_PHOTOS_BUCKET).remove([uploadedPhotoPath]).catch(() => {});
    }
    console.warn("Could not add project comment.", error);
    showAppNotice(error?.message || "Could not add spool message.");
  } finally {
    projectCommentsBusy = false;
    renderProjectComments();
  }
}

async function loadTeamMessages(options = {}) {
  if (!supabaseClient || !cloudUser || !hasActiveCloudLicense() || !activeCompanyIsApproved()) {
    teamMessages = [];
    teamMessagesCompanyId = activeCompany?.id ?? null;
    teamMessagesError = "";
    renderProjectLibraryComms(projectLibraryProjects);
    return [];
  }

  teamMessagesBusy = true;
  teamMessagesError = "";
  renderProjectLibraryComms(projectLibraryProjects);
  try {
    const { data, error } = await supabaseClient
      .from(CLOUD_TEAM_MESSAGES_TABLE)
      .select("id,company_id,author_id,author_email,body,pinned,completed,completed_at,remove_after,created_at,updated_at")
      .eq("company_id", activeCompany.id)
      .order("pinned", { ascending: false })
      .order("created_at", { ascending: false })
      .limit(80);
    if (error) throw error;
    teamMessages = (data ?? []).map(normalizeTeamMessage).filter(Boolean);
    teamMessagesCompanyId = activeCompany.id;
    teamMessagesError = "";
    renderProjectLibraryComms(projectLibraryProjects);
    return teamMessages;
  } catch (error) {
    console.warn("Could not load team messages.", error);
    teamMessages = [];
    teamMessagesError = "Team messages could not be loaded. Run the latest Supabase setup SQL if this is the first time using team comms.";
    if (!options.silent) showAppNotice(error?.message || "Could not load team messages. Run the latest Supabase setup SQL if this is the first time using team comms.");
    renderProjectLibraryComms(projectLibraryProjects);
    return [];
  } finally {
    teamMessagesBusy = false;
    renderProjectLibraryComms(projectLibraryProjects);
  }
}

async function addTeamMessage(bodyText = "") {
  if (!(await ensureSupabaseClient()) || !cloudUser) return;
  if (!activeCompanyIsApproved()) {
    showAppNotice("Join or create an approved team before adding team messages.");
    return;
  }
  if (!hasActiveCloudLicense()) {
    showAppNotice("An active trial or licence is required for team messages.");
    return;
  }

  const body = String(bodyText).trim().slice(0, 500);
  if (!body) {
    showAppNotice("Type the team message first.");
    return;
  }

  teamMessagesBusy = true;
  renderProjectLibraryComms(projectLibraryProjects);
  try {
    const { error } = await supabaseClient
      .from(CLOUD_TEAM_MESSAGES_TABLE)
      .insert({
        company_id: activeCompany.id,
        author_id: cloudUser.id,
        author_email: cloudUser.email ?? "",
        body,
      });
    if (error) throw error;
    await loadTeamMessages({ silent: true });
  } catch (error) {
    console.warn("Could not add team message.", error);
    showAppNotice(error?.message || "Could not add team message. Run the latest Supabase setup SQL if this is the first time using team comms.");
  } finally {
    teamMessagesBusy = false;
    renderProjectLibraryComms(projectLibraryProjects);
  }
}

async function completeTeamMessage(messageId) {
  if (!(await ensureSupabaseClient()) || !cloudUser || !activeCompanyIsApproved()) return;
  const id = normalizeUuid(messageId);
  if (!id) return;

  teamMessagesBusy = true;
  renderProjectLibraryComms(projectLibraryProjects);
  try {
    const now = new Date().toISOString();
    const { error } = await supabaseClient
      .from(CLOUD_TEAM_MESSAGES_TABLE)
      .update({
        completed: true,
        completed_at: now,
        remove_after: isoDaysFromNow(7),
      })
      .eq("id", id)
      .eq("company_id", activeCompany.id);
    if (error) throw error;
    await loadTeamMessages({ silent: true });
  } catch (error) {
    console.warn("Could not complete team message.", error);
    showAppNotice(error?.message || "Could not mark team message done.");
  } finally {
    teamMessagesBusy = false;
    renderProjectLibraryComms(projectLibraryProjects);
  }
}

function cloudProjectRecord() {
  const projectInfo = normalizeProjectInfo(state.projectInfo);
  const id = normalizeProjectId(state.projectId) ?? createProjectId();
  state.projectId = id;
  const existingCloudProject = (cloudProjectCache ?? []).find((project) => project.id === id);
  const knownCloudProject = Boolean(existingCloudProject || currentCloudProjectOwnerId || currentCloudProjectCompanyId);
  const companyId = knownCloudProject
    ? normalizeUuid(currentCloudProjectCompanyId) || normalizeUuid(existingCloudProject?.companyId)
    : activeCompanyIsApproved()
    ? activeCompany.id
    : null;
  return {
    id,
    owner_id: normalizeUuid(currentCloudProjectOwnerId) || normalizeUuid(existingCloudProject?.ownerId) || cloudUser?.id,
    company_id: companyId ?? null,
    name: projectDisplayName(projectInfo),
    project_info: projectInfo,
    drawing_state: statePayload(),
    updated_at: new Date().toISOString(),
  };
}

function mapCloudProject(row) {
  return {
    id: normalizeProjectId(row.id),
    name: String(row.name ?? "").trim().slice(0, 120),
    ownerId: normalizeUuid(row.owner_id),
    companyId: normalizeUuid(row.company_id),
    updatedAt: String(row.updated_at ?? row.created_at ?? ""),
    projectInfo: normalizeProjectInfo(row.project_info),
    state: row.drawing_state,
    source: "cloud",
  };
}

async function initSupabase() {
  if (cloudInitStarted) return cloudInitPromise;
  if (!supabaseConfigured()) return null;
  cloudInitStarted = true;
  cloudInitPromise = (async () => {
    updateCloudStatus("Connecting...", "");

    try {
      const { createClient } = await import(SUPABASE_JS_URL);
      supabaseClient = createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY);
      const { data, error } = await supabaseClient.auth.getSession();
      if (error) throw error;
      await applyCloudSession(data?.session ?? null);
      supabaseClient.auth.onAuthStateChange((_event, session) => {
        applyCloudSession(session).catch((sessionError) => {
          console.warn("Cloud session update failed.", sessionError);
          updateCloudStatus("Cloud setup needed", "warning");
        });
      });
    } catch (error) {
      console.warn("Supabase failed to initialise.", error);
      updateCloudStatus("Cloud unavailable", "warning");
    }
    return supabaseClient;
  })();
  return cloudInitPromise;
}

async function applyCloudSession(session) {
  cloudUser = session?.user ?? null;
  cloudProjectCache = null;
  if (!cloudUser) {
    cloudProfile = null;
    currentCloudProjectOwnerId = null;
    currentCloudProjectCompanyId = null;
    cloudPermissionReadOnly = false;
    resetCloudSaveTracking();
    clearTeamWorkspace();
    updateCloudStatus();
    return;
  }

  cloudProfile = await ensureCloudProfile();
  await loadTeamWorkspace({ silent: true });
  loadCloudSaveMetaForCurrentProject();
  updateCloudStatus();
  if (hasActiveCloudLicense() && state.projectId && hasDrawingContent()) {
    queueCloudAutosave();
  }
  if (!travellerRouteHandled && new URLSearchParams(location.search).get("traveller") === "1") {
    window.setTimeout(() => maybeOpenProjectFromUrl().catch((error) => console.warn("Could not open spool traveller.", error)), 100);
  }
}

async function ensureCloudProfile() {
  if (!supabaseClient || !cloudUser) return null;

  const selectProfile = async () => {
    const { data, error } = await supabaseClient
      .from(CLOUD_PROFILES_TABLE)
      .select("id,email,license_status,trial_started_at,trial_ends_at")
      .eq("id", cloudUser.id)
      .maybeSingle();
    if (error) throw error;
    return data;
  };

  try {
    const existing = await selectProfile();
    if (existing) return existing;

    const { error: insertError } = await supabaseClient
      .from(CLOUD_PROFILES_TABLE)
      .insert({
        id: cloudUser.id,
        email: cloudUser.email ?? "",
      });
    if (insertError) throw insertError;
    return await selectProfile();
  } catch (error) {
    console.warn("Could not load cloud profile.", error);
    return null;
  }
}

function queueCloudAutosave() {
  if (!supabaseClient || !cloudUser || !hasActiveCloudLicense() || !state.projectId || !hasDrawingContent()) return;
  if (cloudSaveConflict) return;
  window.clearTimeout(cloudAutosaveTimer);
  cloudAutosaveTimer = window.setTimeout(() => {
    saveCloudProject({ silent: true, autosave: true }).catch((error) => {
      console.warn("Cloud autosave failed.", error);
      markCloudSaveFailed(error);
    });
  }, CLOUD_AUTOSAVE_DELAY_MS);
}

async function saveCloudProject(options = {}) {
  if (!supabaseClient || !cloudUser) return false;
  if (!hasActiveCloudLicense()) {
    updateCloudStatus(cloudLicenseText(), "warning");
    if (!options.silent) showAppNotice("This account does not have an active trial or licence.");
    return false;
  }
  if (cloudPermissionReadOnly && currentProjectHasCloudRecord()) {
    updateCloudStatus("View/comment only", "warning");
    if (!options.silent) showAppNotice("This team spool is view/comment only for your role. Ask the owner or a team admin to save changes.");
    return false;
  }
  if (cloudAutosaveBusy) return false;

  cloudAutosaveBusy = true;
  updateCloudStatus("Saving cloud...", "saving");
  try {
    const canOverwrite = await ensureCloudProjectCanOverwrite({ autosave: options.autosave === true });
    if (!canOverwrite) return false;
    const record = cloudProjectRecord();
    const { data, error } = await supabaseClient
      .from(CLOUD_PROJECTS_TABLE)
      .upsert(record, { onConflict: "id" })
      .select("id,owner_id,company_id,name,updated_at,project_info,drawing_state")
      .single();
    if (error) throw error;
    cloudProjectCache = null;
    if (data) {
      state.projectId = data.id;
      currentCloudProjectOwnerId = normalizeUuid(data.owner_id);
      currentCloudProjectCompanyId = normalizeUuid(data.company_id);
      if (currentCloudProjectCompanyId) await activateCompanyFromId(currentCloudProjectCompanyId);
    }
    markCloudSaveClean(data?.updated_at, { updateStatus: false });
    updateCloudStatus("Cloud saved", "saved");
    window.setTimeout(() => updateCloudStatus(), 1600);
    return true;
  } catch (error) {
    markCloudSaveFailed(error);
    throw error;
  } finally {
    cloudAutosaveBusy = false;
  }
}

async function loadSavedCloudProjects() {
  if (!supabaseClient || !cloudUser || !hasActiveCloudLicense()) return [];
  if (cloudProjectCache) return cloudProjectCache;

  const { data, error } = await supabaseClient
    .from(CLOUD_PROJECTS_TABLE)
    .select("id,owner_id,company_id,name,updated_at,created_at,project_info,drawing_state")
    .order("updated_at", { ascending: false });
  if (error) throw error;
  cloudProjectCache = (data ?? [])
    .map(mapCloudProject)
    .filter((project) => project.id && stateFromPayload(project.state));
  return cloudProjectCache;
}

async function openSavedCloudProject(projectId, options = {}) {
  clearPendingProjectCommentPhoto();
  let record = (cloudProjectCache ?? []).find((project) => project.id === projectId);
  if (!record) {
    const projects = await loadSavedCloudProjects();
    record = projects.find((project) => project.id === projectId);
  }
  if (!record) {
    showAppNotice("That cloud project was not found.");
    return;
  }

  if (!options.skipConfirm && state.projectId !== record.id && hasDrawingContent()) {
    const proceed = await confirmAppAction("Open this cloud project? Your current drawing will be replaced.", {
      title: "Open cloud spool",
      confirmLabel: "Open spool",
      tone: "warning",
    });
    if (!proceed) return;
    persistState();
  }

  const restored = stateFromPayload(record.state);
  if (!restored) {
    showAppNotice("That cloud project could not be opened.");
    return;
  }

  state = restored;
  state.projectId = record.id;
  state.projectInfo = normalizeProjectInfo(record.projectInfo);
  state.projectInfoPrompted = true;
  currentCloudProjectOwnerId = normalizeUuid(record.ownerId);
  currentCloudProjectCompanyId = normalizeUuid(record.companyId);
  if (record.companyId) await activateCompanyFromId(record.companyId);
  const permissions = projectPermission(record, { source: "cloud" });
  cloudPermissionReadOnly = options.readOnly === true || !permissions.canEdit;
  markCloudSaveClean(record.updatedAt, { updateStatus: false });
  if (cloudPermissionReadOnly) {
    state.locked = true;
  }
  three.userMovedCamera = false;
  setNextIdsFromState(state);
  updateControls();
  withCloudDirtySuppressed(() => updateAll());
  closeProjectLibrary();
  updateCloudStatus("Cloud project opened", "saved");
  await loadProjectComments({ silent: true });
  window.setTimeout(() => updateCloudStatus(), 1600);
}

async function maybeOpenProjectFromUrl() {
  if (location.protocol === "file:") return false;
  const params = new URLSearchParams(location.search);
  const projectId = normalizeProjectId(params.get("project"));
  const traveller = params.get("traveller") === "1";
  if (!projectId) return false;

  await initSupabase();
  if (!cloudUser) {
    openAuthDialog({ startup: true });
    return true;
  }
  if (traveller) travellerRouteHandled = true;
  await openSavedCloudProject(projectId, {
    skipConfirm: true,
    readOnly: params.get("readonly") === "1",
  });
  if (traveller && state.projectId === projectId) openSpoolTraveller();
  return true;
}

function openSpoolTraveller() {
  document.querySelector("#spoolTravellerDialog")?.remove();
  const project = normalizeProjectInfo(state.projectInfo);
  const production = normalizeProductionInfo(state.productionInfo);
  const welds = synchronizeWeldRegister(state);
  const activeNotes = projectComments.filter((comment) => !comment.resolved);
  const photos = projectComments.filter((comment) => comment.photoPath);
  const drawingImage = buildSpoolReportCanvas("client").toDataURL("image/jpeg", 0.78);
  const dialog = document.createElement("div");
  dialog.id = "spoolTravellerDialog";
  dialog.className = "spool-traveller-backdrop";
  dialog.innerHTML = `
    <main class="spool-traveller" role="dialog" aria-modal="true" aria-label="Spool traveller">
      <header class="spool-traveller-header">
        <div><span>Spool traveller</span><h1>${escapeHtml(project.spoolNumber || "Unnamed spool")}</h1><code>${escapeHtml(currentRevisionUid(state))}</code></div>
        <button type="button" data-traveller-close aria-label="Close traveller">Close</button>
      </header>
      <img class="spool-traveller-drawing" src="${drawingImage}" alt="Current spool drawing revision ${escapeHtml(project.revision || "-")}" />
      <section class="spool-traveller-grid">
        <article><span>Revision</span><strong>${escapeHtml(project.revision || "-")}</strong></article>
        <article><span>Stage</span><strong>${escapeHtml(projectStatusLabel())}</strong></article>
        <article><span>Assigned</span><strong>${escapeHtml(production.assignee || "Unassigned")}</strong></article>
        <article><span>Due</span><strong>${escapeHtml(formatProductionDue(production) || "Not set")}</strong></article>
      </section>
      ${production.hold ? `<section class="spool-traveller-hold"><strong>ON HOLD</strong><p>${escapeHtml(production.holdReason || "No reason recorded")}</p></section>` : ""}
      <section class="spool-traveller-section"><h2>Current notes</h2>${activeNotes.length ? `<ul>${activeNotes.slice(-12).map((comment) => `<li><p>${escapeHtml(comment.body)}</p><span>${escapeHtml(comment.authorEmail || "Team member")} / ${escapeHtml(comment.createdAt ? new Date(comment.createdAt).toLocaleString() : "")}</span></li>`).join("")}</ul>` : `<p>No active spool notes.</p>`}</section>
      <section class="spool-traveller-section"><h2>Workshop photos</h2><div class="spool-traveller-photos">${photos.length ? photos.slice(-12).map((comment) => `<figure><img data-traveller-photo="${escapeHtml(comment.photoPath)}" alt="Workshop photo" loading="lazy" /><figcaption>${escapeHtml(comment.body)}</figcaption></figure>`).join("") : `<p>No workshop photos attached.</p>`}</div></section>
      <section class="spool-traveller-section"><h2>Weld register</h2>${welds.length ? `<div class="traveller-weld-list">${welds.map((weld) => `<article><strong>${escapeHtml(weld.number)}</strong><span>${escapeHtml(weldStatusLabel(weld.status))}</span><small>${escapeHtml([weld.welderId && `Welder ${weld.welderId}`, weld.wps, weld.inspectionType].filter(Boolean).join(" / ") || "Details pending")}</small></article>`).join("")}</div>` : `<p>No weld markers registered.</p>`}</section>
    </main>`;
  document.body.append(dialog);
  dialog.querySelector("[data-traveller-close]")?.addEventListener("click", () => dialog.remove());
  dialog.addEventListener("click", (event) => { if (event.target === dialog) dialog.remove(); });
  dialog.querySelectorAll("[data-traveller-photo]").forEach((image) => hydrateProjectCommentPhoto(image, image.dataset.travellerPhoto));
}

async function deleteSavedCloudProject(projectId) {
  let record = (cloudProjectCache ?? []).find((project) => project.id === projectId);
  if (!record) {
    const projects = await loadSavedCloudProjects();
    record = projects.find((project) => project.id === projectId);
  }
  if (!record) return;
  if (!projectPermission(record, { source: "cloud" }).canDelete) {
    showAppNotice("Only the project owner or a team admin can delete this cloud spool.");
    return;
  }

  const proceed = await confirmAppAction(`Delete ${record.name || projectDisplayName(record.projectInfo)} from the cloud?`, {
    title: "Delete cloud spool",
    confirmLabel: "Delete",
    tone: "error",
  });
  if (!proceed) return;

  const { error } = await supabaseClient
    .from(CLOUD_PROJECTS_TABLE)
    .delete()
    .eq("id", projectId);
  if (error) {
    showAppNotice("Could not delete that cloud project.");
    throw error;
  }
  cloudProjectCache = null;
  if (state.projectId === projectId) {
    state.projectId = null;
    currentCloudProjectOwnerId = null;
    currentCloudProjectCompanyId = null;
    cloudPermissionReadOnly = false;
    resetCloudSaveTracking();
    projectComments = [];
    projectCommentsProjectId = null;
    updateControls();
    persistState();
  }
  const projects = await loadSavedCloudProjects();
  renderProjectLibrary(projects, { source: "cloud" });
}

function loadSavedBrowserProjects() {
  try {
    const raw = JSON.parse(localStorage.getItem(SAVED_PROJECTS_KEY));
    if (!Array.isArray(raw)) return [];
    return raw
      .map((project) => ({
        id: normalizeProjectId(project.id),
        name: String(project.name ?? "").trim().slice(0, 120),
        updatedAt: String(project.updatedAt ?? ""),
        projectInfo: normalizeProjectInfo(project.projectInfo),
        state: project.state,
      }))
      .filter((project) => project.id && stateFromPayload(project.state));
  } catch {
    return [];
  }
}

function storeSavedBrowserProjects(projects) {
  localStorage.setItem(SAVED_PROJECTS_KEY, JSON.stringify(projects));
}

function browserProjectRecord() {
  const projectInfo = normalizeProjectInfo(state.projectInfo);
  const id = normalizeProjectId(state.projectId) ?? createProjectId();
  state.projectId = id;
  return {
    id,
    name: projectDisplayName(projectInfo),
    updatedAt: new Date().toISOString(),
    projectInfo,
    state: statePayload(),
  };
}

function autoSaveCurrentBrowserProject() {
  if (!state.projectId) return;
  const projects = loadSavedBrowserProjects();
  const record = browserProjectRecord();
  const existingIndex = projects.findIndex((project) => project.id === record.id);
  if (existingIndex >= 0) {
    projects[existingIndex] = record;
  } else {
    projects.unshift(record);
  }
  storeSavedBrowserProjects(projects);
}

async function saveBrowserProject(options = {}) {
  if (cloudPermissionReadOnly && currentProjectHasCloudRecord()) {
    showAppNotice("This team spool is view/comment only for your role. Ask the project owner or a team admin to save changes.");
    return false;
  }
  const info = await openProjectDetailsDialog({
    title: state.projectId ? "Save project" : cloudUser && hasActiveCloudLicense() ? "Save cloud project" : "Save as project",
    action: "Save project",
    defaults: state.projectInfo,
  });
  if (!info) return false;

  state.projectInfo = info;
  state.projectInfoPrompted = true;
  if (!state.projectId) {
    state.projectId = createProjectId();
  }
  updateControls();
  updateAll();
  const savedToCloud = cloudUser && hasActiveCloudLicense()
    ? await saveCloudProject({ silent: true }).catch((error) => {
        console.warn("Cloud save failed.", error);
        markCloudSaveFailed(error);
        return false;
      })
    : false;
  if (!options.silent) {
    showAppNotice(`Saved ${projectDisplayName(info)} ${savedToCloud ? "to the cloud and this browser" : "in this browser"}.`);
  }
  return true;
}

async function openBrowserProject(options = {}) {
  ensureProjectLibraryDashboardShell();
  projectLibraryGuideVisible = false;
  projectLibraryCommsVisible = false;
  projectLibraryReportVisible = false;
  ensureProjectLibraryGuideSlot();
  ensureProjectLibraryCommsSlot();
  ensureProjectLibraryReportSlot();
  if (!options.keepSearch) {
    projectLibrarySearch = "";
    if (projectLibrarySearchInput) projectLibrarySearchInput.value = "";
  }
  if (!options.keepFolder) {
    projectLibraryOpenFolderKey = "";
  }
  const useCloud = Boolean(cloudUser && hasActiveCloudLicense());
  projectLibrarySource = useCloud ? "cloud" : "browser";
  if (projectLibrarySubtitle) {
    projectLibrarySubtitle.textContent = useCloud
      ? "Loading cloud saved spools. The list will appear here."
      : "Loading saved spools from this device/browser.";
  }
  renderProjectLibraryMessage(useCloud ? "Loading cloud saved spools..." : "Loading saved spools...");
  showProjectLibraryDialog();

  let projects = [];
  if (useCloud) {
    try {
      updateCloudStatus("Loading cloud...", "");
      projects = await promiseWithTimeout(loadSavedCloudProjects(), 12000, "Cloud projects took too long to load.");
      updateCloudStatus();
    } catch (error) {
      console.warn("Could not load cloud projects.", error);
      updateCloudStatus("Cloud load failed", "warning");
      renderProjectLibraryMessage("Cloud projects could not be loaded. Showing projects saved in this browser instead.");
      projects = loadSavedBrowserProjects();
    }
  } else {
    projects = loadSavedBrowserProjects();
  }

  projects = projects
    .sort((first, second) => String(second.updatedAt).localeCompare(String(first.updatedAt)));
  renderProjectLibrary(projects, { source: useCloud && projects.every((project) => project.source === "cloud") ? "cloud" : "browser" });
  showProjectLibraryDialog();
  if (!projectLibraryDialog && !projects.length) {
    showAppNotice(useCloud ? "No cloud projects saved yet." : "No saved projects in this browser yet.");
  }
}

function readProjectLibraryFolderOpenState() {
  try {
    const raw = JSON.parse(localStorage.getItem(PROJECT_LIBRARY_FOLDER_STATE_KEY));
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) return new Map();
    return new Map(
      Object.entries(raw)
        .filter(([, open]) => typeof open === "boolean")
        .slice(-240)
    );
  } catch {
    return new Map();
  }
}

function storeProjectLibraryFolderOpenState() {
  try {
    localStorage.setItem(PROJECT_LIBRARY_FOLDER_STATE_KEY, JSON.stringify(Object.fromEntries(projectLibraryFolderOpenState)));
  } catch (error) {
    console.warn("Could not save job folder state.", error);
  }
}

function projectLibraryFolderStateKey(folderKey, source = projectLibrarySource) {
  return `${source || "browser"}::${folderKey}`;
}

function projectLibraryFolderOpenPreference(folderKey) {
  return projectLibraryFolderOpenState.get(projectLibraryFolderStateKey(folderKey));
}

function rememberProjectLibraryFolderOpen(folderKey, open) {
  if (!folderKey) return;
  projectLibraryFolderOpenState.set(projectLibraryFolderStateKey(folderKey), Boolean(open));
  if (projectLibraryFolderOpenState.size > 240) {
    const oldestKey = projectLibraryFolderOpenState.keys().next().value;
    projectLibraryFolderOpenState.delete(oldestKey);
  }
  storeProjectLibraryFolderOpenState();
}

function showProjectLibraryDialog() {
  if (projectLibraryDialog) {
    projectLibraryDialog.hidden = false;
  }
}

function renderProjectLibraryMessage(message) {
  if (!projectLibraryList) return;
  ensureProjectLibraryDashboardShell();
  ensureProjectLibraryGuideSlot();
  ensureProjectLibraryCommsSlot();
  ensureProjectLibraryReportSlot();
  projectLibraryList.innerHTML = "";
  const notice = document.createElement("div");
  notice.className = "project-library-empty";
  notice.textContent = message;
  projectLibraryList.append(notice);
}

function promiseWithTimeout(promise, timeoutMs, message = "Timed out") {
  return new Promise((resolve, reject) => {
    const timer = window.setTimeout(() => reject(new Error(message)), timeoutMs);
    promise
      .then((value) => {
        window.clearTimeout(timer);
        resolve(value);
      })
      .catch((error) => {
        window.clearTimeout(timer);
        reject(error);
      });
  });
}

function renderProjectLibrary(projects = loadSavedBrowserProjects(), options = {}) {
  if (!projectLibraryList) return;
  ensureProjectLibraryDashboardShell();
  ensureProjectLibraryGuideSlot();
  ensureProjectLibraryCommsSlot();
  ensureProjectLibraryReportSlot();
  projectLibrarySource = options.source === "cloud" ? "cloud" : "browser";
  projectLibraryProjects = Array.isArray(projects) ? [...projects] : [];
  const filteredProjects = filterProjectLibraryProjects(projectLibraryProjects);
  const query = projectLibrarySearch.trim();
  if (projectLibraryCommsVisible) renderProjectLibraryComms(filteredProjects);
  if (projectLibraryReportVisible) renderProjectLibraryReport(filteredProjects);
  if (projectLibrarySearchInput && projectLibrarySearchInput.value !== projectLibrarySearch) {
    projectLibrarySearchInput.value = projectLibrarySearch;
  }
  if (projectLibrarySubtitle) {
    projectLibrarySubtitle.textContent = projectLibrarySource === "cloud"
      ? activeCompanyIsApproved()
        ? `Cloud projects include your own spools and ${activeCompany.name} team spools. Use the production board or open a job folder.`
        : "Projects are saved to your SpoolMate cloud account. Use the production board or open a job folder."
      : "Projects are saved on this device/browser. Use the production board or open a job folder.";
  }
  projectLibraryList.innerHTML = "";

  if (!projectLibraryProjects.length) {
    const empty = document.createElement("div");
    empty.className = "project-library-empty";
    empty.textContent = projectLibrarySource === "cloud"
      ? "No cloud projects yet. Fill in the project details, then press Save."
      : "No saved projects yet. Fill in the project details, then press Save.";
    projectLibraryList.append(empty);
    return;
  }

  if (projectLibraryOpenFolderKey) {
    const openFolder = projectFolders(projectLibraryProjects).find((folder) => folder.key === projectLibraryOpenFolderKey);
    if (openFolder) {
      renderProjectLibraryFolderWindow(openFolder);
      return;
    }
    projectLibraryOpenFolderKey = "";
  }

  projectLibraryList.append(projectDashboardCard(filteredProjects, { totalCount: projectLibraryProjects.length, query }));

  if (!filteredProjects.length) {
    const empty = document.createElement("div");
    empty.className = "project-library-empty";
    empty.textContent = `No saved spools match "${query}".`;
    projectLibraryList.append(empty);
    return;
  }

  projectLibraryList.append(projectProductionBoard(filteredProjects));

  const folders = projectFolders(filteredProjects);
  for (const folder of folders) {
    const section = document.createElement("section");
    section.className = "project-folder";
    section.dataset.projectFolderKey = folder.key;

    const summary = document.createElement("button");
    summary.type = "button";
    summary.className = "project-folder-summary project-folder-launcher";
    summary.dataset.projectFolderOpen = folder.key;
    summary.setAttribute("aria-label", `Open ${folder.title} saved spools`);
    summary.title = "Open this job";

    const folderMain = document.createElement("div");
    folderMain.className = "project-folder-main";

    const title = document.createElement("strong");
    title.textContent = folder.title;

    const meta = document.createElement("span");
    meta.textContent = folder.meta;

    folderMain.append(title, meta);

    const count = document.createElement("span");
    count.className = "project-folder-count";
    count.textContent = `${folder.projects.length} spool${folder.projects.length === 1 ? "" : "s"}`;

    const openIcon = document.createElement("span");
    openIcon.className = "project-folder-toggle-icon";
    openIcon.setAttribute("aria-hidden", "true");
    openIcon.textContent = "Open";

    summary.append(folderMain, count, openIcon);
    section.append(summary);
    projectLibraryList.append(section);
  }
}

function renderProjectLibraryFolderWindow(folder) {
  if (!projectLibraryList) return;
  projectLibraryList.innerHTML = "";
  if (projectLibrarySubtitle) {
    projectLibrarySubtitle.textContent = `${folder.title} is open. Pick a spool drawing, or go back to all jobs.`;
  }

  const windowCard = document.createElement("section");
  windowCard.className = "project-job-window";
  windowCard.dataset.projectFolderKey = folder.key;

  const header = document.createElement("div");
  header.className = "project-job-window-header";

  const copy = document.createElement("div");
  copy.className = "project-job-window-title";
  const title = document.createElement("strong");
  title.textContent = folder.title;
  const meta = document.createElement("span");
  meta.textContent = `${folder.projects.length} spool${folder.projects.length === 1 ? "" : "s"} / ${folder.meta}`;
  copy.append(title, meta);

  const backButton = document.createElement("button");
  backButton.type = "button";
  backButton.className = "project-library-action";
  backButton.dataset.projectFolderBack = "true";
  backButton.textContent = "Back to jobs";

  header.append(copy, backButton);
  windowCard.append(header);
  windowCard.append(projectJobSummaryCard(folder));

  const drawings = document.createElement("div");
  drawings.className = "project-job-window-spools";
  for (const project of folder.projects) {
    drawings.append(projectLibraryRow(project));
  }
  windowCard.append(drawings);
  projectLibraryList.append(windowCard);
}

function openProjectLibraryFolder(folderKey) {
  if (!folderKey) return;
  projectLibraryOpenFolderKey = folderKey;
  renderProjectLibrary(projectLibraryProjects, { source: projectLibrarySource });
}

function closeProjectLibraryFolder() {
  projectLibraryOpenFolderKey = "";
  renderProjectLibrary(projectLibraryProjects, { source: projectLibrarySource });
}

function toggleProjectFolder(folder, forceOpen = null) {
  if (!folder) return;
  const open = forceOpen === null ? !folder.classList.contains("open") : Boolean(forceOpen);
  folder.classList.toggle("open", open);
  const toggle = folder.querySelector("[data-project-folder-toggle]");
  const title = folder.querySelector(".project-folder-main strong")?.textContent || "saved spools";
  const toggleIcon = folder.querySelector("[data-project-folder-icon]");
  const drawings = folder.querySelector(".project-folder-drawings");
  toggle?.setAttribute("aria-expanded", String(open));
  toggle?.setAttribute("aria-label", `${open ? "Hide" : "Show"} ${title} saved spools`);
  if (toggle) toggle.title = `${open ? "Hide" : "Show"} saved spools`;
  if (toggleIcon) toggleIcon.textContent = open ? "-" : "+";
  if (drawings) drawings.hidden = !open;
  rememberProjectLibraryFolderOpen(folder.dataset.projectFolderKey, open);
}

function savedProjectState(project) {
  return project?.state?.state && typeof project.state.state === "object" ? project.state.state : project?.state;
}

function savedProjectProductionInfo(project) {
  return normalizeProductionInfo(savedProjectState(project)?.productionInfo);
}

function savedProjectProductionMessages(project) {
  return activeProductionMessages(savedProjectState(project)?.productionMessages);
}

function savedProjectProductionActivity(project) {
  return normalizeProductionActivity(savedProjectState(project)?.productionActivity);
}

function productionAlertPriority(type) {
  if (type === "returned") return 0;
  if (type === "overdue") return 1;
  if (type === "due") return 2;
  if (type === "soon") return 3;
  if (type === "readycheck") return 4;
  if (type === "comment" || type === "message") return 5;
  if (type === "mine") return 6;
  if (type === "revision" || type === "issued") return 7;
  if (type === "fabricated") return 8;
  return 9;
}

function teamAlertDateText(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return "";
  return date.toLocaleDateString(undefined, { day: "numeric", month: "short" });
}

function recentProjectActivity(project, predicate) {
  const entry = savedProjectProductionActivity(project)
    .slice()
    .reverse()
    .find((item) => predicate(item));
  const date = projectReportDate(entry?.createdAt);
  if (!entry || !date || Date.now() - date.getTime() > TEAM_ALERT_RECENT_MS) return null;
  return { entry, date };
}

function recentProjectStatusDate(project, status) {
  const savedState = savedProjectState(project);
  if (normalizeProjectStatus(savedState?.projectStatus) !== status) return null;

  const statusLabel = projectStatusLabel(status).toLowerCase();
  const activityDate = savedProjectProductionActivity(project)
    .slice()
    .reverse()
    .find((entry) => entry.type === "status" && String(entry.text ?? "").toLowerCase().includes(statusLabel));
  const production = savedProjectProductionInfo(project);
  const dates = [
    projectReportDate(activityDate?.createdAt),
    status === "complete" ? projectReportDate(production.completedAt) : null,
    projectReportDate(production.lastUpdatedAt),
  ].filter(Boolean);

  if (!dates.length) return null;
  const latest = new Date(Math.max(...dates.map((date) => date.getTime())));
  return Date.now() - latest.getTime() <= TEAM_ALERT_RECENT_MS ? latest : null;
}

function loadedProjectCommentForAlert(project) {
  if (!project?.id || projectCommentsProjectId !== project.id || !Array.isArray(projectComments)) return null;
  const latest = [...projectComments]
    .filter((comment) => !comment.resolved)
    .sort((first, second) =>
      (new Date(second.createdAt).getTime() || 0) - (new Date(first.createdAt).getTime() || 0),
    )[0];
  const created = projectReportDate(latest?.createdAt);
  if (!latest || !created || Date.now() - created.getTime() > TEAM_ALERT_RECENT_MS) return null;
  return latest;
}

function projectTeamAlertItems(projects = projectLibraryProjects) {
  const items = [];
  for (const project of Array.isArray(projects) ? projects : []) {
    if (productionProjectHidden(project)) continue;
    const savedState = savedProjectState(project);
    const status = normalizeProjectStatus(savedState?.projectStatus);
    const production = savedProjectProductionInfo(project);
    const dueState = productionDueState(production);
    const dueTime = dueState.dueDate?.getTime() ?? Number.MAX_SAFE_INTEGER;
    if (status !== "complete" && dueState.key === "overdue") {
      items.push({ project, type: "overdue", title: "Overdue", body: `${formatProductionDue(production)} / ${projectStatusLabel(status)}`, dueTime });
    } else if (status !== "complete" && dueState.key === "today") {
      items.push({ project, type: "due", title: "Due today", body: `${formatProductionDue(production)} / ${projectStatusLabel(status)}`, dueTime });
    } else if (status !== "complete" && dueState.key === "soon") {
      items.push({ project, type: "soon", title: "Due soon", body: `${formatProductionDue(production)} / ${projectStatusLabel(status)}`, dueTime });
    }
    if (status === "readycheck") {
      items.push({ project, type: "readycheck", title: "Ready to check", body: "Waiting for checking/sign-off.", dueTime });
    }
    if (status !== "complete" && productionAssignedToCurrentUser(production)) {
      items.push({ project, type: "mine", title: "Assigned to you", body: `${projectStatusLabel(status)}${production.dueDate ? ` / due ${formatProductionDue(production)}` : ""}`, dueTime });
    }
    const returnedReview = status === "draft"
      ? recentProjectActivity(project, (entry) => entry.type === "review" && /^Returned for changes/i.test(entry.text))
      : null;
    if (returnedReview) {
      items.push({
        project,
        type: "returned",
        title: "Returned by checker",
        body: returnedReview.entry.text,
        dueTime,
        eventTime: returnedReview.date.getTime(),
      });
    }
    const activeMessage = [...savedProjectProductionMessages(project)].reverse().find((message) => !message.completed);
    if (activeMessage) {
      const eventTime = new Date(activeMessage.createdAt).getTime() || 0;
      items.push({ project, type: "comment", title: "New comment", body: activeMessage.body, dueTime, eventTime });
    }
    const cloudComment = loadedProjectCommentForAlert(project);
    const returnedConversationDuplicate = returnedReview && /^RETURNED FOR CHANGES/i.test(cloudComment?.body ?? "");
    if (cloudComment && !returnedConversationDuplicate) {
      const eventTime = new Date(cloudComment.createdAt).getTime() || 0;
      const author = cloudComment.authorEmail ? `${cloudComment.authorEmail}: ` : "";
      items.push({
        project,
        type: "comment",
        title: projectCommentMentionsCurrentUser(cloudComment) ? "Mentioned you" : "Spool message",
        body: `${author}${cloudComment.body}`,
        dueTime,
        eventTime,
      });
    }
    const revisionIssue = recentProjectActivity(project, (entry) => entry.type === "revision" && /\bissued by\b/i.test(entry.text));
    const issuedDate = revisionIssue?.date ?? recentProjectStatusDate(project, "issued");
    if (issuedDate) {
      const revision = normalizeProjectInfo(savedState?.projectInfo).revision || "-";
      items.push({
        project,
        type: "revision",
        title: `Revision ${revision} issued`,
        body: revisionIssue
          ? `${revisionIssue.entry.actor || "Team"} / ${teamAlertDateText(issuedDate)}`
          : `Issued ${teamAlertDateText(issuedDate)}`,
        dueTime: Number.MAX_SAFE_INTEGER,
        eventTime: issuedDate.getTime(),
      });
    }
    const fabricatedDate = recentProjectStatusDate(project, "complete");
    if (fabricatedDate) {
      items.push({
        project,
        type: "fabricated",
        title: "Spool fabricated",
        body: `Fabricated ${teamAlertDateText(fabricatedDate)}`,
        dueTime: Number.MAX_SAFE_INTEGER,
        eventTime: fabricatedDate.getTime(),
      });
    }
  }
  return items
    .sort((first, second) =>
      productionAlertPriority(first.type) - productionAlertPriority(second.type) ||
      first.dueTime - second.dueTime ||
      (second.eventTime ?? 0) - (first.eventTime ?? 0),
    )
    .slice(0, 12);
}

function projectAlertCard(projects = projectLibraryProjects) {
  const alerts = projectTeamAlertItems(projects);
  const section = document.createElement("section");
  section.className = "project-alert-card";
  section.innerHTML = `
    <div class="project-alert-head">
      <div>
        <strong>Team alerts</strong>
        <span>${alerts.length ? `${alerts.length} item${alerts.length === 1 ? "" : "s"} needing attention` : "No urgent team alerts in this view."}</span>
      </div>
    </div>
    <div class="project-alert-list">
      ${alerts.length ? alerts.map((alert) => `
        <article class="project-alert-item ${escapeHtml(alert.type)}">
          <button type="button" data-open-project-id="${escapeHtml(alert.project.id)}" data-project-source="${escapeHtml(alert.project.source ?? projectLibrarySource)}">
            <strong>${escapeHtml(alert.title)}</strong>
            <span>${escapeHtml(savedProjectSpoolTitle(alert.project))}</span>
            <small>${escapeHtml(alert.body)}</small>
          </button>
        </article>
      `).join("") : `<div class="project-alert-empty">Nothing due, returned, assigned, ready to check, commented, issued or fabricated recently.</div>`}
    </div>
  `;
  return section;
}

function projectJobMetrics(projects = []) {
  const visible = (Array.isArray(projects) ? projects : []).filter((project) => !productionProjectHidden(project));
  return visible.reduce((summary, project) => {
    const status = normalizeProjectStatus(savedProjectState(project)?.projectStatus);
    const production = savedProjectProductionInfo(project);
    const dueState = productionDueState(production);
    summary.total += 1;
    if (status === "readycheck") summary.readycheck += 1;
    if (status === "checked") summary.checked += 1;
    if (status === "issued") summary.issued += 1;
    if (status === "complete") summary.fabricated += 1;
    if (status !== "complete" && dueState.key === "overdue") summary.overdue += 1;
    if (status !== "complete" && dueState.key === "today") summary.dueToday += 1;
    if (status !== "complete" && production.hold) summary.onHold += 1;
    return summary;
  }, { total: 0, readycheck: 0, checked: 0, issued: 0, fabricated: 0, overdue: 0, dueToday: 0, onHold: 0 });
}

function projectNeedsTodayItems(projects = []) {
  return sortedProductionProjects((Array.isArray(projects) ? projects : [])
    .filter((project) => {
      const status = normalizeProjectStatus(savedProjectState(project)?.projectStatus);
      if (status === "complete") return false;
      const production = savedProjectProductionInfo(project);
      const dueState = productionDueState(production);
      return ["overdue", "today"].includes(dueState.key) || status === "readycheck" || production.hold;
    }))
    .slice(0, 10);
}

function projectJobSummaryCard(folder) {
  const metrics = projectJobMetrics(folder.projects);
  const needsToday = projectNeedsTodayItems(folder.projects);
  const section = document.createElement("section");
  section.className = "project-job-summary-card";
  section.innerHTML = `
    <div class="project-job-summary-stats">
      <div><b>${metrics.total}</b><span>Total</span></div>
      <div><b>${metrics.readycheck}</b><span>Ready check</span></div>
      <div><b>${metrics.checked}</b><span>Checked</span></div>
      <div><b>${metrics.issued}</b><span>Issued</span></div>
      <div><b>${metrics.fabricated}</b><span>Fabricated</span></div>
      <div><b>${metrics.overdue}</b><span>Overdue</span></div>
      <div><b>${metrics.onHold}</b><span>On hold</span></div>
    </div>
    <div class="project-job-today">
      <strong>Needs doing today</strong>
      <div>
        ${needsToday.length ? needsToday.map((project) => {
          const production = savedProjectProductionInfo(project);
          const dueState = productionDueState(production);
          const status = normalizeProjectStatus(savedProjectState(project)?.projectStatus);
          const reason = production.hold
            ? `Hold: ${production.holdReason || "No reason entered"}`
            : dueState.key === "overdue"
              ? `Overdue / ${formatProductionDue(production)}`
              : dueState.key === "today"
                ? `Due today / ${formatProductionDue(production)}`
                : projectStatusLabel(status);
          return `
            <button type="button" data-open-project-id="${escapeHtml(project.id)}" data-project-source="${escapeHtml(project.source ?? projectLibrarySource)}">
              <span>${escapeHtml(savedProjectSpoolTitle(project))}</span>
              <small>${escapeHtml(reason)}</small>
            </button>
          `;
        }).join("") : `<span class="project-job-empty">No due, overdue, hold or ready-to-check spools in this job.</span>`}
      </div>
    </div>
  `;
  return section;
}

function productionPriorityRank(value) {
  const priority = normalizeProductionPriority(value);
  if (priority === "urgent") return 0;
  if (priority === "high") return 1;
  if (priority === "normal") return 2;
  return 3;
}

function sortedProductionProjects(projects) {
  return [...projects].sort((first, second) => {
    const firstInfo = savedProjectProductionInfo(first);
    const secondInfo = savedProjectProductionInfo(second);
    if (firstInfo.hold !== secondInfo.hold) return firstInfo.hold ? -1 : 1;
    const priority = productionPriorityRank(firstInfo.priority) - productionPriorityRank(secondInfo.priority);
    if (priority !== 0) return priority;
    const firstDue = `${firstInfo.dueDate || "9999-99-99"} ${firstInfo.dueTime || "99:99"}`;
    const secondDue = `${secondInfo.dueDate || "9999-99-99"} ${secondInfo.dueTime || "99:99"}`;
    if (firstDue !== secondDue) return firstDue.localeCompare(secondDue);
    return String(second.updatedAt).localeCompare(String(first.updatedAt));
  });
}

function normalizeProductionBoardFilter(value) {
  const key = String(value ?? "").trim().toLowerCase();
  return PRODUCTION_BOARD_FILTER_KEYS.has(key) ? key : "active";
}

function setProjectLibraryBoardFilter(value) {
  projectLibraryBoardFilter = normalizeProductionBoardFilter(value);
  renderProjectLibrary(projectLibraryProjects, { source: projectLibrarySource });
}

function productionCurrentAssigneeNames() {
  return new Set([
    cloudUser?.email,
    checkerName(),
    normalizeProjectInfo(state.projectInfo).drawnBy,
  ]
    .map((value) => String(value ?? "").trim().toLowerCase())
    .filter(Boolean));
}

function productionAssignedToCurrentUser(production) {
  const assignee = normalizeProductionInfo(production).assignee.toLowerCase();
  return Boolean(assignee && productionCurrentAssigneeNames().has(assignee));
}

function productionDueState(production) {
  const dueDate = projectReportDueDate(production);
  if (!dueDate) return { key: "none", label: "No due date", dueDate: null };
  const now = new Date();
  const todayStart = new Date(now);
  todayStart.setHours(0, 0, 0, 0);
  const todayEnd = new Date(now);
  todayEnd.setHours(23, 59, 59, 999);
  const soonEnd = new Date(todayEnd);
  soonEnd.setDate(soonEnd.getDate() + 6);
  if (dueDate.getTime() < todayStart.getTime()) return { key: "overdue", label: "Overdue", dueDate };
  if (dueDate.getTime() <= todayEnd.getTime()) return { key: "today", label: "Due today", dueDate };
  if (dueDate.getTime() <= soonEnd.getTime()) return { key: "soon", label: "Due soon", dueDate };
  return { key: "dated", label: "Scheduled", dueDate };
}

function productionBoardAssigneeChoices(projects = projectLibraryProjects) {
  const choices = new Set();
  if (cloudUser?.email) choices.add(cloudUser.email);
  for (const member of companyMembers) {
    if (member.status === "approved" && member.email) choices.add(member.email);
  }
  for (const project of Array.isArray(projects) ? projects : []) {
    const info = normalizeProjectInfo(project.projectInfo);
    const production = savedProjectProductionInfo(project);
    if (production.assignee) choices.add(production.assignee);
    if (info.drawnBy) choices.add(info.drawnBy);
  }
  return [...choices].filter(Boolean).slice(0, 40);
}

function productionProjectMatchesBoardFilter(project, filter = projectLibraryBoardFilter) {
  if (productionProjectHidden(project)) return false;
  const status = normalizeProjectStatus(savedProjectState(project)?.projectStatus);
  const production = savedProjectProductionInfo(project);
  const dueState = productionDueState(production);
  const normalized = normalizeProductionBoardFilter(filter);
  if (normalized === "all") return true;
  if (normalized === "active") return status !== "complete";
  if (normalized === "today") return status !== "complete" && dueState.key === "today";
  if (normalized === "due") return status !== "complete" && ["overdue", "today", "soon"].includes(dueState.key);
  if (normalized === "overdue") return status !== "complete" && dueState.key === "overdue";
  if (normalized === "readycheck") return status === "readycheck";
  if (normalized === "hold") return status !== "complete" && production.hold;
  if (normalized === "mine") return status !== "complete" && productionAssignedToCurrentUser(production);
  if (normalized === "message") return status !== "complete" && savedProjectProductionMessages(project).some((message) => !message.completed);
  return status !== "complete";
}

function productionBoardFilterCounts(projects = projectLibraryProjects) {
  const visible = (Array.isArray(projects) ? projects : []).filter((project) => !productionProjectHidden(project));
  return Object.keys(PRODUCTION_BOARD_FILTERS).reduce((summary, filter) => {
    summary[filter] = visible.filter((project) => productionProjectMatchesBoardFilter(project, filter)).length;
    return summary;
  }, {});
}

function productionStatusQuickActions(status, canEdit, projectId) {
  const disabledAttr = canEdit ? "" : ' disabled title="View/comment only for your team role"';
  const actions = [
    ["readycheck", "Ready"],
    ["issued", "Issued"],
    ["complete", "Fabbed"],
  ].filter(([nextStatus]) => normalizeProjectStatus(status) !== nextStatus);
  return actions
    .map(([nextStatus, label]) => `<button type="button" data-production-action="set-status" data-status="${nextStatus}" data-project-id="${escapeHtml(projectId)}"${disabledAttr}>${label}</button>`)
    .join("");
}

function cloneProjectDrawingState(project) {
  try {
    return JSON.parse(JSON.stringify(project?.state ?? {}));
  } catch {
    return null;
  }
}

function drawingStateTarget(payload) {
  return payload?.state && typeof payload.state === "object" ? payload.state : payload;
}

function projectRecordWithState(project, nextDrawingState, updatedAt = new Date().toISOString()) {
  return {
    ...project,
    updatedAt,
    state: nextDrawingState,
    projectInfo: normalizeProjectInfo(project.projectInfo),
    name: project.name || projectDisplayName(project.projectInfo),
  };
}

function syncCurrentStateFromProjectState(projectId, targetState) {
  if (state.projectId !== projectId || !targetState) return;
  state.projectStatus = normalizeProjectStatus(targetState.projectStatus);
  state.productionInfo = normalizeProductionInfo(targetState.productionInfo);
  state.productionMessages = normalizeProductionMessages(targetState.productionMessages);
  state.productionActivity = normalizeProductionActivity(targetState.productionActivity);
  updateControls();
  updateAll();
}

async function persistProjectWorkflowUpdate(project, nextDrawingState, updatedAt) {
  const source = project.source ?? projectLibrarySource;
  const nextRecord = projectRecordWithState(project, nextDrawingState, updatedAt);

  if (source === "cloud") {
    if (!(await ensureSupabaseClient()) || !cloudUser || !hasActiveCloudLicense()) {
      showAppNotice("Sign in with an active licence to update cloud production items.");
      return false;
    }
    if (!projectPermission(project, { source: "cloud" }).canEdit) {
      showAppNotice("Only the project owner or a team admin can update this cloud spool.");
      return false;
    }
    updateCloudStatus("Updating production...", "");
    const { error } = await supabaseClient
      .from(CLOUD_PROJECTS_TABLE)
      .update({
        name: nextRecord.name,
        project_info: nextRecord.projectInfo,
        drawing_state: nextDrawingState,
        updated_at: updatedAt,
      })
      .eq("id", project.id);
    if (error) throw error;
    cloudProjectCache = null;
    updateCloudStatus("Production updated", "");
    window.setTimeout(() => updateCloudStatus(), 1500);
  } else {
    const projects = loadSavedBrowserProjects();
    const nextProjects = projects.map((item) => item.id === project.id ? nextRecord : item);
    storeSavedBrowserProjects(nextProjects);
  }

  projectLibraryProjects = projectLibraryProjects.map((item) => item.id === project.id ? nextRecord : item);
  syncCurrentStateFromProjectState(project.id, drawingStateTarget(nextDrawingState));
  renderProjectLibrary(projectLibraryProjects, { source: projectLibrarySource });
  return true;
}

async function updateSavedProjectWorkflow(projectId, updates = {}) {
  const project = projectLibraryProjects.find((item) => item.id === projectId);
  if (!project) return false;
  const nextDrawingState = cloneProjectDrawingState(project);
  const targetState = drawingStateTarget(nextDrawingState);
  if (!targetState) return false;

  const now = new Date().toISOString();
  const previousStatus = normalizeProjectStatus(targetState.projectStatus);
  const previousProduction = normalizeProductionInfo(targetState.productionInfo);
  const nextProduction = normalizeProductionInfo({
    ...targetState.productionInfo,
    ...(updates.productionInfo ?? {}),
    lastUpdatedBy: checkerName(),
    lastUpdatedAt: now,
  });
  let activity = normalizeProductionActivity(targetState.productionActivity);

  if (updates.status !== undefined) {
    const nextStatus = normalizeProjectStatus(updates.status);
    if (nextStatus === "checked" && previousStatus !== "checked") {
      throw new Error("Open the spool and use Approve drawing so the checker and comment are recorded.");
    }
    if (projectStatusAtLeast(nextStatus, "issued") && !targetState.checkedAt) {
      throw new Error("Approve the drawing before moving it to Issued or fabrication.");
    }
    if (projectStatusAtLeast(previousStatus, "checked") && projectStatusIndex(nextStatus) < projectStatusIndex("checked")) {
      throw new Error("Open the spool and use Return for changes so the checker comment and revision are preserved.");
    }
    targetState.projectStatus = nextStatus;
    if (nextStatus !== previousStatus) {
      activity = addProductionActivity(activity, "status", `Moved from ${projectStatusLabel(previousStatus)} to ${projectStatusLabel(nextStatus)}.`, now);
    }
    if (projectStatusAtLeast(nextStatus, "checked") && !targetState.checkedAt) {
      targetState.checkedAt = now;
      targetState.checkedBy = checkerName();
    }
    if (nextStatus === "complete") {
      nextProduction.completedAt = nextProduction.completedAt || now;
      nextProduction.removeAfter = nextProduction.removeAfter || isoDaysFromNow(7);
    } else {
      nextProduction.completedAt = "";
      nextProduction.removeAfter = "";
    }
  }

  const changedProduction = updates.productionInfo && typeof updates.productionInfo === "object" ? updates.productionInfo : {};
  if (Object.prototype.hasOwnProperty.call(changedProduction, "assignee") && previousProduction.assignee !== nextProduction.assignee) {
    activity = addProductionActivity(activity, "assignee", `Assigned changed from ${previousProduction.assignee || "Unassigned"} to ${nextProduction.assignee || "Unassigned"}.`, now);
  }
  if (
    (Object.prototype.hasOwnProperty.call(changedProduction, "dueDate") || Object.prototype.hasOwnProperty.call(changedProduction, "dueTime")) &&
    (previousProduction.dueDate !== nextProduction.dueDate || previousProduction.dueTime !== nextProduction.dueTime)
  ) {
    activity = addProductionActivity(activity, "due", `Due changed from ${formatProductionDue(previousProduction) || "No due date"} to ${formatProductionDue(nextProduction) || "No due date"}.`, now);
  }
  if (Object.prototype.hasOwnProperty.call(changedProduction, "priority") && previousProduction.priority !== nextProduction.priority) {
    activity = addProductionActivity(activity, "priority", `Priority changed from ${productionPriorityLabel(previousProduction.priority)} to ${productionPriorityLabel(nextProduction.priority)}.`, now);
  }
  if (Object.prototype.hasOwnProperty.call(changedProduction, "hold") && previousProduction.hold !== nextProduction.hold) {
    activity = addProductionActivity(activity, "hold", nextProduction.hold
      ? `Put on hold${nextProduction.holdReason ? `: ${nextProduction.holdReason}` : "."}`
      : "Hold removed.", now);
  }
  if (
    Object.prototype.hasOwnProperty.call(changedProduction, "holdReason") &&
    previousProduction.holdReason !== nextProduction.holdReason &&
    !(Object.prototype.hasOwnProperty.call(changedProduction, "hold") && nextProduction.hold)
  ) {
    activity = addProductionActivity(activity, "hold", `Hold reason changed from ${previousProduction.holdReason || "none"} to ${nextProduction.holdReason || "none"}.`, now);
  }

  let messages = normalizeProductionMessages(targetState.productionMessages);
  if (updates.addMessage) {
    const body = String(updates.addMessage).trim().slice(0, 240);
    if (body) {
      messages.push({
        id: `msg-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
        body,
        author: checkerName(),
        createdAt: now,
        completed: false,
        completedAt: "",
        removeAfter: "",
      });
      activity = addProductionActivity(activity, "message", `Added note: ${body}`, now);
    }
  }
  if (updates.completeMessageId) {
    const completedMessage = messages.find((message) => message.id === updates.completeMessageId);
    messages = messages.map((message) => message.id === updates.completeMessageId
      ? {
          ...message,
          completed: true,
          completedAt: now,
          removeAfter: message.removeAfter || isoDaysFromNow(7),
        }
      : message);
    if (completedMessage) {
      activity = addProductionActivity(activity, "message", `Marked note done: ${completedMessage.body}`, now);
    }
  }

  targetState.productionInfo = normalizeProductionInfo(nextProduction);
  targetState.productionMessages = normalizeProductionMessages(messages);
  targetState.productionActivity = normalizeProductionActivity(activity);
  targetState.projectStatus = normalizeProjectStatus(targetState.projectStatus);

  return persistProjectWorkflowUpdate(project, nextDrawingState, now);
}

function showProjectLibraryComms() {
  projectLibraryCommsVisible = true;
  projectLibraryGuideVisible = false;
  projectLibraryReportVisible = false;
  if (projectLibraryOpenFolderKey) {
    projectLibraryOpenFolderKey = "";
  }
  renderProjectLibrary(projectLibraryProjects, { source: projectLibrarySource });
  ensureProjectLibraryCommsSlot();
  renderProjectLibraryComms(projectLibraryProjects);
  renderProjectComments();
  if (cloudUser && state.projectId && projectCommentsProjectId !== state.projectId) {
    loadProjectComments({ silent: true }).catch((error) => {
      console.warn("Spool conversation refresh failed.", error);
      renderProjectComments("The current spool conversation could not be loaded.");
    });
  }
  if (projectLibrarySource === "cloud" && activeCompanyIsApproved()) {
    loadTeamMessages({ silent: true }).catch((error) => {
      console.warn("Team comms refresh failed.", error);
      renderProjectLibraryComms(projectLibraryProjects, "Team messages could not be loaded.");
    });
  }
  projectLibraryCommsSlot?.scrollIntoView({ behavior: "smooth", block: "start" });
}

function hideProjectLibraryComms() {
  projectLibraryCommsVisible = false;
  ensureProjectLibraryCommsSlot();
}

function dashboardCommsItems(projects = projectLibraryProjects) {
  return (Array.isArray(projects) ? projects : [])
    .flatMap((project) => {
      const messages = savedProjectProductionMessages(project)
        .filter((message) => !message.completed)
        .map((message) => ({
          project,
          message,
          createdTime: new Date(message.createdAt).getTime() || 0,
        }));
      return messages;
    })
    .sort((first, second) => second.createdTime - first.createdTime)
    .slice(0, 18);
}

function renderProjectLibraryComms(projects = projectLibraryProjects, errorMessage = "") {
  if (!projectLibraryCommsSlot) return;
  projectLibraryCommsSlot.hidden = !projectLibraryCommsVisible;
  if (projectLibrarySpoolConversation) projectLibrarySpoolConversation.hidden = !projectLibraryCommsVisible;
  if (!projectLibraryCommsVisible) return;

  const activeErrorMessage = errorMessage || teamMessagesError;
  const sourceLabel = projectLibrarySource === "cloud"
    ? activeCompanyIsApproved()
      ? activeCompany.name
      : "Cloud"
    : "Browser";
  const spoolMessages = dashboardCommsItems(projects);
  const cloudReady = Boolean(cloudUser && hasActiveCloudLicense() && activeCompanyIsApproved());
  const visibleTeamMessages = (teamMessagesCompanyId === activeCompany?.id ? teamMessages : [])
    .filter((message) => !message.completed || message.pinned)
    .slice(0, 12);

  projectLibraryCommsSlot.innerHTML = `
    <section class="team-comms-card" aria-label="Team communication">
      <div class="team-comms-head">
        <div>
          <strong>Team comms</strong>
          <span>${escapeHtml(sourceLabel)} messages, active yard notes and spool actions in one place.</span>
        </div>
        <div class="team-comms-actions">
          <button type="button" data-project-library-action="refresh-team-messages"${cloudReady ? "" : " disabled"}>Refresh</button>
          <button type="button" data-project-library-action="hide-comms">Hide</button>
        </div>
      </div>
      ${activeErrorMessage ? `<div class="team-comms-warning">${escapeHtml(activeErrorMessage)}</div>` : ""}
      <div class="team-comms-layout">
        <section class="team-comms-panel">
          <div class="team-comms-panel-head">
            <strong>General team messages</strong>
            <span>${cloudReady ? teamMessagesBusy ? "Refreshing..." : "Shared with the active company" : "Cloud team required"}</span>
          </div>
          ${cloudReady ? `
            <div class="team-comms-compose">
              <input data-team-message-input type="text" maxlength="500" placeholder="Message for the team" />
              <button type="button" data-project-library-action="add-team-message">Post</button>
            </div>
          ` : `
            <div class="team-comms-empty">Sign in to an approved company team to post shared team messages.</div>
          `}
          <div class="team-comms-list">
            ${visibleTeamMessages.length ? visibleTeamMessages.map(teamMessageHtml).join("") : `<div class="team-comms-empty">${cloudReady ? "No team messages yet." : "Team messages will appear here."}</div>`}
          </div>
        </section>
        <section class="team-comms-panel">
          <div class="team-comms-panel-head">
            <strong>Active spool notes</strong>
            <span>${spoolMessages.length} open message${spoolMessages.length === 1 ? "" : "s"} from production cards</span>
          </div>
          <div class="team-comms-list">
            ${spoolMessages.length ? spoolMessages.map(spoolMessageHtml).join("") : `<div class="team-comms-empty">No active spool messages on this dashboard.</div>`}
          </div>
        </section>
      </div>
    </section>
  `;
}

function teamMessageHtml(message) {
  const meta = [
    message.authorEmail || "Team member",
    message.createdAt ? new Date(message.createdAt).toLocaleString() : "Just now",
    message.pinned ? "Pinned" : "",
  ].filter(Boolean).join(" / ");
  return `
    <article class="team-comms-message${message.completed ? " done" : ""}${message.pinned ? " pinned" : ""}">
      <p>${escapeHtml(message.body)}</p>
      <small>${escapeHtml(meta)}</small>
      ${message.completed ? `<span class="team-comms-done">Done</span>` : `<button type="button" data-project-library-action="complete-team-message" data-team-message-id="${escapeHtml(message.id)}">Done</button>`}
    </article>
  `;
}

function spoolMessageHtml(item) {
  const { project, message } = item;
  const production = savedProjectProductionInfo(project);
  const meta = [
    savedProjectDetailLine(project),
    message.author ? `By ${message.author}` : "",
    message.createdAt ? new Date(message.createdAt).toLocaleString() : "",
    production.assignee ? `To ${production.assignee}` : "",
  ].filter(Boolean).join(" / ");
  return `
    <article class="team-comms-message spool-note">
      <button type="button" class="team-comms-open" data-open-project-id="${escapeHtml(project.id)}" data-project-source="${escapeHtml(project.source ?? projectLibrarySource)}">${escapeHtml(savedProjectSpoolTitle(project))}</button>
      <p>${escapeHtml(message.body)}</p>
      <small>${escapeHtml(meta)}</small>
      <button type="button" data-production-action="complete-message" data-project-id="${escapeHtml(project.id)}" data-message-id="${escapeHtml(message.id)}">Done</button>
    </article>
  `;
}

function showProjectLibraryGuide() {
  projectLibraryGuideVisible = true;
  projectLibraryCommsVisible = false;
  projectLibraryReportVisible = false;
  if (projectLibraryOpenFolderKey) {
    projectLibraryOpenFolderKey = "";
  }
  renderProjectLibrary(projectLibraryProjects, { source: projectLibrarySource });
  const guide = ensureProjectLibraryGuideSlot();
  if (!guide) {
    showAppNotice("The Jobs guide is at the top of the Job dashboard.");
    return;
  }
  guide.open = true;
  guide.scrollIntoView({ behavior: "smooth", block: "start" });
  guide.classList.add("attention");
  window.setTimeout(() => guide.classList.remove("attention"), 1400);
}

function hideProjectLibraryGuide() {
  projectLibraryGuideVisible = false;
  ensureProjectLibraryGuideSlot();
}

function bindProjectLibraryGuideCard(details) {
  if (!details || details.dataset.guideCardBound === "true") return details;
  details.dataset.guideCardBound = "true";
  return details;
}

function projectLibraryGuideCard() {
  const details = document.createElement("details");
  details.className = "project-guide-card";
  details.id = "projectJobsGuide";
  details.setAttribute("aria-label", "Jobs board guide");
  details.open = true;
  bindProjectLibraryGuideCard(details);

  const summary = document.createElement("summary");
  summary.textContent = "How to use this Jobs board";
  details.append(summary);

  const content = document.createElement("div");
  content.className = "project-guide-content";
  content.innerHTML = `
    <ol>
      <li>
        <strong>Save each spool first.</strong>
        <span>Use Save current so the spool appears in the job list and production board.</span>
      </li>
      <li>
        <strong>Move the spool through stages.</strong>
        <span>Drag a card to another stage, or use the Stage menu on the card. You can also change the open drawing from the top Status menu.</span>
      </li>
      <li>
        <strong>Allocate the work.</strong>
        <span>Use the card fields for Assigned, Due, Priority and Hold. The same details are also in Review &gt; Checks &gt; Workflow.</span>
      </li>
      <li>
        <strong>Use messages for yard notes.</strong>
        <span>Add a message to a card, mark it Done when handled, and it will be set to disappear after one week.</span>
      </li>
      <li>
        <strong>Open Comms for the team view.</strong>
        <span>Use Comms to post general team messages and see all active spool notes in one place.</span>
      </li>
    </ol>
    <p>Quick rule: the board is for tracking production. Use Open when you need to edit the drawing itself.</p>
    <div class="project-guide-actions">
      <button type="button" data-project-library-action="hide-guide">Hide guide</button>
    </div>
  `;
  details.append(content);
  return details;
}

function showProjectLibraryReport() {
  projectLibraryReportVisible = true;
  projectLibraryGuideVisible = false;
  projectLibraryCommsVisible = false;
  if (projectLibraryOpenFolderKey) {
    projectLibraryOpenFolderKey = "";
  }
  renderProjectLibrary(projectLibraryProjects, { source: projectLibrarySource });
  const slot = ensureProjectLibraryReportSlot();
  if (!slot) {
    showAppNotice("The Jobs report could not be shown.");
    return;
  }
  renderProjectLibraryReport();
  slot.hidden = false;
  slot.scrollIntoView({ behavior: "smooth", block: "start" });
  slot.classList.add("attention");
  window.setTimeout(() => slot.classList.remove("attention"), 1400);
}

function hideProjectLibraryReport() {
  projectLibraryReportVisible = false;
  ensureProjectLibraryReportSlot();
}

function setProjectLibraryReportPeriod(period) {
  projectLibraryReportPeriod = period === "weekly" ? "weekly" : "daily";
  projectLibraryReportVisible = true;
  projectLibraryCommsVisible = false;
  renderProjectLibraryReport();
}

function projectLibraryReportSourceProjects(projects = null) {
  if (Array.isArray(projects)) return projects;
  return filterProjectLibraryProjects(projectLibraryProjects);
}

function projectLibraryReportPeriodRange(period = projectLibraryReportPeriod) {
  const now = new Date();
  const activityStart = new Date(now);
  activityStart.setHours(0, 0, 0, 0);
  if (period === "weekly") {
    activityStart.setDate(activityStart.getDate() - 6);
  }
  const activityEnd = new Date(now);
  const dueEnd = new Date(now);
  dueEnd.setHours(23, 59, 59, 999);
  if (period === "weekly") {
    dueEnd.setDate(dueEnd.getDate() + 6);
  }
  return {
    now,
    activityStart,
    activityEnd,
    dueEnd,
    title: period === "weekly" ? "Weekly job progression" : "Daily job progression",
    activityLabel: period === "weekly" ? "last 7 days" : "today",
    dueLabel: period === "weekly" ? "next 7 days" : "today",
  };
}

function projectReportDate(value) {
  const text = String(value ?? "").trim();
  if (!text) return null;
  const date = new Date(text);
  return Number.isNaN(date.getTime()) ? null : date;
}

function projectReportDueDate(production) {
  const info = normalizeProductionInfo(production);
  if (!info.dueDate) return null;
  const date = new Date(`${info.dueDate}T${info.dueTime || "23:59"}:00`);
  return Number.isNaN(date.getTime()) ? null : date;
}

function projectReportActivityDate(project) {
  const savedState = savedProjectState(project);
  const production = normalizeProductionInfo(savedState?.productionInfo);
  const dates = [
    projectReportDate(production.lastUpdatedAt),
    projectReportDate(production.completedAt),
    projectReportDate(savedState?.checkedAt),
    projectReportDate(project.updatedAt),
  ].filter(Boolean);
  if (!dates.length) return null;
  return new Date(Math.max(...dates.map((date) => date.getTime())));
}

function projectReportDateInRange(date, start, end) {
  if (!date) return false;
  const time = date.getTime();
  return time >= start.getTime() && time <= end.getTime();
}

function projectReportProjectLabel(project) {
  const info = normalizeProjectInfo(project.projectInfo);
  const job = info.jobNumber ? `Job ${info.jobNumber}` : "No job";
  return `${job} / ${savedProjectSpoolTitle(project)}`;
}

function projectReportProjectLine(project) {
  const savedState = savedProjectState(project);
  const production = normalizeProductionInfo(savedState?.productionInfo);
  const parts = [
    projectStatusLabel(savedState?.projectStatus),
    production.assignee ? `Assigned ${production.assignee}` : "Unassigned",
    production.dueDate ? `Due ${formatProductionDue(production)}` : "",
    production.hold ? "HOLD" : "",
  ].filter(Boolean);
  return `${projectReportProjectLabel(project)} - ${parts.join(" / ")}`;
}

function projectLibraryReportData(projects = null) {
  const range = projectLibraryReportPeriodRange();
  const sourceProjects = projectLibraryReportSourceProjects(projects);
  const visibleProjects = sourceProjects.filter((project) => !productionProjectHidden(project));
  const stageCounts = visibleProjects.reduce((summary, project) => {
    const status = normalizeProjectStatus(savedProjectState(project)?.projectStatus);
    summary[status] = (summary[status] ?? 0) + 1;
    return summary;
  }, {});
  const todayStart = new Date(range.now);
  todayStart.setHours(0, 0, 0, 0);

  const enriched = visibleProjects.map((project) => {
    const savedState = savedProjectState(project);
    const production = normalizeProductionInfo(savedState?.productionInfo);
    const status = normalizeProjectStatus(savedState?.projectStatus);
    return {
      project,
      savedState,
      production,
      status,
      activityDate: projectReportActivityDate(project),
      dueDate: projectReportDueDate(production),
    };
  });

  const updated = enriched
    .filter((item) => projectReportDateInRange(item.activityDate, range.activityStart, range.activityEnd))
    .sort((first, second) => (second.activityDate?.getTime() ?? 0) - (first.activityDate?.getTime() ?? 0));
  const completed = enriched.filter((item) => {
    if (item.status !== "complete") return false;
    const completedAt = projectReportDate(item.production.completedAt) ?? item.activityDate;
    return projectReportDateInRange(completedAt, range.activityStart, range.activityEnd);
  });
  const dueSoon = enriched
    .filter((item) => item.status !== "complete" && item.dueDate && item.dueDate.getTime() <= range.dueEnd.getTime())
    .sort((first, second) => (first.dueDate?.getTime() ?? 0) - (second.dueDate?.getTime() ?? 0));
  const overdue = enriched.filter((item) => item.status !== "complete" && item.dueDate && item.dueDate.getTime() < todayStart.getTime());
  const onHold = enriched.filter((item) => item.production.hold);
  const readyToCheck = enriched.filter((item) => item.status === "readycheck");
  const readyToIssue = enriched.filter((item) => item.status === "checked");
  const issued = enriched.filter((item) => item.status === "issued");
  const fabrication = enriched.filter((item) => ["cutting", "fitup", "welded", "finish"].includes(item.status));
  const actionQueue = enriched
    .filter((item) => item.status !== "complete" && !item.production.hold)
    .sort((first, second) => {
      const priority = productionPriorityRank(first.production.priority) - productionPriorityRank(second.production.priority);
      if (priority !== 0) return priority;
      const firstDue = first.dueDate?.getTime() ?? Number.MAX_SAFE_INTEGER;
      const secondDue = second.dueDate?.getTime() ?? Number.MAX_SAFE_INTEGER;
      if (firstDue !== secondDue) return firstDue - secondDue;
      return PROJECT_STATUS_FLOW.findIndex(([key]) => key === first.status) - PROJECT_STATUS_FLOW.findIndex(([key]) => key === second.status);
    });
  const assignees = new Map();
  for (const item of enriched.filter((entry) => entry.status !== "complete")) {
    const name = item.production.assignee || "Unassigned";
    const current = assignees.get(name) ?? { name, count: 0, due: 0, overdue: 0, hold: 0, urgent: 0 };
    current.count += 1;
    if (item.dueDate && item.dueDate.getTime() <= range.dueEnd.getTime()) current.due += 1;
    if (item.dueDate && item.dueDate.getTime() < todayStart.getTime()) current.overdue += 1;
    if (item.production.hold) current.hold += 1;
    if (item.production.priority === "urgent") current.urgent += 1;
    assignees.set(name, current);
  }

  return {
    range,
    visibleProjects,
    stageCounts,
    updated,
    completed,
    dueSoon,
    overdue,
    onHold,
    readyToCheck,
    readyToIssue,
    issued,
    fabrication,
    actionQueue,
    assignees: [...assignees.values()].sort((first, second) => second.count - first.count || first.name.localeCompare(second.name)),
  };
}

function projectReportItemHtml(item, options = {}) {
  const dueDate = item?.dueDate instanceof Date ? item.dueDate : null;
  const activityDate = item?.activityDate instanceof Date ? item.activityDate : null;
  const isOverdue = dueDate && dueDate.getTime() < new Date().setHours(0, 0, 0, 0);
  const small = options.detail === "activity"
    ? activityDate ? activityDate.toLocaleString() : "not dated"
    : dueDate ? dueDate.toLocaleString() : projectStatusLabel(item?.status);
  return `<li${isOverdue ? ' class="overdue"' : ""}><span>${escapeHtml(projectReportProjectLine(item.project))}</span><small>${escapeHtml(small)}</small></li>`;
}

function renderProjectLibraryReport(projects = null) {
  if (!projectLibraryReportSlot) return;
  const data = projectLibraryReportData(projects);
  const total = data.visibleProjects.length;
  const period = projectLibraryReportPeriod;
  projectLibraryReportSlot.hidden = !projectLibraryReportVisible;
  projectLibraryReportSlot.innerHTML = `
    <section class="project-report-card" aria-label="Job progression report">
      <div class="project-report-head">
        <div>
          <strong>${escapeHtml(data.range.title)}</strong>
          <span>${escapeHtml(total)} spool${total === 1 ? "" : "s"} in the current dashboard / updated ${escapeHtml(data.range.activityLabel)} / due ${escapeHtml(data.range.dueLabel)}</span>
        </div>
        <div class="project-report-actions">
          <button type="button" class="${period === "daily" ? "active" : ""}" data-project-library-action="report-period" data-report-period="daily">Daily</button>
          <button type="button" class="${period === "weekly" ? "active" : ""}" data-project-library-action="report-period" data-report-period="weekly">Weekly</button>
          <button type="button" data-project-library-action="copy-report">Copy</button>
          <button type="button" data-project-library-action="hide-report">Hide</button>
        </div>
      </div>
      <div class="project-report-stats">
        <div><b>${data.updated.length}</b><span>Updated ${escapeHtml(data.range.activityLabel)}</span></div>
        <div><b>${data.readyToCheck.length}</b><span>Ready to check</span></div>
        <div><b>${data.readyToIssue.length}</b><span>Ready to issue</span></div>
        <div><b>${data.dueSoon.length}</b><span>Due ${escapeHtml(data.range.dueLabel)}</span></div>
        <div><b>${data.overdue.length}</b><span>Overdue</span></div>
        <div><b>${data.completed.length}</b><span>Fabricated ${escapeHtml(data.range.activityLabel)}</span></div>
      </div>
      <div class="project-report-grid">
        <section>
          <strong>Today / next actions</strong>
          <ul>
            ${data.actionQueue.slice(0, 10).map((item) => projectReportItemHtml(item)).join("") || "<li><span>No open action queue yet.</span></li>"}
          </ul>
        </section>
        <section>
          <strong>Stages</strong>
          <ul>
            ${PROJECT_STATUS_FLOW.map(([status, label]) => `<li><span>${escapeHtml(label)}</span><b>${data.stageCounts[status] ?? 0}</b></li>`).join("")}
          </ul>
        </section>
        <section>
          <strong>Ready to check</strong>
          <ul>
            ${data.readyToCheck.slice(0, 8).map((item) => projectReportItemHtml(item)).join("") || "<li><span>No spools waiting for checking.</span></li>"}
          </ul>
        </section>
        <section>
          <strong>Ready to issue / fabricate</strong>
          <ul>
            ${[...data.readyToIssue, ...data.issued, ...data.fabrication].slice(0, 10).map((item) => projectReportItemHtml(item)).join("") || "<li><span>No issued or fabrication queue yet.</span></li>"}
          </ul>
        </section>
        <section>
          <strong>People</strong>
          <ul>
            ${data.assignees.slice(0, 10).map((item) => `<li><span>${escapeHtml(item.name)}</span><small>${item.count} active / ${item.due} due / ${item.overdue} overdue / ${item.hold} hold / ${item.urgent} urgent</small></li>`).join("") || "<li><span>No active assignees yet.</span></li>"}
          </ul>
        </section>
        <section>
          <strong>Holds and blockers</strong>
          <ul>
            ${data.onHold.slice(0, 10).map((item) => `<li><span>${escapeHtml(projectReportProjectLine(item.project))}</span><small>${escapeHtml(item.production.holdReason || "No hold reason entered")}</small></li>`).join("") || "<li><span>No spools on hold.</span></li>"}
          </ul>
        </section>
        <section>
          <strong>Recent progress</strong>
          <ul>
            ${data.updated.slice(0, 8).map((item) => projectReportItemHtml(item, { detail: "activity" })).join("") || "<li><span>No production updates in this period.</span></li>"}
          </ul>
        </section>
      </div>
    </section>
  `;
}

function projectLibraryReportText(projects = null) {
  const data = projectLibraryReportData(projects);
  const total = data.visibleProjects.length;
  const lines = [
    `SpoolMate ${data.range.title}`,
    `Generated ${data.range.now.toLocaleString()}`,
    `Scope: ${projectLibrarySource === "cloud" ? activeCompanyIsApproved() ? activeCompany.name : "Cloud" : "Browser"}${projectLibrarySearch.trim() ? ` / search "${projectLibrarySearch.trim()}"` : ""}`,
    "",
    `Total spools: ${total}`,
    `Updated ${data.range.activityLabel}: ${data.updated.length}`,
    `Ready to check: ${data.readyToCheck.length}`,
    `Ready to issue: ${data.readyToIssue.length}`,
    `Due ${data.range.dueLabel}: ${data.dueSoon.length}`,
    `Overdue: ${data.overdue.length}`,
    `On hold: ${data.onHold.length}`,
    `Fabricated ${data.range.activityLabel}: ${data.completed.length}`,
    "",
    "Stage count:",
    ...PROJECT_STATUS_FLOW.map(([status, label]) => `- ${label}: ${data.stageCounts[status] ?? 0}`),
    "",
    "Today / next actions:",
    ...(data.actionQueue.slice(0, 12).map((item) => `- ${projectReportProjectLine(item.project)}`)),
    ...(data.actionQueue.length ? [] : ["- No open action queue yet."]),
    "",
    "Ready to check:",
    ...(data.readyToCheck.slice(0, 12).map((item) => `- ${projectReportProjectLine(item.project)}`)),
    ...(data.readyToCheck.length ? [] : ["- No spools waiting for checking."]),
    "",
    "Ready to issue / fabricate:",
    ...([...data.readyToIssue, ...data.issued, ...data.fabrication].slice(0, 12).map((item) => `- ${projectReportProjectLine(item.project)}`)),
    ...([...data.readyToIssue, ...data.issued, ...data.fabrication].length ? [] : ["- No issued or fabrication queue yet."]),
    "",
    "Due and overdue:",
    ...(data.dueSoon.slice(0, 12).map((item) => `- ${projectReportProjectLine(item.project)} (${item.dueDate ? item.dueDate.toLocaleString() : "not dated"})`)),
    ...(data.dueSoon.length ? [] : ["- No spools due in this period."]),
    "",
    "Holds and blockers:",
    ...(data.onHold.slice(0, 12).map((item) => `- ${projectReportProjectLine(item.project)} (${item.production.holdReason || "No hold reason entered"})`)),
    ...(data.onHold.length ? [] : ["- No spools on hold."]),
    "",
    "People:",
    ...(data.assignees.slice(0, 12).map((item) => `- ${item.name}: ${item.count} active, ${item.due} due, ${item.overdue} overdue, ${item.hold} hold, ${item.urgent} urgent`)),
    ...(data.assignees.length ? [] : ["- No active assignees yet."]),
    "",
    "Recent progress:",
    ...(data.updated.slice(0, 12).map((item) => `- ${projectReportProjectLine(item.project)} (${item.activityDate ? item.activityDate.toLocaleString() : "not dated"})`)),
    ...(data.updated.length ? [] : ["- No production updates in this period."]),
  ];
  return lines.join("\n");
}

async function copyProjectLibraryReport() {
  const text = projectLibraryReportText();
  try {
    if (!navigator.clipboard?.writeText) throw new Error("Clipboard unavailable");
    await navigator.clipboard.writeText(text);
    showAppNotice("Jobs report copied.");
  } catch (error) {
    console.warn("Could not copy report.", error);
    await openFieldInputDialog({
      title: "Copy Jobs report",
      label: "Report text",
      value: text,
      multiline: true,
      readOnly: true,
      help: "Clipboard access was blocked, so select and copy this report manually.",
      submitLabel: "Done",
    });
  }
}

function productionCommandStripItem(projects, filter, label, hint, counts, activeFilter) {
  const matching = sortedProductionProjects((Array.isArray(projects) ? projects : [])
    .filter((project) => productionProjectMatchesBoardFilter(project, filter)));
  const first = matching[0] ?? null;
  const count = counts?.[filter] ?? matching.length;
  let detail = hint;
  if (first) {
    const production = savedProjectProductionInfo(first);
    const dueState = productionDueState(production);
    const status = normalizeProjectStatus(savedProjectState(first)?.projectStatus);
    detail = [
      savedProjectSpoolTitle(first),
      production.assignee ? `to ${production.assignee}` : "",
      dueState.key !== "none" ? dueState.label : projectStatusLabel(status),
    ].filter(Boolean).join(" / ");
  }
  return `
    <button type="button" class="${activeFilter === filter ? "active" : ""}" data-project-library-action="board-filter" data-board-filter="${escapeHtml(filter)}">
      <b>${count}</b>
      <span>${escapeHtml(label)}</span>
      <small>${escapeHtml(count ? detail : hint)}</small>
    </button>
  `;
}

function projectProductionCommandStrip(projects, counts, activeFilter) {
  const shortcuts = [
    ["today", "Due today", "Nothing due today."],
    ["overdue", "Overdue", "No overdue spools."],
    ["readycheck", "Ready check", "No checking queue."],
    ["mine", "Assigned to me", "Nothing assigned to you."],
    ["hold", "On hold", "No hold items."],
    ["message", "Messages", "No open yard notes."],
  ];
  const active = normalizeProductionBoardFilter(activeFilter);
  const totalActive = counts?.active ?? 0;
  const openActions = (counts?.today ?? 0) + (counts?.overdue ?? 0) + (counts?.readycheck ?? 0) + (counts?.hold ?? 0) + (counts?.message ?? 0);
  const scope = projectLibrarySource === "cloud"
    ? activeCompanyIsApproved() ? activeCompany.name : "Cloud"
    : "Browser";
  const section = document.createElement("section");
  section.className = "production-command-strip";
  section.innerHTML = `
    <div class="production-command-head">
      <div>
        <strong>Production command centre</strong>
        <span>${openActions} action item${openActions === 1 ? "" : "s"} / ${totalActive} active spool${totalActive === 1 ? "" : "s"} / ${escapeHtml(scope)} scope</span>
      </div>
      <div class="production-command-actions">
        <button type="button" data-project-library-action="show-report" data-report-period="daily">Daily report</button>
        <button type="button" data-project-library-action="show-report" data-report-period="weekly">Weekly report</button>
        <button type="button" data-project-library-action="show-comms">Comms</button>
      </div>
    </div>
    <div class="production-command-grid">
      ${shortcuts.map(([filter, label, hint]) => productionCommandStripItem(projects, filter, label, hint, counts, active)).join("")}
    </div>
  `;
  return section;
}

function projectProductionBoard(projects) {
  const section = document.createElement("section");
  section.className = "production-board-card";

  const boardFilter = normalizeProductionBoardFilter(projectLibraryBoardFilter);
  const boardProjects = projects.filter((project) => productionProjectMatchesBoardFilter(project, boardFilter));
  const counts = productionBoardFilterCounts(projects);
  const assigneeOptions = productionBoardAssigneeChoices(projects)
    .map((name) => `<option value="${escapeHtml(name)}"></option>`)
    .join("");

  const header = document.createElement("div");
  header.className = "production-board-header";
  header.innerHTML = `
    <div>
      <strong>Production board</strong>
      <span>${boardProjects.length} showing / ${projects.length} in dashboard. Drag cards, use quick status buttons, or update the card fields.</span>
    </div>
    <div class="production-board-filters" aria-label="Production board filters">
      ${Object.entries(PRODUCTION_BOARD_FILTERS).map(([key, label]) => `
        <button type="button" class="${boardFilter === key ? "active" : ""}" data-project-library-action="board-filter" data-board-filter="${key}">
          ${escapeHtml(label)} <b>${counts[key] ?? 0}</b>
        </button>
      `).join("")}
    </div>
  `;
  section.append(header);

  if (assigneeOptions) {
    const datalist = document.createElement("datalist");
    datalist.id = "productionBoardAssigneeOptions";
    datalist.innerHTML = assigneeOptions;
    section.append(datalist);
  }

  const lanes = document.createElement("div");
  lanes.className = "production-board-lanes";

  const visibleStatuses = boardFilter === "active"
    ? PROJECT_STATUS_FLOW.filter(([status]) => status !== "complete")
    : PROJECT_STATUS_FLOW;

  for (const [status, label] of visibleStatuses) {
    const stageProjects = sortedProductionProjects(boardProjects.filter((project) => {
      return normalizeProjectStatus(savedProjectState(project)?.projectStatus) === status;
    }));
    const lane = document.createElement("section");
    lane.className = "production-lane";
    lane.dataset.productionStatus = status;
    lane.dataset.productionDropStatus = status;

    const laneHeader = document.createElement("div");
    laneHeader.className = "production-lane-header";
    const laneTitle = document.createElement("strong");
    laneTitle.textContent = label;
    const count = document.createElement("span");
    count.textContent = String(stageProjects.length);
    laneHeader.append(laneTitle, count);
    lane.append(laneHeader);

    const visibleProjects = stageProjects.slice(0, 6);
    if (!visibleProjects.length) {
      const empty = document.createElement("span");
      empty.className = "production-lane-empty";
      empty.textContent = "No spools";
      lane.append(empty);
    } else {
      for (const project of visibleProjects) {
        lane.append(projectProductionCard(project));
      }
      if (stageProjects.length > visibleProjects.length) {
        const more = document.createElement("span");
        more.className = "production-lane-more";
        more.textContent = `${stageProjects.length - visibleProjects.length} more in job folders`;
        lane.append(more);
      }
    }

    lanes.append(lane);
  }

  section.append(lanes);
  return section;
}

function productionProjectHidden(project) {
  const status = normalizeProjectStatus(savedProjectState(project)?.projectStatus);
  const production = savedProjectProductionInfo(project);
  if (status !== "complete" || !production.removeAfter) return false;
  const removeTime = new Date(production.removeAfter).getTime();
  return !Number.isNaN(removeTime) && removeTime < Date.now();
}

function projectProductionCard(project) {
  const savedState = savedProjectState(project);
  const production = savedProjectProductionInfo(project);
  const messages = savedProjectProductionMessages(project);
  const activeMessage = [...messages].reverse().find((message) => !message.completed) ?? null;
  const status = normalizeProjectStatus(savedState?.projectStatus);
  const permission = projectPermission(project);
  const canEdit = permission.canEdit;
  const disabledAttr = canEdit ? "" : ' disabled title="View/comment only for your team role"';
  const dueState = productionDueState(production);
  const card = document.createElement("article");
  card.className = "production-spool-card";
  card.classList.toggle("urgent", production.priority === "urgent");
  card.classList.toggle("hold", production.hold);
  card.classList.toggle("overdue", dueState.key === "overdue");
  card.classList.toggle("due-today", dueState.key === "today");
  card.classList.toggle("complete", status === "complete");
  card.classList.toggle("read-only", !canEdit);
  card.draggable = canEdit;
  card.dataset.productionProjectId = project.id;
  card.dataset.projectSource = project.source ?? projectLibrarySource;
  card.dataset.productionStatus = status;

  const parts = [
    production.assignee ? `To ${production.assignee}` : "Unassigned",
    production.dueDate ? `Due ${formatProductionDue(production)}` : "No due date",
    productionPriorityLabel(production.priority),
  ];
  if (production.hold) parts.unshift(production.holdReason ? `Hold: ${production.holdReason}` : "On hold");
  if (status === "complete" && production.removeAfter) parts.push(`Hides ${new Date(production.removeAfter).toLocaleDateString()}`);
  if (!canEdit) parts.push(permission.label);
  const quickActions = productionStatusQuickActions(status, canEdit, project.id);
  const latestActivity = [...savedProjectProductionActivity(project)].reverse()[0] ?? null;

  card.innerHTML = `
    <div class="production-card-head">
      <button type="button" class="production-card-title" data-open-project-id="${escapeHtml(project.id)}" data-project-source="${escapeHtml(project.source ?? projectLibrarySource)}">
        <strong>${escapeHtml(savedProjectSpoolTitle(project))}</strong>
        <span>${escapeHtml(savedProjectDetailLine(project))}</span>
      </button>
      <span class="production-drag-handle" aria-hidden="true">${canEdit ? "Drag" : "View"}</span>
    </div>
    <div class="production-card-badges">
      <span class="status">${escapeHtml(projectStatusLabel(status))}</span>
      <span class="due ${escapeHtml(dueState.key)}">${escapeHtml(dueState.label)}</span>
      <span class="priority ${escapeHtml(production.priority)}">${escapeHtml(productionPriorityLabel(production.priority))}</span>
      ${production.hold ? `<span class="hold">Hold</span>` : ""}
    </div>
    <small class="production-card-meta">${escapeHtml(parts.join(" / "))}</small>
    ${latestActivity ? `
      <div class="production-card-activity">
        <span>${escapeHtml(latestActivity.actor || "Team")}</span>
        <strong>${escapeHtml(latestActivity.text)}</strong>
        <small>${escapeHtml(formatProductionActivityTime(latestActivity.createdAt))}</small>
      </div>
    ` : ""}
    <div class="production-card-fields">
      <label>
        <span>Stage</span>
        <select data-production-field="status" data-project-id="${escapeHtml(project.id)}"${disabledAttr}>
          ${PROJECT_STATUS_FLOW.map(([key, label]) => `<option value="${key}"${status === key ? " selected" : ""}>${escapeHtml(label)}</option>`).join("")}
        </select>
      </label>
      <label>
        <span>Assigned</span>
        <input data-production-field="assignee" data-project-id="${escapeHtml(project.id)}" list="productionBoardAssigneeOptions" type="text" maxlength="80" value="${escapeHtml(production.assignee)}" placeholder="Who"${disabledAttr} />
      </label>
      <label>
        <span>Due</span>
        <input data-production-field="dueDate" data-project-id="${escapeHtml(project.id)}" type="date" value="${escapeHtml(production.dueDate)}"${disabledAttr} />
      </label>
      <label>
        <span>Time</span>
        <input data-production-field="dueTime" data-project-id="${escapeHtml(project.id)}" type="time" value="${escapeHtml(production.dueTime)}"${disabledAttr} />
      </label>
      <label>
        <span>Priority</span>
        <select data-production-field="priority" data-project-id="${escapeHtml(project.id)}"${disabledAttr}>
          ${[...PRODUCTION_PRIORITIES].map((priority) => `<option value="${priority}"${production.priority === priority ? " selected" : ""}>${escapeHtml(productionPriorityLabel(priority))}</option>`).join("")}
        </select>
      </label>
      <label class="production-inline-toggle">
        <input data-production-field="hold" data-project-id="${escapeHtml(project.id)}" type="checkbox"${production.hold ? " checked" : ""}${disabledAttr} />
        <span>Hold</span>
      </label>
      <label class="production-hold-card-reason">
        <span>Hold reason</span>
        <input data-production-field="holdReason" data-project-id="${escapeHtml(project.id)}" type="text" maxlength="140" value="${escapeHtml(production.holdReason)}" placeholder="Missing fitting, client hold..."${disabledAttr} />
      </label>
    </div>
    <div class="production-message-panel">
      ${activeMessage ? `
        <div class="production-active-message">
          <span>${escapeHtml(activeMessage.body)}</span>
          <button type="button" data-production-action="complete-message" data-project-id="${escapeHtml(project.id)}" data-message-id="${escapeHtml(activeMessage.id)}"${disabledAttr}>Done</button>
        </div>
      ` : ""}
      <div class="production-message-compose">
        <input data-production-message-input data-project-id="${escapeHtml(project.id)}" type="text" maxlength="240" placeholder="${canEdit ? "Message / yard note" : "Use spool comments or team Comms"}"${disabledAttr} />
        <button type="button" data-production-action="add-message" data-project-id="${escapeHtml(project.id)}"${disabledAttr}>Add</button>
      </div>
    </div>
    <div class="production-card-actions">
      ${quickActions}
      <button type="button" data-open-project-id="${escapeHtml(project.id)}" data-project-source="${escapeHtml(project.source ?? projectLibrarySource)}">Open</button>
    </div>
  `;
  return card;
}

function filterProjectLibraryProjects(projects) {
  const query = projectLibrarySearch.trim().toLowerCase();
  if (!query) return projects;
  return projects.filter((project) => projectLibrarySearchText(project).includes(query));
}

function projectLibrarySearchText(project) {
  const info = normalizeProjectInfo(project.projectInfo);
  const savedState = savedProjectState(project);
  const production = normalizeProductionInfo(savedState?.productionInfo);
  const messages = activeProductionMessages(savedState?.productionMessages).map((message) => message.body).join(" ");
  const activity = normalizeProductionActivity(savedState?.productionActivity).map((entry) => `${entry.actor} ${entry.text}`).join(" ");
  const status = projectStatusLabel(savedState?.projectStatus);
  const scope = project.companyId ? companyNameForId(project.companyId) : project.source === "cloud" ? "personal cloud" : "browser";
  return [
    project.name,
    info.jobNumber,
    info.spoolNumber,
    info.client,
    info.revision,
    info.drawnBy,
    status,
    production.assignee,
    production.dueDate,
    production.dueTime,
    productionPriorityLabel(production.priority),
    production.hold ? "hold on hold" : "",
    production.holdReason,
    messages,
    activity,
    scope,
    savedProjectSpoolTitle(project),
    savedProjectDetailLine(project),
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function projectRecentActivityItems(projects = [], limit = 7) {
  return (Array.isArray(projects) ? projects : [])
    .filter((project) => !productionProjectHidden(project))
    .flatMap((project) => savedProjectProductionActivity(project).map((entry) => ({
      project,
      entry,
      time: new Date(entry.createdAt).getTime() || 0,
    })))
    .sort((first, second) => second.time - first.time)
    .slice(0, limit);
}

function projectDashboardCard(projects, options = {}) {
  const card = document.createElement("section");
  card.className = "project-dashboard-card team-work-dashboard";
  const counts = productionBoardFilterCounts(projects);
  const recentActivity = projectRecentActivityItems(projects);
  const totalCount = options.totalCount ?? projects.length;
  const resultText = options.query && totalCount !== projects.length
    ? `${projects.length} matching of ${totalCount} saved spool${totalCount === 1 ? "" : "s"}`
    : `${projects.length} saved spool${projects.length === 1 ? "" : "s"}`;
  const title = projectLibrarySource === "cloud"
    ? activeCompanyIsApproved() ? `${activeCompany.name} team dashboard` : "Cloud team dashboard"
    : "Browser production dashboard";
  const queues = [
    ["mine", "Assigned to me", "Nothing assigned to you."],
    ["today", "Due today", "Nothing due today."],
    ["overdue", "Overdue", "No overdue spools."],
    ["readycheck", "Ready to check", "No checking queue."],
    ["hold", "On hold", "No hold items."],
  ];

  card.innerHTML = `
    <div class="team-dashboard-head">
      <div>
        <strong>${escapeHtml(title)}</strong>
        <span>${escapeHtml(resultText)} / ${counts.active ?? 0} active</span>
      </div>
      <div class="team-dashboard-actions">
        <button type="button" data-project-library-action="show-report" data-report-period="daily">Daily report</button>
        <button type="button" data-project-library-action="show-report" data-report-period="weekly">Weekly report</button>
        <button type="button" data-project-library-action="show-comms">Team comms</button>
      </div>
    </div>
    <div class="team-dashboard-layout">
      <div class="team-dashboard-queues production-command-grid" aria-label="Team work queues">
        ${queues.map(([filter, label, hint]) => productionCommandStripItem(projects, filter, label, hint, counts, projectLibraryBoardFilter)).join("")}
      </div>
      <section class="team-dashboard-activity" aria-label="Recent team activity">
        <div class="team-dashboard-activity-head">
          <strong>Recent team activity</strong>
          <span>Latest assignment, due-date, hold, note and stage changes</span>
        </div>
        <div class="team-dashboard-activity-list">
          ${recentActivity.length ? recentActivity.map(({ project, entry }) => `
            <button type="button" data-open-project-id="${escapeHtml(project.id)}" data-project-source="${escapeHtml(project.source ?? projectLibrarySource)}">
              <span>${escapeHtml(savedProjectSpoolTitle(project))}</span>
              <strong>${escapeHtml(entry.text)}</strong>
              <small>${escapeHtml(entry.actor || "Team")} / ${escapeHtml(formatProductionActivityTime(entry.createdAt))}</small>
            </button>
          `).join("") : `<div class="team-dashboard-empty">No team activity yet. Assign a spool or move one to begin the history.</div>`}
        </div>
      </section>
    </div>
  `;
  return card;
}

function recentProjectChoices(limit = 9) {
  const choices = new Map();
  const projects = loadSavedBrowserProjects()
    .sort((first, second) => String(second.updatedAt).localeCompare(String(first.updatedAt)));

  for (const project of projects) {
    const info = normalizeProjectInfo(project.projectInfo);
    if (!info.jobNumber) continue;
    const key = `${info.jobNumber.toLowerCase()}::${info.client.toLowerCase()}`;
    const existing = choices.get(key);
    if (existing) {
      existing.count += 1;
      continue;
    }

    choices.set(key, {
      key,
      jobNumber: info.jobNumber,
      client: info.client,
      revision: info.revision,
      drawnBy: info.drawnBy,
      updatedAt: project.updatedAt,
      count: 1,
    });
  }

  return [...choices.values()].slice(0, limit);
}

function updateProjectJobPickerButton() {
  if (!projectDialogJobPickerButton) return;
  const choices = recentProjectChoices();
  projectDialogJobPickerButton.disabled = choices.length === 0;
  projectDialogJobPickerButton.title = choices.length
    ? "Pick from previous project numbers. You can also right-click the Job no. field."
    : "No previous saved project numbers yet.";
}

function openProjectJobPicker() {
  if (!projectJobQuickPick) return;
  renderProjectJobPicker();
  projectJobQuickPick.hidden = false;
}

function closeProjectJobPicker() {
  if (projectJobQuickPick) projectJobQuickPick.hidden = true;
}

function renderProjectJobPicker() {
  if (!projectJobQuickPick) return;
  projectJobQuickPick.innerHTML = "";

  const query = projectDialogInputs.jobNumber?.value.trim().toLowerCase() ?? "";
  const choices = recentProjectChoices()
    .filter((choice) => {
      if (!query) return true;
      return choice.jobNumber.toLowerCase().includes(query) || choice.client.toLowerCase().includes(query);
    });

  if (!choices.length) {
    const empty = document.createElement("div");
    empty.className = "project-job-picker-empty";
    empty.textContent = query ? "No matching saved jobs." : "No saved project numbers yet.";
    projectJobQuickPick.append(empty);
    return;
  }

  for (const choice of choices) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "project-job-choice";
    button.dataset.projectJobNumber = choice.jobNumber;
    button.dataset.projectClient = choice.client;
    button.dataset.projectRevision = choice.revision;
    button.dataset.projectDrawnBy = choice.drawnBy;

    const title = document.createElement("strong");
    title.textContent = `Job ${choice.jobNumber}`;

    const detail = document.createElement("span");
    detail.textContent = [
      choice.client || "No client / area",
      `${choice.count} saved spool${choice.count === 1 ? "" : "s"}`,
    ].join(" / ");

    const meta = document.createElement("small");
    meta.textContent = choice.updatedAt ? `Last used ${new Date(choice.updatedAt).toLocaleDateString()}` : "Saved project";

    button.append(title, detail, meta);
    projectJobQuickPick.append(button);
  }
}

function applyProjectJobChoice(choiceButton) {
  const jobNumber = choiceButton.dataset.projectJobNumber ?? "";
  const client = choiceButton.dataset.projectClient ?? "";
  const revision = choiceButton.dataset.projectRevision ?? "";
  const drawnBy = choiceButton.dataset.projectDrawnBy ?? "";

  if (projectDialogInputs.jobNumber) projectDialogInputs.jobNumber.value = jobNumber;
  if (projectDialogInputs.client) projectDialogInputs.client.value = client;
  if (projectDialogInputs.revision && !projectDialogInputs.revision.value.trim()) {
    projectDialogInputs.revision.value = revision;
  }
  if (projectDialogInputs.drawnBy && !projectDialogInputs.drawnBy.value.trim()) {
    projectDialogInputs.drawnBy.value = drawnBy;
  }

  closeProjectJobPicker();
  projectDialogInputs.spoolNumber?.focus();
}

function projectLibraryRow(project) {
    const permission = projectPermission(project);
    const row = document.createElement("div");
    row.className = "project-library-row";
    row.classList.toggle("active", project.id === state.projectId);
    row.classList.toggle("read-only", !permission.canEdit);
    row.dataset.openProjectId = project.id;
    row.dataset.projectSource = project.source ?? projectLibrarySource;
    row.tabIndex = 0;
    row.setAttribute("role", "button");
    row.setAttribute("aria-label", `Open ${savedProjectSpoolTitle(project)}`);
    row.title = "Open this spool";

    const main = document.createElement("div");
    main.className = "project-library-main";

    const title = document.createElement("strong");
    title.textContent = savedProjectSpoolTitle(project);

    const details = document.createElement("span");
    details.textContent = savedProjectDetailLine(project);

    const meta = document.createElement("span");
    meta.textContent = `${savedProjectMetaLine(project)}${project.source === "cloud" ? ` / ${permission.label}` : ""}`;

    main.append(title, details, meta);

    const activity = savedProjectProductionActivity(project).slice(-3).reverse();
    if (activity.length) {
      const activityBlock = document.createElement("div");
      activityBlock.className = "project-library-activity";
      activityBlock.innerHTML = `
        <strong>Activity</strong>
        ${activity.map((entry) => `
          <span>${escapeHtml(entry.actor || "Team")}: ${escapeHtml(entry.text)}</span>
        `).join("")}
      `;
      main.append(activityBlock);
    }

    const openButton = document.createElement("button");
    openButton.type = "button";
    openButton.className = "project-library-action primary";
    openButton.textContent = "Open";
    openButton.dataset.openProjectId = project.id;

    const deleteButton = document.createElement("button");
    deleteButton.type = "button";
    deleteButton.className = "project-library-action danger";
    deleteButton.textContent = "Delete";
    deleteButton.dataset.deleteProjectId = project.id;
    deleteButton.dataset.projectSource = project.source ?? projectLibrarySource;
    deleteButton.disabled = !permission.canDelete;
    if (!permission.canDelete) deleteButton.title = "Only the project owner or a team admin can delete this cloud spool.";

    openButton.dataset.projectSource = project.source ?? projectLibrarySource;
    row.append(main, openButton, deleteButton);
    return row;
}

function projectFolders(projects) {
  const folderMap = new Map();
  for (const project of projects) {
    const key = projectFolderKey(project);
    if (!folderMap.has(key)) {
      folderMap.set(key, {
        key,
        title: projectFolderTitle(project),
        projects: [],
        latest: "",
        active: false,
      });
    }

    const folder = folderMap.get(key);
    folder.projects.push(project);
    if (String(project.updatedAt) > String(folder.latest)) {
      folder.latest = project.updatedAt;
    }
    if (project.id === state.projectId) {
      folder.active = true;
    }
  }

  return [...folderMap.values()]
    .map((folder) => ({
      ...folder,
      projects: folder.projects.sort((first, second) => String(second.updatedAt).localeCompare(String(first.updatedAt))),
      meta: projectFolderMetaLine(folder),
    }))
    .sort((first, second) => {
      if (first.active !== second.active) return first.active ? -1 : 1;
      return String(second.latest).localeCompare(String(first.latest));
    });
}

function projectFolderKey(project) {
  const info = normalizeProjectInfo(project.projectInfo);
  const main = info.jobNumber || info.client || "unfiled";
  const client = info.jobNumber && info.client ? info.client : "";
  return `${main}::${client}`.toLowerCase();
}

function projectFolderTitle(project) {
  const info = normalizeProjectInfo(project.projectInfo);
  if (info.jobNumber && info.client) return `Job ${info.jobNumber} - ${info.client}`;
  if (info.jobNumber) return `Job ${info.jobNumber}`;
  if (info.client) return info.client;
  return "Unfiled project";
}

function projectFolderMetaLine(folder) {
  const updated = folder.latest ? new Date(folder.latest).toLocaleString() : "not dated";
  return `Last saved ${updated}`;
}

function savedProjectSpoolTitle(project) {
  const info = normalizeProjectInfo(project.projectInfo);
  const parts = [
    info.spoolNumber ? `Spool ${info.spoolNumber}` : "",
    info.revision ? `Rev ${info.revision}` : "",
  ].filter(Boolean);
  return parts.join(" - ") || project.name || "Untitled spool";
}

function savedProjectDetailLine(project) {
  const info = normalizeProjectInfo(project.projectInfo);
  const parts = [
    info.drawnBy ? `Drawn by ${info.drawnBy}` : "",
    info.client,
    info.jobNumber ? `Job ${info.jobNumber}` : "",
  ].filter(Boolean);
  return parts.join(" / ") || "No spool details";
}

function savedProjectMetaLine(project) {
  const savedState = savedProjectState(project);
  const production = normalizeProductionInfo(savedState?.productionInfo);
  const runs = Array.isArray(savedState?.edges) ? savedState.edges.length : 0;
  const updated = project.updatedAt ? new Date(project.updatedAt).toLocaleString() : "not dated";
  const status = projectStatusLabel(savedState?.projectStatus);
  const locked = savedState?.locked ? " / locked" : "";
  const scope = project.companyId ? (companyNameForId(project.companyId) || "Team") : project.source === "cloud" ? "Personal cloud" : "";
  const scopeText = scope ? `${scope} - ` : "";
  const assignee = production.assignee ? ` - ${production.assignee}` : "";
  const due = production.dueDate ? ` - due ${formatProductionDue(production)}` : "";
  const hold = production.hold ? " - HOLD" : "";
  return `${scopeText}${status}${locked}${hold}${assignee}${due} - ${runs} run${runs === 1 ? "" : "s"} - saved ${updated}`;
}

function closeProjectLibrary() {
  projectLibraryGuideVisible = false;
  projectLibraryReportVisible = false;
  ensureProjectLibraryGuideSlot();
  ensureProjectLibraryReportSlot();
  if (projectLibraryDialog) projectLibraryDialog.hidden = true;
}

async function openSavedBrowserProject(projectId) {
  clearPendingProjectCommentPhoto();
  const record = loadSavedBrowserProjects().find((project) => project.id === projectId);
  if (!record) {
    showAppNotice("That saved project was not found.");
    renderProjectLibrary(loadSavedBrowserProjects(), { source: "browser" });
    return;
  }

  if (state.projectId !== record.id && hasDrawingContent()) {
    const proceed = await confirmAppAction("Open this project? Your current drawing will be replaced.", {
      title: "Open saved spool",
      confirmLabel: "Open spool",
      tone: "warning",
    });
    if (!proceed) return;
    persistState();
  }

  const restored = stateFromPayload(record.state);
  if (!restored) {
    showAppNotice("That saved project could not be opened.");
    return;
  }

  state = restored;
  state.projectId = record.id;
  state.projectInfo = normalizeProjectInfo(record.projectInfo);
  state.projectInfoPrompted = true;
  currentCloudProjectOwnerId = null;
  currentCloudProjectCompanyId = null;
  cloudPermissionReadOnly = false;
  loadCloudSaveMetaForCurrentProject(record.id);
  projectComments = [];
  projectCommentsProjectId = null;
  three.userMovedCamera = false;
  setNextIdsFromState(state);
  updateControls();
  withCloudDirtySuppressed(() => updateAll());
  updateCloudStatus();
  closeProjectLibrary();
}

async function deleteSavedBrowserProject(projectId) {
  const projects = loadSavedBrowserProjects();
  const record = projects.find((project) => project.id === projectId);
  if (!record) return;

  const proceed = await confirmAppAction(`Delete ${record.name || projectDisplayName(record.projectInfo)} from this browser?`, {
    title: "Delete saved spool",
    confirmLabel: "Delete",
    tone: "error",
  });
  if (!proceed) return;

  storeSavedBrowserProjects(projects.filter((project) => project.id !== projectId));
  if (state.projectId === projectId) {
    state.projectId = null;
    currentCloudProjectOwnerId = null;
    currentCloudProjectCompanyId = null;
    cloudPermissionReadOnly = false;
    resetCloudSaveTracking();
    projectComments = [];
    projectCommentsProjectId = null;
    updateControls();
    persistState();
  }
  renderProjectLibrary(loadSavedBrowserProjects(), { source: "browser" });
}

function withTemporaryState(tempState, callback) {
  const previousState = state;
  state = tempState;
  try {
    return callback();
  } finally {
    state = previousState;
  }
}

function normalizeLoadPlanTrayKey(value) {
  return LOAD_PLAN_TRAY_KEYS.has(value) ? value : "medium";
}

function normalizeLoadPlanRackKey(value) {
  return LOAD_PLAN_RACK_KEYS.has(value) ? value : "standard";
}

function selectedLoadPlanTray() {
  return LOAD_PLAN_TRAYS[normalizeLoadPlanTrayKey(loadPlanTrayKey)] ?? LOAD_PLAN_TRAYS.medium;
}

function selectedLoadPlanRack() {
  return LOAD_PLAN_RACKS[normalizeLoadPlanRackKey(loadPlanRackKey)] ?? LOAD_PLAN_RACKS.standard;
}

function loadPlanExtentsFromPoints(points) {
  const xs = points.map((point) => point.x);
  const ys = points.map((point) => point.y);
  const zs = points.map((point) => point.z);
  const min = { x: Math.min(...xs), y: Math.min(...ys), z: Math.min(...zs) };
  const max = { x: Math.max(...xs), y: Math.max(...ys), z: Math.max(...zs) };
  return {
    min,
    max,
    span: {
      x: max.x - min.x,
      y: max.y - min.y,
      z: max.z - min.z,
    },
  };
}

function loadPlanAxisValue(point, axis) {
  return Number(point?.[axis]) || 0;
}

function loadPlanFootprintForAxes(segmentData, extents, pipeSizes, largestPipe, axes) {
  const [primaryAxis, secondaryAxis, heightAxis] = axes;
  const label = `${primaryAxis.toUpperCase()}${secondaryAxis.toUpperCase()} lay`;
  const rawPoints = state.points.map((point) => ({
    x: loadPlanAxisValue(point, primaryAxis),
    y: loadPlanAxisValue(point, secondaryAxis),
  }));
  const minX = Math.min(...rawPoints.map((point) => point.x));
  const minY = Math.min(...rawPoints.map((point) => point.y));
  const rawWidthMm = Math.max(...rawPoints.map((point) => point.x)) - minX;
  const rawHeightMm = Math.max(...rawPoints.map((point) => point.y)) - minY;
  const paddingMm = Math.max(90, largestPipe.od * 1.3);
  const pointByIndex = rawPoints.map((point) => ({
    x: point.x - minX + paddingMm,
    y: point.y - minY + paddingMm,
  }));
  const segments = segmentData.map((segment) => {
    const size = pipeSizeForSegment(segment);
    return {
      from: pointByIndex[segment.from],
      to: pointByIndex[segment.to],
      nb: size.nb,
      od: size.od,
    };
  });
  const widthMm = Math.max(largestPipe.od * 4, rawWidthMm + paddingMm * 2);
  const heightMm = Math.max(largestPipe.od * 4, rawHeightMm + paddingMm * 2);
  const verticalMm = Math.max(largestPipe.od * 2, extents.span[heightAxis]);

  return {
    label,
    axes: { primary: primaryAxis, secondary: secondaryAxis, height: heightAxis },
    segments,
    widthMm,
    heightMm,
    verticalMm,
    maxPipeOdMm: largestPipe.od,
    pipeSizes,
    areaMm2: widthMm * heightMm,
  };
}

function loadPlanStackFootprintForAxis(segmentData, extents, pipeSizes, largestPipe, primaryAxis) {
  const otherAxes = ["x", "y", "z"].filter((axis) => axis !== primaryAxis);
  const sideAxis = otherAxes[0];
  const heightAxis = otherAxes[1];
  const rawPoints = state.points.map((point) => ({
    x: loadPlanAxisValue(point, primaryAxis),
    side: loadPlanAxisValue(point, sideAxis),
    height: loadPlanAxisValue(point, heightAxis),
  }));
  const minX = Math.min(...rawPoints.map((point) => point.x));
  const minSide = Math.min(...rawPoints.map((point) => point.side));
  const maxSide = Math.max(...rawPoints.map((point) => point.side));
  const rawWidthMm = Math.max(...rawPoints.map((point) => point.x)) - minX;
  const paddingMm = Math.max(90, largestPipe.od * 1.3);
  const pipeLaneMm = Math.max(420, largestPipe.od * 4.2);
  const sideSpanMm = Math.max(1, maxSide - minSide);
  const sideTravelMm = Math.min(pipeLaneMm * 0.58, Math.max(largestPipe.od * 1.5, 180));
  const pointByIndex = rawPoints.map((point) => ({
    x: point.x - minX + paddingMm,
    y: paddingMm + pipeLaneMm / 2 + ((point.side - minSide) / sideSpanMm - 0.5) * sideTravelMm,
  }));
  const segments = segmentData.map((segment) => {
    const size = pipeSizeForSegment(segment);
    return {
      from: pointByIndex[segment.from],
      to: pointByIndex[segment.to],
      nb: size.nb,
      od: size.od,
    };
  });
  const widthMm = Math.max(largestPipe.od * 4, rawWidthMm + paddingMm * 2);
  const heightMm = pipeLaneMm + paddingMm * 2;
  const verticalMm = Math.max(largestPipe.od * 2, extents.span[sideAxis], extents.span[heightAxis]);

  return {
    label: `${primaryAxis.toUpperCase()} edge stack`,
    axes: { primary: primaryAxis, secondary: "stack", height: `${sideAxis}${heightAxis}` },
    segments,
    widthMm,
    heightMm,
    verticalMm,
    maxPipeOdMm: largestPipe.od,
    pipeSizes,
    areaMm2: widthMm * heightMm,
    stackLay: true,
  };
}

function loadPlanFootprintsFromSegments(segmentData) {
  const extents = loadPlanExtentsFromPoints(state.points);
  const pipeSizes = [...new Set(segmentData.map((segment) => pipeSizeForSegment(segment).nb))].sort((first, second) => first - second);
  const largestPipe = pipeSizeByNb(pipeSizes.length ? pipeSizes[pipeSizes.length - 1] : state.pipeSizeNb);
  const axisSets = [
    ["x", "y", "z"],
    ["x", "z", "y"],
    ["y", "z", "x"],
  ];
  const seen = new Set();
  const stackAxes = ["x", "y", "z"].sort((first, second) => extents.span[second] - extents.span[first]);
  const footprints = [
    ...axisSets.map((axes) => loadPlanFootprintForAxes(segmentData, extents, pipeSizes, largestPipe, axes)),
    ...stackAxes.map((axis) => loadPlanStackFootprintForAxis(segmentData, extents, pipeSizes, largestPipe, axis)),
  ]
    .filter((footprint) => {
      const key = `${footprint.stackLay ? "stack" : "flat"}:${Math.round(footprint.widthMm)}:${Math.round(footprint.heightMm)}:${Math.round(footprint.verticalMm)}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((first, second) => {
      if (first.stackLay !== second.stackLay) return first.stackLay ? 1 : -1;
      const heightDiff = first.verticalMm - second.verticalMm;
      if (Math.abs(heightDiff) > 1) return heightDiff;
      return second.areaMm2 - first.areaMm2;
    });

  return {
    footprints,
    pipeSizes,
    largestPipe,
  };
}

function loadPlanItemFromPayload(id, name, payload, projectInfo, updatedAt = "", source = "saved") {
  const restored = stateFromPayload(payload);
  if (!restored) return null;

  return withTemporaryState(restored, () => {
    const segmentData = segments();
    if (!segmentData.length) return null;

    const quantities = quantitySummary(segmentData);
    const footprintSet = loadPlanFootprintsFromSegments(segmentData);
    const footprint = footprintSet.footprints[0];
    if (!footprint) return null;
    const normalizedInfo = normalizeProjectInfo(projectInfo ?? state.projectInfo);
    const displayName = name || projectDisplayName(normalizedInfo);

    return {
      id,
      name: displayName,
      projectInfo: normalizedInfo,
      updatedAt,
      source,
      segmentCount: segmentData.length,
      lengthMm: footprint.widthMm,
      widthMm: footprint.heightMm,
      heightMm: footprint.verticalMm,
      jobKey: loadPlanJobKeyFromInfo(normalizedInfo),
      jobLabel: loadPlanJobLabelFromInfo(normalizedInfo),
      footprint,
      footprints: footprintSet.footprints,
      footprintAreaMm2: Math.max(...footprintSet.footprints.map((item) => item.areaMm2)),
      weightKg: quantities.totalWeightKg,
      pipeSpecLabel: pipeSpecShortLabel(),
      pipeSizesLabel: footprintSet.pipeSizes.length
        ? footprintSet.pipeSizes.map((nb) => pipeSizeDisplayLabelByNb(nb)).join(", ")
        : pipeSizeDisplayLabelByNb(state.pipeSizeNb),
    };
  });
}

function loadPlanAvailableItems() {
  const items = [];
  const currentPayload = statePayload();
  const current = loadPlanItemFromPayload(
    "__current__",
    `${projectDisplayName(currentPayload.projectInfo)} (current)`,
    currentPayload,
    currentPayload.projectInfo,
    "",
    "current",
  );
  if (current) items.push(current);

  const projects = loadSavedBrowserProjects()
    .filter((project) => project.id !== state.projectId)
    .sort((first, second) => String(second.updatedAt).localeCompare(String(first.updatedAt)));

  for (const project of projects) {
    const item = loadPlanItemFromPayload(
      project.id,
      project.name || projectDisplayName(project.projectInfo),
      project.state,
      project.projectInfo,
      project.updatedAt,
    );
    if (item) items.push(item);
  }

  return items;
}

function loadPlanJobKeyFromInfo(info) {
  const normalized = normalizeProjectInfo(info);
  const jobNumber = String(normalized.jobNumber ?? "").trim();
  return jobNumber ? jobNumber.toLowerCase() : "__unassigned__";
}

function loadPlanJobLabelFromInfo(info) {
  const normalized = normalizeProjectInfo(info);
  const jobNumber = String(normalized.jobNumber ?? "").trim();
  const client = String(normalized.client ?? "").trim();
  if (!jobNumber) return client ? `Unassigned job - ${client}` : "Unassigned job";
  return client ? `${jobNumber} - ${client}` : jobNumber;
}

function loadPlanJobChoices(items = loadPlanAvailableItems()) {
  const byKey = new Map();
  for (const item of items) {
    if (!byKey.has(item.jobKey)) {
      byKey.set(item.jobKey, {
        key: item.jobKey,
        label: item.jobLabel,
        count: 0,
      });
    }
    byKey.get(item.jobKey).count += 1;
  }

  return [...byKey.values()].sort((first, second) => {
    if (first.key === "__unassigned__") return 1;
    if (second.key === "__unassigned__") return -1;
    return first.label.localeCompare(second.label, undefined, { numeric: true, sensitivity: "base" });
  });
}

function renderLoadPlanJobOptions(items = loadPlanAvailableItems()) {
  if (!loadPlanJobSelect) return;
  const choices = loadPlanJobChoices(items);
  const validKeys = new Set(choices.map((choice) => choice.key));
  if (loadPlanJobKey && !validKeys.has(loadPlanJobKey)) {
    loadPlanJobKey = "";
  }

  loadPlanJobSelect.innerHTML = "";
  const placeholder = document.createElement("option");
  placeholder.value = "";
  placeholder.textContent = choices.length ? "Select job first" : "No jobs saved yet";
  loadPlanJobSelect.append(placeholder);

  for (const choice of choices) {
    const option = document.createElement("option");
    option.value = choice.key;
    option.textContent = `${choice.label} (${choice.count})`;
    loadPlanJobSelect.append(option);
  }

  loadPlanJobSelect.value = loadPlanJobKey;
  loadPlanJobSelect.disabled = !choices.length;
}

function loadPlanVisibleItems(items = loadPlanAvailableItems()) {
  if (!loadPlanJobKey) return [];
  return items.filter((item) => item.jobKey === loadPlanJobKey);
}

function selectedLoadPlanItems(items = loadPlanVisibleItems()) {
  return items.filter((item) => loadPlanSelection.has(item.id)).slice(0, LOAD_PLAN_MAX_SPOOLS);
}

function loadPlanItemMeta(item) {
  const size = `${formatLength(item.lengthMm)} x ${formatLength(item.widthMm)} footprint / ${formatLength(item.heightMm)} high`;
  return `${formatMass(item.weightKg)} kg / ${item.segmentCount} runs / ${size}`;
}

function loadPlanItemFitStatus(item) {
  const tray = selectedLoadPlanTray();
  const rack = selectedLoadPlanRack();
  const trayPlacement = findLoadPlanPlacement(item, [], tray, "tray");
  const rackPlacement = rack ? findLoadPlanPlacement(item, [], rack, "rack") : null;

  if (trayPlacement) {
    return {
      className: "fit-tray",
      text: "Fits tray",
    };
  }

  if (rackPlacement) {
    return {
      className: "fit-rack",
      text: "Won't fit tray - roof racks only",
    };
  }

  return {
    className: "fit-none",
    text: rack ? "Won't fit selected tray or roof racks" : "Won't fit selected tray",
  };
}

function renderLoadPlanProjectChoices() {
  if (!loadPlanProjectList) return [];

  if (loadPlanTraySelect) loadPlanTraySelect.value = normalizeLoadPlanTrayKey(loadPlanTrayKey);
  if (loadPlanRackSelect) loadPlanRackSelect.value = normalizeLoadPlanRackKey(loadPlanRackKey);
  const allItems = loadPlanAvailableItems();
  renderLoadPlanJobOptions(allItems);
  const items = loadPlanVisibleItems(allItems);
  const validIds = new Set(items.map((item) => item.id));
  loadPlanSelection = new Set([...loadPlanSelection].filter((id) => validIds.has(id)));

  loadPlanProjectList.innerHTML = "";
  if (!allItems.length) {
    const empty = document.createElement("div");
    empty.className = "project-library-empty";
    empty.textContent = "No pipe spools available yet. Draw or open a saved spool, then come back to Load plan.";
    loadPlanProjectList.append(empty);
    if (loadPlanPlayButton) loadPlanPlayButton.disabled = true;
    updateLoadPlanBulkButtons([]);
    drawLoadPlanEmpty();
    return allItems;
  }

  if (!loadPlanJobKey) {
    const empty = document.createElement("div");
    empty.className = "project-library-empty";
    empty.textContent = "Select a job first, then the spools for that job will show here.";
    loadPlanProjectList.append(empty);
    if (loadPlanPlayButton) loadPlanPlayButton.disabled = true;
    currentLoadPlan = createTruckLoadPlan([]);
    updateLoadPlanBulkButtons([]);
    updateLoadPlanPendingSelection([]);
    return allItems;
  }

  if (!items.length) {
    const empty = document.createElement("div");
    empty.className = "project-library-empty";
    empty.textContent = "No spools found for this job.";
    loadPlanProjectList.append(empty);
    if (loadPlanPlayButton) loadPlanPlayButton.disabled = true;
    updateLoadPlanBulkButtons([]);
    updateLoadPlanPendingSelection([]);
    return allItems;
  }

  if (loadPlanPlayButton) loadPlanPlayButton.disabled = false;
  updateLoadPlanBulkButtons(items);

  for (const item of items) {
    const label = document.createElement("label");
    label.className = "load-plan-choice";

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.value = item.id;
    checkbox.checked = loadPlanSelection.has(item.id);

    const body = document.createElement("span");
    const title = document.createElement("strong");
    title.textContent = item.name;

    const meta = document.createElement("span");
    meta.textContent = loadPlanItemMeta(item);

    const fitStatus = loadPlanItemFitStatus(item);
    const fit = document.createElement("em");
    fit.className = `load-plan-fit-status ${fitStatus.className}`;
    fit.textContent = fitStatus.text;

    const detail = document.createElement("small");
    detail.textContent = `${item.pipeSizesLabel} / ${item.pipeSpecLabel} / ${item.footprints.length} lay option${item.footprints.length === 1 ? "" : "s"}${item.source === "current" ? " / on screen now" : ""}`;

    body.append(title, meta, fit, detail);
    label.append(checkbox, body);
    loadPlanProjectList.append(label);
  }

  updateLoadPlanPendingSelection(items);
  return allItems;
}

function updateLoadPlanBulkButtons(items = loadPlanVisibleItems()) {
  const hasItems = Boolean(loadPlanJobKey && items.length);
  if (loadPlanSelectAllButton) loadPlanSelectAllButton.disabled = !hasItems;
  if (loadPlanDeselectAllButton) loadPlanDeselectAllButton.disabled = !hasItems;
}

function setVisibleLoadPlanSelection(selectAll) {
  const items = loadPlanVisibleItems();
  if (!items.length) return;

  if (selectAll) {
    loadPlanSelection = new Set(items.slice(0, LOAD_PLAN_MAX_SPOOLS).map((item) => item.id));
    if (items.length > LOAD_PLAN_MAX_SPOOLS) {
      showAppNotice(`Selected the first ${LOAD_PLAN_MAX_SPOOLS} spools. This load planner handles up to ${LOAD_PLAN_MAX_SPOOLS} at once.`);
    }
  } else {
    loadPlanSelection.clear();
  }

  renderLoadPlanProjectChoices();
}

function updateLoadPlanPendingSelection(items = loadPlanVisibleItems()) {
  const selectedItems = selectedLoadPlanItems(items);
  const selectedCount = selectedItems.length;
  currentLoadPlan = loadPlanViewMode === "model" && selectedCount
    ? createTruckLoadPlan(selectedItems)
    : createTruckLoadPlan([]);
  renderLoadPlan(currentLoadPlan);
  if (!loadPlanSummary) return;
  if (loadPlanViewMode === "model" && selectedCount) {
    updateLoadPlanSummary(currentLoadPlan);
    return;
  }
  loadPlanSummary.textContent = selectedCount
    ? `${selectedCount} spool${selectedCount === 1 ? "" : "s"} selected. Press Make layout.`
    : loadPlanJobKey ? "Select spools, then press Make layout." : "Select a job first.";
}

function handleLoadPlanChoiceChange(event) {
  const checkbox = event.target instanceof HTMLInputElement ? event.target : null;
  if (!checkbox || checkbox.type !== "checkbox") return;

  if (checkbox.checked && loadPlanSelection.size >= LOAD_PLAN_MAX_SPOOLS) {
    checkbox.checked = false;
    showAppNotice(`Pick up to ${LOAD_PLAN_MAX_SPOOLS} spools for this load plan.`);
    return;
  }

  if (checkbox.checked) {
    loadPlanSelection.add(checkbox.value);
  } else {
    loadPlanSelection.delete(checkbox.value);
  }

  updateLoadPlanPendingSelection(loadPlanVisibleItems());
}

function updateLoadPlanViewControls() {
  const modelActive = loadPlanViewMode === "model";
  const hasPlan = Boolean(currentLoadPlan?.placements?.length);
  loadPlanLayoutButton?.classList.toggle("active", !modelActive);
  loadPlanLayoutButton?.setAttribute("aria-pressed", String(!modelActive));
  loadPlanModelButton?.classList.toggle("active", modelActive);
  loadPlanModelButton?.setAttribute("aria-pressed", String(modelActive));
  if (loadPlanAnimateButton) loadPlanAnimateButton.disabled = !hasPlan;
  loadPlanSpinButton?.classList.toggle("active", modelActive && loadPlanThree.spinning);
  loadPlanSpinButton?.setAttribute("aria-pressed", String(modelActive && loadPlanThree.spinning));
  if (loadPlanSpinButton) loadPlanSpinButton.disabled = !modelActive;
  if (loadPlanResetButton) loadPlanResetButton.disabled = !modelActive;
  loadPlanStage?.classList.toggle("is-3d-model", modelActive);
}

function setLoadPlanViewMode(mode) {
  const nextMode = mode === "model" ? "model" : "layout";
  const selectedItems = selectedLoadPlanItems();
  loadPlanViewMode = nextMode;

  if (nextMode === "model") {
    if (selectedItems.length) {
      currentLoadPlan = createTruckLoadPlan(selectedItems);
      updateLoadPlanSummary(currentLoadPlan);
    } else if (!currentLoadPlan) {
      currentLoadPlan = createTruckLoadPlan([]);
    }
  }

  updateLoadPlanViewControls();
  renderLoadPlan(currentLoadPlan ?? createTruckLoadPlan([]));
}

function loadPlanNormalizeRotation(rotation) {
  return ((Number(rotation) || 0) % 360 + 360) % 360;
}

function loadPlanRotationOptions() {
  const preferred = [0, 180, 90, 270, 15, 345, 30, 330, 45, 315, 60, 300, 75, 285];
  const all = [];
  for (let angle = 0; angle < 360; angle += LOAD_PLAN_ROTATION_STEP_DEG) {
    all.push(angle);
  }
  return [...new Set([...preferred, ...all].map(loadPlanNormalizeRotation))];
}

function loadPlanRotatePointAroundCenter(point, footprint, rotation) {
  const radians = loadPlanNormalizeRotation(rotation) * Math.PI / 180;
  const centerX = footprint.widthMm / 2;
  const centerY = footprint.heightMm / 2;
  const dx = point.x - centerX;
  const dy = point.y - centerY;
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);
  return {
    x: dx * cos - dy * sin,
    y: dx * sin + dy * cos,
  };
}

function loadPlanRotationBounds(footprint, rotation) {
  const rotationKey = String(loadPlanNormalizeRotation(rotation));
  footprint.rotationBounds ??= {};
  if (footprint.rotationBounds[rotationKey]) return footprint.rotationBounds[rotationKey];

  const points = (footprint.segments ?? [])
    .flatMap((segment) => [segment.from, segment.to])
    .filter(Boolean);
  if (!points.length) {
    const fallback = {
      minX: 0,
      minY: 0,
      widthMm: footprint.widthMm,
      heightMm: footprint.heightMm,
      paddingMm: 0,
    };
    footprint.rotationBounds[rotationKey] = fallback;
    return fallback;
  }

  const rotated = points.map((point) => loadPlanRotatePointAroundCenter(point, footprint, rotation));
  const minX = Math.min(...rotated.map((point) => point.x));
  const maxX = Math.max(...rotated.map((point) => point.x));
  const minY = Math.min(...rotated.map((point) => point.y));
  const maxY = Math.max(...rotated.map((point) => point.y));
  const paddingMm = Math.max(70, (footprint.maxPipeOdMm ?? 50) * 0.85);
  const bounds = {
    minX,
    minY,
    widthMm: Math.max((footprint.maxPipeOdMm ?? 50) * 4, maxX - minX + paddingMm * 2),
    heightMm: Math.max((footprint.maxPipeOdMm ?? 50) * 4, maxY - minY + paddingMm * 2),
    paddingMm,
  };
  footprint.rotationBounds[rotationKey] = bounds;
  return bounds;
}

function loadPlanRotatedSize(footprint, rotation) {
  const bounds = loadPlanRotationBounds(footprint, rotation);
  return { widthMm: bounds.widthMm, heightMm: bounds.heightMm };
}

function loadPlanTransformPoint(point, footprint, rotation) {
  const bounds = loadPlanRotationBounds(footprint, rotation);
  const rotated = loadPlanRotatePointAroundCenter(point, footprint, rotation);
  return {
    x: rotated.x - bounds.minX + bounds.paddingMm,
    y: rotated.y - bounds.minY + bounds.paddingMm,
  };
}

function loadPlanAxisPositions(maxValue, step, centredValue = 0) {
  const values = new Set([0, Math.max(0, maxValue), clampNumber(centredValue, 0, Math.max(0, maxValue))]);
  for (let value = 0; value <= maxValue; value += step) {
    values.add(Math.round(value));
  }
  return [...values].sort((first, second) => first - second);
}

function loadPlanRectsOverlap(first, second, clearanceMm = LOAD_PLAN_CLEARANCE_MM) {
  return !(
    first.x + first.widthMm + clearanceMm <= second.x ||
    second.x + second.widthMm + clearanceMm <= first.x ||
    first.y + first.heightMm + clearanceMm <= second.y ||
    second.y + second.heightMm + clearanceMm <= first.y
  );
}

function loadPlanRectCenter(rect) {
  return {
    x: rect.x + rect.widthMm / 2,
    y: rect.y + rect.heightMm / 2,
  };
}

function loadPlanStackRepeatPenalty(rect, layer, placed) {
  if (layer <= 0) return 0;
  const center = loadPlanRectCenter(rect);
  return placed.reduce((penalty, placement) => {
    if ((placement.layer ?? 0) >= layer) return penalty;
    const otherCenter = loadPlanRectCenter(placement.rect);
    const distance = pointDistance2d(center, otherCenter);
    const repeatRange = Math.max(260, Math.min(rect.widthMm, rect.heightMm, placement.widthMm, placement.heightMm) * 0.85);
    if (distance >= repeatRange) return penalty;
    return penalty + (1 - distance / repeatRange) * 560000;
  }, 0);
}

function loadPlanFrontCrowdPenalty(rect, layer, placed, zoneType) {
  const sameLayer = placed.filter((placement) => (placement.layer ?? 0) === layer);
  if (!sameLayer.length) return 0;

  const center = loadPlanRectCenter(rect);
  return sameLayer.reduce((penalty, placement) => {
    const otherCenter = loadPlanRectCenter(placement.rect);
    const xGap = Math.abs(center.x - otherCenter.x);
    const xRange = clampNumber((rect.widthMm + placement.widthMm) * 0.34, 620, 1450);
    if (xGap >= xRange) return penalty;

    const yGap = Math.abs(center.y - otherCenter.y);
    const sideBySide = yGap > Math.min(rect.heightMm, placement.heightMm) * 0.55;
    const strength = zoneType === "rack" ? 7800000 : 9800000;
    return penalty + (1 - xGap / xRange) * strength * (sideBySide ? 1 : 0.62);
  }, 0);
}

function loadPlanLayerQueuePenalty(rect, layer, placed, loadZone) {
  const sameLayer = placed.filter((placement) => (placement.layer ?? 0) === layer);
  if (!sameLayer.length) return rect.x * 1200;

  const openEnd = Math.max(...sameLayer.map((placement) => placement.x + placement.widthMm));
  const targetX = clampNumber(openEnd + LOAD_PLAN_CLEARANCE_MM * 2, 0, Math.max(0, loadZone.lengthMm - rect.widthMm));
  return Math.abs(rect.x - targetX) * 2700;
}

function findLoadPlanPlacement(item, placed, loadZone, zoneType) {
  let best = null;
  const rotations = loadPlanRotationOptions();
  const footprints = item.footprints?.length ? item.footprints : [item.footprint].filter(Boolean);
  const maxLayers = zoneType === "tray" ? LOAD_PLAN_TRAY_LAYERS : LOAD_PLAN_RACK_LAYERS;

  for (const footprint of footprints) {
    for (const rotation of rotations) {
      const size = loadPlanRotatedSize(footprint, rotation);
      if (size.widthMm > loadZone.lengthMm || size.heightMm > loadZone.widthMm) continue;

      const maxX = loadZone.lengthMm - size.widthMm;
      const maxY = loadZone.widthMm - size.heightMm;
      const xPositions = loadPlanAxisPositions(maxX, LOAD_PLAN_PACK_STEP_MM, maxX / 2);
      const yPositions = loadPlanAxisPositions(maxY, LOAD_PLAN_PACK_STEP_MM, maxY / 2);

      for (let layer = 0; layer < maxLayers; layer += 1) {
        for (const x of xPositions) {
          for (const y of yPositions) {
            const rect = { x, y, widthMm: size.widthMm, heightMm: size.heightMm };
            const clearanceMm = layer > 0 ? Math.max(4, LOAD_PLAN_CLEARANCE_MM * 0.4) : LOAD_PLAN_CLEARANCE_MM;
            if (placed.some((placement) => placement.layer === layer && loadPlanRectsOverlap(rect, placement.rect, clearanceMm))) continue;

            const usedLengthMm = Math.max(
              x + size.widthMm,
              ...placed.map((placement) => placement.x + placement.widthMm),
              0,
            );
            const sideBalance = Math.abs(y + size.heightMm / 2 - loadZone.widthMm / 2);
            const normalizedRotation = loadPlanNormalizeRotation(rotation);
            const simpleAngle = normalizedRotation % 90 === 0;
            const diagonalBonus = simpleAngle ? 0 : -Math.min(90000, Math.abs(Math.sin(normalizedRotation * Math.PI / 180)) * 42000);
            const rotationPenalty = normalizedRotation === 0 ? 0 : simpleAngle ? 20 : 34;
            const layPenalty = footprint === item.footprint ? 0 : footprint.verticalMm * 5;
            const layerPenalty = layer * (zoneType === "tray" ? 220000 : 320000);
            const roofPenalty = zoneType === "rack" ? 180000 : 0;
            const xPositionPenalty = layer > 0 ? Math.abs(x - maxX / 2) * 18 : x * 2;
            const frontCrowdPenalty = loadPlanFrontCrowdPenalty(rect, layer, placed, zoneType);
            const queuePenalty = loadPlanLayerQueuePenalty(rect, layer, placed, loadZone);
            const repeatPenalty = loadPlanStackRepeatPenalty(rect, layer, placed);
            const score = usedLengthMm * 4200 + sideBalance * 24 + xPositionPenalty + queuePenalty + y + rotationPenalty + layPenalty + layerPenalty + roofPenalty + diagonalBonus + repeatPenalty + frontCrowdPenalty;
            if (!best || score < best.score) {
              best = {
                x,
                y,
                widthMm: size.widthMm,
                heightMm: size.heightMm,
                rotation,
                rect,
                zone: zoneType,
                layer,
                footprint,
                score,
              };
            }
          }
        }
      }
    }
  }

  return best;
}

function createTruckLoadPlan(items) {
  const tray = selectedLoadPlanTray();
  const rack = selectedLoadPlanRack();
  if (!items.length) return { tray, rack, placements: [], rejected: [], usedLengthMm: 0, rackUsedLengthMm: 0, totalDuration: 900 };

  const sorted = [...items].sort((first, second) => {
    const areaDiff = second.footprintAreaMm2 - first.footprintAreaMm2;
    if (Math.abs(areaDiff) > 1) return areaDiff;
    return second.weightKg - first.weightKg;
  });
  const placements = [];
  const trayPlacements = [];
  const rackPlacements = [];
  const rejected = [];

  for (const item of sorted) {
    const rackCandidate = rack ? findLoadPlanPlacement(item, rackPlacements, rack, "rack") : null;
    const trayCandidate = findLoadPlanPlacement(item, trayPlacements, tray, "tray");
    const placement = trayCandidate ?? rackCandidate;
    if (!placement) {
      rejected.push(item);
      continue;
    }

    const zonePlacements = placement.zone === "rack" ? rackPlacements : trayPlacements;
    zonePlacements.push(placement);
    placements.push({
      ...placement,
      item,
      order: placements.length + 1,
      delay: placements.length * 620,
      duration: 860,
    });
  }

  const usedLengthMm = trayPlacements.reduce((max, placement) => Math.max(max, placement.x + placement.widthMm), 0);
  const rackUsedLengthMm = rackPlacements.reduce((max, placement) => Math.max(max, placement.x + placement.widthMm), 0);
  return {
    tray,
    rack,
    placements,
    rejected,
    usedLengthMm,
    rackUsedLengthMm,
    totalWeightKg: placements.reduce((sum, placement) => sum + placement.item.weightKg, 0),
    totalDuration: placements.length
      ? placements[placements.length - 1].delay + placements[placements.length - 1].duration + 320
      : 900,
  };
}

function openLoadPlanDialog() {
  if (!loadPlanDialog) return;
  loadPlanSelection = new Set();
  loadPlanJobKey = "";
  loadPlanViewMode = "layout";
  updateLoadPlanViewControls();
  if (loadPlanTraySelect) loadPlanTraySelect.value = normalizeLoadPlanTrayKey(loadPlanTrayKey);
  if (loadPlanRackSelect) loadPlanRackSelect.value = normalizeLoadPlanRackKey(loadPlanRackKey);
  loadPlanDialog.hidden = false;
  renderLoadPlanProjectChoices();
  loadPlanPlayButton?.focus();
}

function closeLoadPlanDialog() {
  if (loadPlanAnimationFrame) {
    cancelAnimationFrame(loadPlanAnimationFrame);
    loadPlanAnimationFrame = 0;
  }
  setLoadPlanSpin(false);
  stopLoadPlanThreeLoop();
  currentLoadPlan = null;
  if (loadPlanDialog) loadPlanDialog.hidden = true;
}

function drawLoadPlanEmpty() {
  if (!loadPlanCanvas) return;
  if (loadPlanThreeCanvas) loadPlanThreeCanvas.hidden = true;
  loadPlanCanvas.hidden = false;
  const { ctx, width, height } = resizeCanvas(loadPlanCanvas);
  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = "#f7fbfa";
  ctx.fillRect(0, 0, width, height);
  ctx.fillStyle = "#5b6b70";
  ctx.font = "900 14px Arial, sans-serif";
  ctx.textAlign = "center";
  ctx.fillText("No spools ready for load planning", width / 2, height / 2);
  if (loadPlanSummary) loadPlanSummary.textContent = "Draw or open saved spools first. The planner can use the current spool plus saved browser projects.";
}

function renderLoadPlan(plan, elapsed = 0, playing = false) {
  updateLoadPlanViewControls();
  if (loadPlanViewMode === "model") {
    if (renderLoadPlanThree(plan, elapsed, playing)) return;
    loadPlanViewMode = "layout";
    updateLoadPlanViewControls();
  }

  stopLoadPlanThreeLoop();
  setLoadPlanSpin(false);
  if (loadPlanThreeCanvas) loadPlanThreeCanvas.hidden = true;
  if (loadPlanCanvas) loadPlanCanvas.hidden = false;
  drawTruckLoadPlan(plan, elapsed, playing);
}

function renderLoadPlanThree(plan, elapsed = 0, playing = false) {
  if (!plan || !ensureLoadPlanThree()) return false;
  if (loadPlanCanvas) loadPlanCanvas.hidden = true;
  if (loadPlanThreeCanvas) loadPlanThreeCanvas.hidden = false;
  resizeLoadPlanThree();
  rebuildLoadPlanThree(plan, elapsed, playing);
  updateLoadPlanViewControls();
  return true;
}

function ensureLoadPlanThree() {
  if (!loadPlanThreeCanvas || !loadPlanStage || !three.module || !three.OrbitControls) return false;
  if (loadPlanThree.ready) {
    loadPlanThreeCanvas.hidden = false;
    if (loadPlanCanvas) loadPlanCanvas.hidden = true;
    resizeLoadPlanThree();
    startLoadPlanThreeLoop();
    return true;
  }

  try {
    const THREE = three.module;
    loadPlanThree.scene = new THREE.Scene();
    loadPlanThree.scene.background = new THREE.Color(0xf7fbfa);
    loadPlanThree.camera = new THREE.PerspectiveCamera(42, 1, 0.05, 100);
    loadPlanThree.camera.up.set(0, 0, 1);
    loadPlanThree.renderer = new THREE.WebGLRenderer({
      canvas: loadPlanThreeCanvas,
      antialias: true,
      alpha: false,
      preserveDrawingBuffer: true,
    });
    loadPlanThree.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    loadPlanThree.renderer.shadowMap.enabled = true;
    loadPlanThree.renderer.outputColorSpace = THREE.SRGBColorSpace;
    loadPlanThree.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    loadPlanThree.renderer.toneMappingExposure = 1.08;

    loadPlanThree.scene.add(new THREE.HemisphereLight(0xffffff, 0xb8c2c0, 2.2));
    const keyLight = new THREE.DirectionalLight(0xffffff, 3.4);
    keyLight.position.set(6, -8, 8);
    keyLight.castShadow = true;
    loadPlanThree.scene.add(keyLight);
    const fillLight = new THREE.DirectionalLight(0xe8f0ef, 1.25);
    fillLight.position.set(-7, 7, 6);
    loadPlanThree.scene.add(fillLight);

    loadPlanThree.controls = new three.OrbitControls(loadPlanThree.camera, loadPlanThree.renderer.domElement);
    loadPlanThree.controls.enableDamping = true;
    loadPlanThree.controls.dampingFactor = 0.12;
    loadPlanThree.controls.screenSpacePanning = true;
    loadPlanThree.controls.enablePan = true;
    loadPlanThree.controls.enableZoom = true;
    loadPlanThree.controls.rotateSpeed = 0.58;
    loadPlanThree.controls.panSpeed = 0.72;
    loadPlanThree.controls.zoomSpeed = 0.78;
    loadPlanThree.controls.autoRotateSpeed = 1.15;

    loadPlanThree.ready = true;
    loadPlanThreeCanvas.hidden = false;
    if (loadPlanCanvas) loadPlanCanvas.hidden = true;
    resizeLoadPlanThree();
    startLoadPlanThreeLoop();
    return true;
  } catch (error) {
    console.warn("Load planner 3D view failed; using canvas fallback.", error);
    return false;
  }
}

function startLoadPlanThreeLoop() {
  if (!loadPlanThree.ready || loadPlanThree.animationFrame) return;
  loadPlanThree.animationFrame = requestAnimationFrame(animateLoadPlanThree);
}

function stopLoadPlanThreeLoop() {
  if (!loadPlanThree.animationFrame) return;
  cancelAnimationFrame(loadPlanThree.animationFrame);
  loadPlanThree.animationFrame = 0;
}

function animateLoadPlanThree() {
  if (!loadPlanThree.ready) {
    loadPlanThree.animationFrame = 0;
    return;
  }
  loadPlanThree.animationFrame = requestAnimationFrame(animateLoadPlanThree);
  if (loadPlanThree.controls) {
    loadPlanThree.controls.autoRotate = loadPlanThree.spinning;
    loadPlanThree.controls.update();
  }
  loadPlanThree.renderer?.render(loadPlanThree.scene, loadPlanThree.camera);
}

function resizeLoadPlanThree() {
  if (!loadPlanThree.ready || !loadPlanStage) return;
  const rect = loadPlanStage.getBoundingClientRect();
  const width = Math.max(1, Math.floor(rect.width));
  const height = Math.max(1, Math.floor(rect.height));
  loadPlanThree.renderer.setSize(width, height, false);
  loadPlanThree.camera.aspect = width / height;
  loadPlanThree.camera.updateProjectionMatrix();
}

function rebuildLoadPlanThree(plan, elapsed = 0, playing = false) {
  if (!loadPlanThree.ready || !plan) return;
  const THREE = three.module;
  if (loadPlanThree.group) {
    loadPlanThree.scene.remove(loadPlanThree.group);
    disposeObject3d(loadPlanThree.group);
  }

  const group = new THREE.Group();
  buildLoadPlanTruckBody3d(group, plan);
  buildLoadPlanZone3d(group, plan.tray, "tray", plan.tray);
  if (plan.rack) buildLoadPlanZone3d(group, plan.rack, "rack", plan.tray);

  const drawPlacements = [...plan.placements].sort((first, second) => {
    if (first.zone !== second.zone) return first.zone === "rack" ? -1 : 1;
    if ((first.layer ?? 0) !== (second.layer ?? 0)) return (first.layer ?? 0) - (second.layer ?? 0);
    return first.order - second.order;
  });
  for (const placement of drawPlacements) {
    buildLoadPlanSpool3d(group, plan, placement, elapsed, playing);
  }

  loadPlanThree.scene.add(group);
  loadPlanThree.group = group;
  frameLoadPlanThreeCamera();
  loadPlanThree.renderer.render(loadPlanThree.scene, loadPlanThree.camera);
}

function buildLoadPlanTruckBody3d(group, plan) {
  const THREE = three.module;
  const trayLength = plan.tray.lengthMm * LOAD_PLAN_3D_SCALE;
  const trayWidth = plan.tray.widthMm * LOAD_PLAN_3D_SCALE;
  const trayStartX = -trayLength / 2;
  const trayEndX = trayLength / 2;
  const cabLength = clampNumber(trayLength * 0.32, 0.95, 1.25);
  const bonnetLength = clampNumber(trayLength * 0.16, 0.45, 0.62);
  const cabWidth = Math.min(trayWidth * 0.86, 1.72);
  const cabX = trayStartX - cabLength / 2 - 0.12;
  const bonnetX = cabX - cabLength / 2 - bonnetLength / 2 + 0.05;
  const frontX = bonnetX - bonnetLength / 2 - 0.08;
  const chassisLength = trayEndX - frontX + 0.16;
  const chassisX = (trayEndX + frontX) / 2;

  const chassisMaterial = new THREE.MeshStandardMaterial({ color: 0x2e383a, roughness: 0.48, metalness: 0.42 });
  const cabMaterial = new THREE.MeshStandardMaterial({ color: 0xe7eeee, roughness: 0.45, metalness: 0.18 });
  const trimMaterial = new THREE.MeshStandardMaterial({ color: 0x445154, roughness: 0.4, metalness: 0.35 });
  const glassMaterial = new THREE.MeshStandardMaterial({ color: 0x5f7c84, roughness: 0.18, metalness: 0.2 });
  const tyreMaterial = new THREE.MeshStandardMaterial({ color: 0x101516, roughness: 0.72, metalness: 0.05 });
  const hubMaterial = new THREE.MeshStandardMaterial({ color: 0xb8c4c2, roughness: 0.32, metalness: 0.62 });

  const chassis = new THREE.Mesh(new THREE.BoxGeometry(chassisLength, trayWidth * 0.72, 0.12), chassisMaterial);
  chassis.position.set(chassisX, 0, -0.08);
  chassis.castShadow = true;
  chassis.receiveShadow = true;
  group.add(chassis);

  const cab = new THREE.Mesh(new THREE.BoxGeometry(cabLength, cabWidth, 0.62), cabMaterial);
  cab.position.set(cabX, 0, 0.28);
  cab.castShadow = true;
  cab.receiveShadow = true;
  group.add(cab);

  const bonnet = new THREE.Mesh(new THREE.BoxGeometry(bonnetLength, cabWidth * 0.92, 0.32), cabMaterial);
  bonnet.position.set(bonnetX, 0, 0.16);
  bonnet.castShadow = true;
  bonnet.receiveShadow = true;
  group.add(bonnet);

  const windscreen = new THREE.Mesh(new THREE.BoxGeometry(0.045, cabWidth * 0.72, 0.28), glassMaterial);
  windscreen.position.set(cabX - cabLength * 0.28, 0, 0.56);
  windscreen.castShadow = true;
  group.add(windscreen);

  const trayApron = new THREE.Mesh(new THREE.BoxGeometry(trayLength, 0.08, 0.16), trimMaterial);
  for (const side of [-1, 1]) {
    const apron = trayApron.clone();
    apron.position.set(0, side * (trayWidth / 2 + 0.035), -0.01);
    apron.castShadow = true;
    group.add(apron);
  }

  const wheelXPositions = [
    bonnetX - bonnetLength * 0.12,
    trayStartX + trayLength * 0.28,
    trayEndX - trayLength * 0.18,
  ];
  for (const x of wheelXPositions) {
    for (const side of [-1, 1]) {
      const wheel = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.22, 0.16, 32), tyreMaterial);
      wheel.position.set(x, side * (trayWidth / 2 + 0.18), -0.13);
      wheel.castShadow = true;
      group.add(wheel);

      const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.095, 0.095, 0.18, 20), hubMaterial);
      hub.position.copy(wheel.position);
      hub.castShadow = true;
      group.add(hub);
    }
  }

  if (plan.rack) {
    const rackLength = plan.rack.lengthMm * LOAD_PLAN_3D_SCALE;
    const rackStartX = trayStartX;
    const rackEndX = rackStartX + rackLength;
    const rackTopZ = loadPlanZoneBaseZ("rack") + 0.08;
    const rackY = trayWidth / 2;
    const mastMaterial = new THREE.MeshStandardMaterial({ color: 0x50676b, roughness: 0.42, metalness: 0.46 });
    const postXs = [
      rackStartX + Math.min(0.55, rackLength * 0.12),
      rackStartX + rackLength * 0.34,
      rackStartX + rackLength * 0.66,
      rackEndX - Math.min(0.55, rackLength * 0.12),
    ];
    for (const x of postXs) {
      const postBottom = x > trayEndX ? 0.18 : 0.08;
      for (const side of [-1, 1]) {
        const post = cylinderBetween(
          new THREE.Vector3(x, side * rackY, postBottom),
          new THREE.Vector3(x, side * rackY, rackTopZ),
          0.024,
          mastMaterial,
          14,
        );
        post.castShadow = true;
        group.add(post);
      }
    }
  }
}

function buildLoadPlanZone3d(group, loadZone, zone, tray = selectedLoadPlanTray()) {
  const THREE = three.module;
  const length = loadZone.lengthMm * LOAD_PLAN_3D_SCALE;
  const width = loadZone.widthMm * LOAD_PLAN_3D_SCALE;
  const offsetX = loadPlanZoneOffsetX(loadZone, zone, tray);
  const baseZ = loadPlanZoneBaseZ(zone);
  const edgeMaterial = new THREE.MeshStandardMaterial({ color: 0x50676b, roughness: 0.5, metalness: 0.35 });

  if (zone === "tray") {
    const deckThickness = 0.09;
    const deckMaterial = new THREE.MeshStandardMaterial({
      color: 0xd8e8e4,
      roughness: 0.62,
      metalness: 0.2,
    });
    const deck = new THREE.Mesh(new THREE.BoxGeometry(length, width, deckThickness), deckMaterial);
    deck.position.set(0, 0, baseZ - deckThickness * 0.5);
    deck.receiveShadow = true;
    deck.castShadow = true;
    group.add(deck);

    const railDepth = 0.16;
    for (const side of [-1, 1]) {
      const rail = new THREE.Mesh(new THREE.BoxGeometry(length, 0.05, railDepth), edgeMaterial);
      rail.position.set(0, side * width * 0.5, baseZ + railDepth * 0.5);
      rail.castShadow = true;
      group.add(rail);
    }

    const headboard = new THREE.Mesh(new THREE.BoxGeometry(0.07, width + 0.12, 0.62), edgeMaterial);
    headboard.position.set(-length / 2 + 0.035, 0, baseZ + 0.31);
    headboard.castShadow = true;
    group.add(headboard);

    const tailBar = new THREE.Mesh(new THREE.BoxGeometry(0.07, width + 0.08, 0.18), edgeMaterial);
    tailBar.position.set(length / 2 - 0.035, 0, baseZ + 0.09);
    tailBar.castShadow = true;
    group.add(tailBar);
  } else {
    const railRadius = 0.035;
    const railY = width / 2;
    const railZ = baseZ + 0.08;
    const crossbarXs = [-length * 0.42, -length * 0.14, length * 0.14, length * 0.42];
    for (const side of [-1, 1]) {
      const start = new THREE.Vector3(offsetX - length / 2, side * railY, railZ);
      const end = new THREE.Vector3(offsetX + length / 2, side * railY, railZ);
      const rail = cylinderBetween(start, end, railRadius, edgeMaterial, 16);
      rail.castShadow = true;
      group.add(rail);
    }

    for (const x of crossbarXs) {
      const crossbar = cylinderBetween(
        new THREE.Vector3(offsetX + x, -railY, railZ + 0.012),
        new THREE.Vector3(offsetX + x, railY, railZ + 0.012),
        0.028,
        edgeMaterial,
        14,
      );
      crossbar.castShadow = true;
      group.add(crossbar);
    }
  }
}

function loadPlanAnimationProgress(placement, elapsed, playing) {
  if (!playing) return 1;
  return clampNumber((elapsed - placement.delay) / placement.duration, 0, 1);
}

function loadPlanAnimationOffset(placement, plan, progress) {
  if (progress >= 1) return new three.module.Vector3(0, 0, 0);
  const eased = 1 - Math.pow(1 - progress, 3);
  const trayLength = plan.tray.lengthMm * LOAD_PLAN_3D_SCALE;
  const trayWidth = plan.tray.widthMm * LOAD_PLAN_3D_SCALE;
  const side = placement.order % 2 ? -1 : 1;
  const lane = (placement.order - 1) % 4;
  const start = new three.module.Vector3(
    -trayLength * 0.58 - 0.72 - lane * 0.28,
    side * (trayWidth * 0.58 + 0.38 + lane * 0.14),
    0.46 + ((placement.order - 1) % 3) * 0.14,
  );
  const lift = Math.sin(progress * Math.PI) * 0.24;
  return start.multiplyScalar(1 - eased).add(new three.module.Vector3(0, 0, lift));
}

function buildLoadPlanSpool3d(group, plan, placement, elapsed = 0, playing = false) {
  const THREE = three.module;
  const loadZone = placement.zone === "rack" ? plan.rack : plan.tray;
  if (!loadZone) return;
  const progress = loadPlanAnimationProgress(placement, elapsed, playing);
  if (playing && progress <= 0) return;
  const spoolGroup = new THREE.Group();
  spoolGroup.position.copy(loadPlanAnimationOffset(placement, plan, progress));
  const drawPlacement = loadPlanSettledPlacement(plan, placement, loadZone);
  const pipeMaterial = new THREE.MeshStandardMaterial({
    color: 0x202524,
    metalness: 0.55,
    roughness: 0.34,
  });
  const darkMaterial = new THREE.MeshStandardMaterial({ color: 0x0b1112, metalness: 0.42, roughness: 0.5 });
  const zBase = loadPlanZoneBaseZ(placement.zone) + loadPlanLayerHeightMm(placement) * LOAD_PLAN_3D_SCALE + 0.08;
  const center = loadPlanPlacementCenter3d(drawPlacement, loadZone, zBase - 0.025, plan.tray);
  buildLoadPlanDunnage3d(spoolGroup, loadZone, drawPlacement, zBase, plan.tray);

  for (const segment of loadPlanVisibleSegments(drawPlacement)) {
    const from = loadPlanTransformPoint(segment.from, drawPlacement.footprint, drawPlacement.rotation);
    const to = loadPlanTransformPoint(segment.to, drawPlacement.footprint, drawPlacement.rotation);
    const start = loadPlanPoint3d(drawPlacement, loadZone, from, zBase, plan.tray);
    const end = loadPlanPoint3d(drawPlacement, loadZone, to, zBase, plan.tray);
    const radius = clampNumber(segment.od * LOAD_PLAN_3D_SCALE * 0.5, 0.018, 0.18);
    const shadowPipe = cylinderBetween(
      start.clone().add(new THREE.Vector3(0.035, -0.035, -0.035)),
      end.clone().add(new THREE.Vector3(0.035, -0.035, -0.035)),
      radius * 1.08,
      darkMaterial,
      18,
    );
    shadowPipe.castShadow = true;
    spoolGroup.add(shadowPipe);

    const pipe = cylinderBetween(start, end, radius, pipeMaterial, 28);
    pipe.castShadow = true;
    pipe.receiveShadow = true;
    spoolGroup.add(pipe);
  }

  for (const node of loadPlanPlacementNodePoints(drawPlacement)) {
    const point = loadPlanPoint3d(drawPlacement, loadZone, node.point, zBase, plan.tray);
    const radius = clampNumber(node.od * LOAD_PLAN_3D_SCALE * 0.43, 0.014, 0.13);
    const nodeMaterial = new THREE.MeshStandardMaterial({
      color: node.count >= 3 ? 0xf2f6f5 : 0x202524,
      metalness: 0.5,
      roughness: 0.34,
    });
    const marker = new THREE.Mesh(new THREE.SphereGeometry(radius, 18, 12), nodeMaterial);
    marker.position.copy(point);
    marker.castShadow = true;
    marker.receiveShadow = true;
    spoolGroup.add(marker);
  }

  const marker = new THREE.Mesh(
    new THREE.SphereGeometry(0.075, 18, 12),
    new THREE.MeshStandardMaterial({ color: loadPlanSpoolColor(placement.order - 1), roughness: 0.28, metalness: 0.2 }),
  );
  marker.position.copy(center).add(new THREE.Vector3(-drawPlacement.widthMm * LOAD_PLAN_3D_SCALE * 0.5, -drawPlacement.heightMm * LOAD_PLAN_3D_SCALE * 0.5, 0.16));
  marker.castShadow = true;
  spoolGroup.add(marker);
  group.add(spoolGroup);
}

function loadPlanSettledPlacement(plan, placement, loadZone) {
  const layer = placement.layer ?? 0;
  if (layer <= 0 || placement.zone !== "tray") return placement;

  const supports = plan.placements.filter((candidate) => {
    if (candidate.zone !== placement.zone || (candidate.layer ?? 0) !== layer - 1) return false;
    const firstRight = placement.x + placement.widthMm;
    const secondRight = candidate.x + candidate.widthMm;
    return Math.min(firstRight, secondRight) - Math.max(placement.x, candidate.x) > Math.min(placement.widthMm, candidate.widthMm) * 0.18;
  });
  if (!supports.length) return placement;

  const supportCenters = supports
    .map((support) => support.y + support.heightMm / 2)
    .sort((first, second) => first - second);
  const targetCenter = supportCenters.length >= 2
    ? (supportCenters[0] + supportCenters[supportCenters.length - 1]) / 2
    : supportCenters[0];
  const targetY = clampNumber(targetCenter - placement.heightMm / 2, 0, loadZone.widthMm - placement.heightMm);
  const settledY = placement.y + (targetY - placement.y) * 0.65;
  return { ...placement, y: settledY, settled: Math.abs(settledY - placement.y) > 1 };
}

function loadPlanVisibleSegments(placement) {
  const segments = placement.footprint.segments ?? [];
  if (segments.length <= LOAD_PLAN_VISIBLE_SEGMENT_LIMIT) return segments;
  return [...segments]
    .sort((first, second) => {
      const firstLength = pointDistance2d(first.from, first.to);
      const secondLength = pointDistance2d(second.from, second.to);
      return secondLength - firstLength;
    })
    .slice(0, LOAD_PLAN_VISIBLE_SEGMENT_LIMIT);
}

function loadPlanPlacementNodePoints(placement) {
  const nodes = new Map();
  for (const segment of loadPlanVisibleSegments(placement)) {
    for (const point of [segment.from, segment.to]) {
      const transformed = loadPlanTransformPoint(point, placement.footprint, placement.rotation);
      const key = `${Math.round(transformed.x)}:${Math.round(transformed.y)}`;
      const existing = nodes.get(key);
      nodes.set(key, {
        point: transformed,
        od: Math.max(existing?.od ?? 0, segment.od ?? 50),
        count: (existing?.count ?? 0) + 1,
      });
    }
  }
  return [...nodes.values()];
}

function buildLoadPlanDunnage3d(group, loadZone, placement, zBase, tray = selectedLoadPlanTray()) {
  const THREE = three.module;
  const timberMaterial = new THREE.MeshStandardMaterial({
    color: 0x8a6a48,
    roughness: 0.78,
    metalness: 0.02,
  });
  const timberWidth = LOAD_PLAN_TIMBER_WIDTH_MM * LOAD_PLAN_3D_SCALE;
  const timberHeight = LOAD_PLAN_TIMBER_THICKNESS_MM * LOAD_PLAN_3D_SCALE * 0.62;
  const yLength = Math.min(loadZone.widthMm, Math.max(placement.heightMm, 520)) * LOAD_PLAN_3D_SCALE;
  const timberZ = zBase - timberHeight * 0.86;
  const supportCount = placement.widthMm > 3600 ? 3 : 2;
  const xPositions = Array.from({ length: supportCount }, (_, index) => {
    const fraction = supportCount === 2 ? 0.28 + index * 0.44 : 0.18 + index * 0.32;
    return placement.x + placement.widthMm * fraction;
  });

  for (const xMm of xPositions) {
    const beam = new THREE.Mesh(new THREE.BoxGeometry(timberWidth, yLength, timberHeight), timberMaterial);
    beam.position.copy(loadPlanPoint3d({ ...placement, x: xMm, y: placement.y + placement.heightMm / 2 }, loadZone, { x: 0, y: 0 }, timberZ, tray));
    beam.castShadow = true;
    beam.receiveShadow = true;
    group.add(beam);
  }
}

function loadPlanZoneBaseZ(zone) {
  return zone === "rack" ? 1.65 : 0.08;
}

function loadPlanZoneOffsetX(loadZone, zone, tray = selectedLoadPlanTray()) {
  if (zone !== "rack") return 0;
  return ((loadZone.lengthMm - tray.lengthMm) / 2) * LOAD_PLAN_3D_SCALE;
}

function loadPlanPoint3d(placement, loadZone, point, z, tray = selectedLoadPlanTray()) {
  const zone = placement.zone ?? "tray";
  const x = (placement.x + point.x - loadZone.lengthMm / 2) * LOAD_PLAN_3D_SCALE + loadPlanZoneOffsetX(loadZone, zone, tray);
  const y = (placement.y + point.y - loadZone.widthMm / 2) * LOAD_PLAN_3D_SCALE;
  return new three.module.Vector3(x, y, z);
}

function loadPlanPlacementCenter3d(placement, loadZone, z, tray = selectedLoadPlanTray()) {
  const zone = placement.zone ?? "tray";
  return new three.module.Vector3(
    (placement.x + placement.widthMm / 2 - loadZone.lengthMm / 2) * LOAD_PLAN_3D_SCALE + loadPlanZoneOffsetX(loadZone, zone, tray),
    (placement.y + placement.heightMm / 2 - loadZone.widthMm / 2) * LOAD_PLAN_3D_SCALE,
    z,
  );
}

function frameLoadPlanThreeCamera() {
  if (!loadPlanThree.ready || !loadPlanThree.group) return;
  const THREE = three.module;
  const box = new THREE.Box3().setFromObject(loadPlanThree.group);
  const center = new THREE.Vector3();
  const size = new THREE.Vector3();
  box.getCenter(center);
  box.getSize(size);
  const maxDim = Math.max(size.x, size.y, size.z, 2.5);
  loadPlanThree.bounds = { center, size };
  if (loadPlanThree.controls) {
    loadPlanThree.controls.target.copy(center);
  }
  loadPlanThree.camera.position.set(center.x + maxDim * 0.72, center.y - maxDim * 1.55, center.z + maxDim * 0.42);
  loadPlanThree.camera.near = 0.03;
  loadPlanThree.camera.far = Math.max(100, maxDim * 8);
  loadPlanThree.camera.updateProjectionMatrix();
  loadPlanThree.camera.lookAt(center);
  loadPlanThree.controls?.update();
}

function resetLoadPlanThreeView() {
  if (!ensureLoadPlanThree()) {
    renderLoadPlan(currentLoadPlan);
    return;
  }
  setLoadPlanSpin(false);
  if (loadPlanThree.group) loadPlanThree.group.rotation.set(0, 0, 0);
  frameLoadPlanThreeCamera();
}

function setLoadPlanSpin(active) {
  loadPlanThree.spinning = Boolean(active);
  if (loadPlanThree.controls) loadPlanThree.controls.autoRotate = loadPlanThree.spinning;
  loadPlanSpinButton?.classList.toggle("active", loadPlanThree.spinning);
  loadPlanSpinButton?.setAttribute("aria-pressed", String(loadPlanThree.spinning));
  updateLoadPlanViewControls();
}

function loadPlanZoneTitle(zone) {
  return zone === "rack" ? "Roof racks" : "Truck tray";
}

function loadPlanLayerGroups(plan, tray, rack = null) {
  const placements = plan?.placements ?? [];
  const groups = [];
  const addZone = (zone, loadZone) => {
    if (!loadZone) return;
    const zonePlacements = placements.filter((placement) => placement.zone === zone);
    const layers = [...new Set(zonePlacements.map((placement) => placement.layer ?? 0))]
      .sort((first, second) => first - second);
    for (const layer of layers) {
      groups.push({
        zone,
        loadZone,
        layer,
        placements: zonePlacements
          .filter((placement) => (placement.layer ?? 0) === layer)
          .sort((first, second) => first.x - second.x || first.y - second.y || first.order - second.order),
      });
    }
  };

  addZone("rack", rack);
  addZone("tray", tray);

  if (!groups.length && (plan?.rejected?.length || !placements.length)) {
    if (rack) groups.push({ zone: "rack", loadZone: rack, layer: 0, placements: [] });
    groups.push({ zone: "tray", loadZone: tray, layer: 0, placements: [] });
  }

  return groups;
}

function loadPlanTopViewTiles(width, height, groups, hasRejected = false) {
  const margin = Math.max(16, Math.min(30, width * 0.035));
  const headerHeight = 42;
  const footerHeight = hasRejected ? 72 : 34;
  const gap = 14;
  const count = Math.max(groups.length, 1);
  const columns = width >= 780 && count > 2 ? 2 : 1;
  const rows = Math.ceil(count / columns);
  const tileWidth = (width - margin * 2 - gap * (columns - 1)) / columns;
  const tileHeight = Math.max(78, (height - headerHeight - footerHeight - margin - gap * (rows - 1)) / rows);

  return groups.map((group, index) => {
    const column = index % columns;
    const row = Math.floor(index / columns);
    return {
      group,
      x: margin + column * (tileWidth + gap),
      y: headerHeight + row * (tileHeight + gap),
      width: tileWidth,
      height: tileHeight,
    };
  });
}

function loadPlanFitText(ctx, text, maxWidth) {
  const value = String(text ?? "");
  if (ctx.measureText(value).width <= maxWidth) return value;
  let trimmed = value;
  while (trimmed.length > 4 && ctx.measureText(`${trimmed}...`).width > maxWidth) {
    trimmed = trimmed.slice(0, -1);
  }
  return `${trimmed}...`;
}

function loadPlanShortName(item) {
  const info = item?.projectInfo ?? {};
  const parts = [info.jobNumber, info.spoolNumber].map((part) => String(part ?? "").trim()).filter(Boolean);
  return parts.length ? parts.join(" ") : truncateLoadPlanName(item?.name ?? "Spool", 18);
}

function drawLoadPlanDirectionArrow(ctx, start, end, color) {
  const angle = Math.atan2(end.y - start.y, end.x - start.x);
  const head = 7;
  ctx.save();
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = 2;
  ctx.lineCap = "round";
  drawLine(ctx, start, end);
  ctx.beginPath();
  ctx.moveTo(end.x, end.y);
  ctx.lineTo(end.x - Math.cos(angle - 0.58) * head, end.y - Math.sin(angle - 0.58) * head);
  ctx.lineTo(end.x - Math.cos(angle + 0.58) * head, end.y - Math.sin(angle + 0.58) * head);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawLoadPlanTopViewTile(ctx, tile) {
  const { group } = tile;
  const { loadZone } = group;
  const isRack = group.zone === "rack";
  const pad = 14;
  const titleY = tile.y + 18;
  const planX = tile.x + pad;
  const planY = tile.y + 34;
  const planMaxWidth = tile.width - pad * 2;
  const planMaxHeight = Math.max(48, tile.height - 48);
  const scaleX = planMaxWidth / loadZone.lengthMm;
  const scaleY = planMaxHeight / loadZone.widthMm;
  const zoneWidth = loadZone.lengthMm * scaleX;
  const zoneHeight = loadZone.widthMm * scaleY;
  const zoneX = tile.x + (tile.width - zoneWidth) / 2;
  const zoneY = planY + (planMaxHeight - zoneHeight) / 2;

  ctx.save();
  ctx.fillStyle = "#ffffff";
  ctx.strokeStyle = "rgba(31, 42, 47, 0.14)";
  ctx.lineWidth = 1;
  roundRect(ctx, tile.x, tile.y, tile.width, tile.height, 8);
  ctx.fill();
  ctx.stroke();

  ctx.fillStyle = "#17282c";
  ctx.font = "950 13px Arial, sans-serif";
  ctx.textAlign = "left";
  const layerText = `${loadPlanZoneTitle(group.zone)} - Layer ${group.layer + 1}`;
  ctx.fillText(layerText, tile.x + pad, titleY);
  ctx.textAlign = "right";
  ctx.fillStyle = "#607176";
  ctx.font = "850 11px Arial, sans-serif";
  ctx.fillText(`${formatLength(loadZone.lengthMm)} x ${formatLength(loadZone.widthMm)} mm`, tile.x + tile.width - pad, titleY);

  ctx.fillStyle = isRack ? "#eef5f6" : "#eef7f3";
  ctx.strokeStyle = isRack ? "#789096" : "#5f8583";
  ctx.lineWidth = 2;
  roundRect(ctx, zoneX, zoneY, zoneWidth, zoneHeight, 4);
  ctx.fill();
  ctx.stroke();

  ctx.save();
  ctx.beginPath();
  ctx.rect(zoneX, zoneY, zoneWidth, zoneHeight);
  ctx.clip();
  ctx.strokeStyle = "rgba(96, 113, 118, 0.18)";
  ctx.lineWidth = 1;
  for (let x = 1000; x < loadZone.lengthMm; x += 1000) {
    const sx = zoneX + x * scaleX;
    drawLine(ctx, { x: sx, y: zoneY }, { x: sx, y: zoneY + zoneHeight });
  }
  for (let y = 500; y < loadZone.widthMm; y += 500) {
    const sy = zoneY + y * scaleY;
    drawLine(ctx, { x: zoneX, y: sy }, { x: zoneX + zoneWidth, y: sy });
  }
  ctx.restore();

  if (isRack) {
    ctx.strokeStyle = "rgba(23, 40, 44, 0.32)";
    ctx.lineWidth = 3;
    for (const yFraction of [0.28, 0.72]) {
      const railY = zoneY + zoneHeight * yFraction;
      drawLine(ctx, { x: zoneX, y: railY }, { x: zoneX + zoneWidth, y: railY });
    }
  }

  for (const placement of group.placements) {
    drawLoadPlanTopViewPlacement(ctx, placement, zoneX, zoneY, scaleX, scaleY);
  }

  if (!group.placements.length) {
    ctx.fillStyle = "#6b7b80";
    ctx.font = "900 12px Arial, sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("No spools on this layer", zoneX + zoneWidth / 2, zoneY + zoneHeight / 2 + 4);
  }

  ctx.restore();
}

function drawLoadPlanTopViewPlacement(ctx, placement, zoneX, zoneY, scaleX, scaleY) {
  const x = zoneX + placement.x * scaleX;
  const y = zoneY + placement.y * scaleY;
  const width = Math.max(8, placement.widthMm * scaleX);
  const height = Math.max(8, placement.heightMm * scaleY);
  const pipeScale = Math.sqrt(scaleX * scaleY);
  const color = loadPlanSpoolColor(placement.order - 1);
  const label = `#${placement.order} ${loadPlanShortName(placement.item)}`;
  const detail = `${placement.item.pipeSizesLabel} / ${formatMass(placement.item.weightKg)} kg`;

  ctx.save();
  ctx.globalAlpha = 0.32;
  ctx.strokeStyle = color;
  ctx.lineWidth = 1.3;
  ctx.setLineDash([5, 5]);
  roundRect(ctx, x, y, width, height, 6);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.globalAlpha = 1;

  for (const segment of placement.footprint.segments ?? []) {
    const from = loadPlanTransformPoint(segment.from, placement.footprint, placement.rotation);
    const to = loadPlanTransformPoint(segment.to, placement.footprint, placement.rotation);
    const start = {
      x: zoneX + (placement.x + from.x) * scaleX,
      y: zoneY + (placement.y + from.y) * scaleY,
    };
    const end = {
      x: zoneX + (placement.x + to.x) * scaleX,
      y: zoneY + (placement.y + to.y) * scaleY,
    };
    const pipeWidth = clampNumber(segment.od * pipeScale * 0.72, 3.2, 13);
    ctx.lineCap = "butt";
    ctx.lineJoin = "round";
    ctx.strokeStyle = "rgba(18, 32, 36, 0.34)";
    ctx.lineWidth = pipeWidth + 3;
    drawLine(ctx, { x: start.x + 2, y: start.y + 3 }, { x: end.x + 2, y: end.y + 3 });
    ctx.strokeStyle = "#122024";
    ctx.lineWidth = pipeWidth + 1.5;
    drawLine(ctx, start, end);
    ctx.strokeStyle = color;
    ctx.lineWidth = pipeWidth;
    drawLine(ctx, start, end);
    ctx.strokeStyle = "rgba(255, 255, 255, 0.54)";
    ctx.lineWidth = Math.max(1.2, pipeWidth * 0.18);
    drawLine(ctx, { x: start.x, y: start.y - pipeWidth * 0.16 }, { x: end.x, y: end.y - pipeWidth * 0.16 });

    if (pointDistance2d(start, end) < 2) {
      ctx.fillStyle = color;
      ctx.strokeStyle = "#122024";
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(start.x, start.y, Math.max(4, pipeWidth * 0.65), 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
  }

  for (const node of loadPlanPlacementNodePoints(placement)) {
    const point = {
      x: zoneX + (placement.x + node.point.x) * scaleX,
      y: zoneY + (placement.y + node.point.y) * scaleY,
    };
    const radius = clampNumber(node.od * pipeScale * 0.36, 2.4, 7.5);
    ctx.fillStyle = node.count >= 3 ? "#ffffff" : color;
    ctx.strokeStyle = node.count >= 3 ? "#122024" : "rgba(18, 32, 36, 0.82)";
    ctx.lineWidth = node.count >= 3 ? 2.2 : 1.4;
    ctx.beginPath();
    ctx.arc(point.x, point.y, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }

  const arrowColor = "rgba(18, 32, 36, 0.82)";
  if (width >= height) {
    const arrowY = height >= 42 ? y + height - 11 : y + height / 2;
    drawLoadPlanDirectionArrow(ctx, { x: x + 10, y: arrowY }, { x: x + width - 10, y: arrowY }, arrowColor);
  } else {
    const arrowX = width >= 56 ? x + width - 11 : x + width / 2;
    drawLoadPlanDirectionArrow(ctx, { x: arrowX, y: y + 10 }, { x: arrowX, y: y + height - 10 }, arrowColor);
  }

  ctx.fillStyle = "#122024";
  ctx.font = "950 12px Arial, sans-serif";
  ctx.textAlign = "left";
  ctx.textBaseline = "top";
  const labelPadding = 6;
  const labelMax = Math.max(18, Math.min(260, width - labelPadding * 2));
  const cardWidth = Math.min(width - 4, Math.max(58, ctx.measureText(label).width + 12));
  const cardHeight = height >= 48 ? 34 : 20;
  const cardX = x + 3;
  const cardY = y + 3;
  if (width >= 64 && height >= 28) {
    ctx.fillStyle = "rgba(255, 255, 255, 0.86)";
    roundRect(ctx, cardX, cardY, cardWidth, cardHeight, 5);
    ctx.fill();
    ctx.strokeStyle = "rgba(18, 32, 36, 0.16)";
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.fillStyle = "#122024";
    ctx.fillText(loadPlanFitText(ctx, label, labelMax), cardX + labelPadding, cardY + 4);
    if (height >= 48) {
      ctx.font = "850 10px Arial, sans-serif";
      ctx.fillStyle = "#35474c";
      ctx.fillText(loadPlanFitText(ctx, detail, labelMax), cardX + labelPadding, cardY + 19);
    }
  } else {
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(`#${placement.order}`, x + width / 2, y + height / 2);
  }

  ctx.restore();
}

function loadPlanProjectIsoPoint(projector, xMm, yMm, zMm = 0) {
  return {
    x: projector.originX + (xMm + yMm * projector.skewX) * projector.scale,
    y: projector.originY + yMm * projector.skewY * projector.scale - zMm * projector.zLift * projector.scale,
  };
}

function drawLoadPlanIsoDeck(ctx, projector, loadZone, zone) {
  const corners = [
    loadPlanProjectIsoPoint(projector, 0, 0, 0),
    loadPlanProjectIsoPoint(projector, loadZone.lengthMm, 0, 0),
    loadPlanProjectIsoPoint(projector, loadZone.lengthMm, loadZone.widthMm, 0),
    loadPlanProjectIsoPoint(projector, 0, loadZone.widthMm, 0),
  ];
  ctx.save();
  ctx.fillStyle = zone === "rack" ? "#eef5f6" : "#edf6f2";
  ctx.strokeStyle = zone === "rack" ? "#789096" : "#5f8583";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(corners[0].x, corners[0].y);
  for (const corner of corners.slice(1)) ctx.lineTo(corner.x, corner.y);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  ctx.strokeStyle = "rgba(96, 113, 118, 0.18)";
  ctx.lineWidth = 1;
  for (let x = 1000; x < loadZone.lengthMm; x += 1000) {
    drawLine(ctx, loadPlanProjectIsoPoint(projector, x, 0, 0), loadPlanProjectIsoPoint(projector, x, loadZone.widthMm, 0));
  }
  for (let y = 500; y < loadZone.widthMm; y += 500) {
    drawLine(ctx, loadPlanProjectIsoPoint(projector, 0, y, 0), loadPlanProjectIsoPoint(projector, loadZone.lengthMm, y, 0));
  }

  if (zone === "rack") {
    ctx.strokeStyle = "rgba(23, 40, 44, 0.34)";
    ctx.lineWidth = 3;
    for (const yFraction of [0.28, 0.72]) {
      drawLine(
        ctx,
        loadPlanProjectIsoPoint(projector, 0, loadZone.widthMm * yFraction, 65),
        loadPlanProjectIsoPoint(projector, loadZone.lengthMm, loadZone.widthMm * yFraction, 65),
      );
    }
  }
  ctx.restore();
}

function drawLoadPlanIsoSpool(ctx, placement, projector) {
  const color = loadPlanSpoolColor(placement.order - 1);
  const zMm = (placement.layer ?? 0) * LOAD_PLAN_LAYER_RISE_MM + Math.max(40, placement.footprint.maxPipeOdMm * 0.5);
  const center = loadPlanProjectIsoPoint(
    projector,
    placement.x + placement.widthMm / 2,
    placement.y + placement.heightMm / 2,
    zMm + 70,
  );

  ctx.save();
  for (const segment of placement.footprint.segments ?? []) {
    const from = loadPlanTransformPoint(segment.from, placement.footprint, placement.rotation);
    const to = loadPlanTransformPoint(segment.to, placement.footprint, placement.rotation);
    const start = loadPlanProjectIsoPoint(projector, placement.x + from.x, placement.y + from.y, zMm);
    const end = loadPlanProjectIsoPoint(projector, placement.x + to.x, placement.y + to.y, zMm);
    const pipeWidth = clampNumber(segment.od * projector.scale * 0.58, 2.4, 9.5);

    ctx.lineCap = "butt";
    ctx.lineJoin = "round";
    ctx.strokeStyle = "rgba(18, 32, 36, 0.26)";
    ctx.lineWidth = pipeWidth + 3;
    drawLine(ctx, { x: start.x + 2, y: start.y + 4 }, { x: end.x + 2, y: end.y + 4 });
    ctx.strokeStyle = "#102328";
    ctx.lineWidth = pipeWidth + 1.3;
    drawLine(ctx, start, end);
    ctx.strokeStyle = color;
    ctx.lineWidth = pipeWidth;
    drawLine(ctx, start, end);
    ctx.strokeStyle = "rgba(255, 255, 255, 0.5)";
    ctx.lineWidth = Math.max(1, pipeWidth * 0.18);
    drawLine(ctx, { x: start.x, y: start.y - pipeWidth * 0.18 }, { x: end.x, y: end.y - pipeWidth * 0.18 });
  }

  for (const node of loadPlanPlacementNodePoints(placement)) {
    const point = loadPlanProjectIsoPoint(projector, placement.x + node.point.x, placement.y + node.point.y, zMm);
    const radius = clampNumber(node.od * projector.scale * 0.28, 2.2, 6.5);
    ctx.fillStyle = node.count >= 3 ? "#ffffff" : color;
    ctx.strokeStyle = "#102328";
    ctx.lineWidth = node.count >= 3 ? 2 : 1.2;
    ctx.beginPath();
    ctx.arc(point.x, point.y, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }

  ctx.fillStyle = "#ffffff";
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(center.x, center.y, 11, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = "#122024";
  ctx.font = "950 10px Arial, sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(String(placement.order), center.x, center.y + 0.5);
  ctx.restore();
}

function drawLoadPlanIsoZone(ctx, zonePlacements, loadZone, zone, area) {
  const maxLayer = zonePlacements.reduce((max, placement) => Math.max(max, placement.layer ?? 0), 0);
  const maxZ = Math.max(260, maxLayer * LOAD_PLAN_LAYER_RISE_MM + 260);
  const skewX = 0.38;
  const skewY = 0.24;
  const zLift = 0.56;
  const projectedWidthMm = loadZone.lengthMm + loadZone.widthMm * skewX;
  const projectedHeightMm = loadZone.widthMm * skewY + maxZ * zLift;
  const scale = Math.min(
    (area.width - 28) / projectedWidthMm,
    Math.max(1, area.height - 42) / projectedHeightMm,
  );
  const projector = {
    scale,
    skewX,
    skewY,
    zLift,
    originX: area.x + (area.width - projectedWidthMm * scale) / 2,
    originY: area.y + 30 + maxZ * zLift * scale,
  };

  ctx.save();
  ctx.fillStyle = "#ffffff";
  ctx.strokeStyle = "rgba(31, 42, 47, 0.14)";
  ctx.lineWidth = 1;
  roundRect(ctx, area.x, area.y, area.width, area.height, 8);
  ctx.fill();
  ctx.stroke();

  ctx.fillStyle = "#17282c";
  ctx.font = "950 13px Arial, sans-serif";
  ctx.textAlign = "left";
  ctx.fillText(`${loadPlanZoneTitle(zone)} 3D guide`, area.x + 12, area.y + 19);
  ctx.textAlign = "right";
  ctx.fillStyle = "#607176";
  ctx.font = "850 11px Arial, sans-serif";
  ctx.fillText("order dots match top view", area.x + area.width - 12, area.y + 19);

  drawLoadPlanIsoDeck(ctx, projector, loadZone, zone);
  const sorted = [...zonePlacements].sort((first, second) => {
    if ((first.layer ?? 0) !== (second.layer ?? 0)) return (first.layer ?? 0) - (second.layer ?? 0);
    return first.y - second.y || first.x - second.x || first.order - second.order;
  });
  for (const placement of sorted) {
    drawLoadPlanIsoSpool(ctx, placement, projector);
  }

  if (!zonePlacements.length) {
    ctx.fillStyle = "#6b7b80";
    ctx.font = "900 12px Arial, sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("No spools here", area.x + area.width / 2, area.y + area.height / 2);
  }
  ctx.restore();
}

function drawLoadPlanIsoModel(ctx, plan, area) {
  const placements = plan?.placements ?? [];
  const zones = [];
  if (plan?.rack && placements.some((placement) => placement.zone === "rack")) {
    zones.push({ zone: "rack", loadZone: plan.rack });
  }
  if (placements.some((placement) => placement.zone === "tray") || !zones.length) {
    zones.push({ zone: "tray", loadZone: plan?.tray ?? selectedLoadPlanTray() });
  }

  const gap = 10;
  const zoneHeight = Math.max(86, (area.height - gap * (zones.length - 1)) / zones.length);
  for (const [index, zoneData] of zones.entries()) {
    const zoneArea = {
      x: area.x,
      y: area.y + index * (zoneHeight + gap),
      width: area.width,
      height: zoneHeight,
    };
    drawLoadPlanIsoZone(
      ctx,
      placements.filter((placement) => placement.zone === zoneData.zone),
      zoneData.loadZone,
      zoneData.zone,
      zoneArea,
    );
  }
}

function drawLoadPlanRejected(ctx, plan, tiles, width, height) {
  if (!plan.rejected.length) return;
  const x = Math.max(16, Math.min(...tiles.map((tile) => tile.x)));
  const right = Math.min(width - 16, Math.max(...tiles.map((tile) => tile.x + tile.width)));
  const y = height - 58;
  ctx.save();
  ctx.fillStyle = "#fff5f3";
  ctx.strokeStyle = "rgba(180, 35, 24, 0.35)";
  roundRect(ctx, x, y, right - x, 38, 8);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = "#9f2d20";
  ctx.font = "900 11px Arial, sans-serif";
  ctx.textAlign = "left";
  const loadZones = plan.rack ? "tray or roof racks" : "tray";
  ctx.fillText(loadPlanFitText(ctx, `Does not fit ${loadZones}: ${plan.rejected.map((item) => item.name).join(", ")}`, right - x - 20), x + 10, y + 24);
  ctx.restore();
}

function loadPlanSpoolColor(index) {
  const colors = ["#0f6b73", "#b55532", "#6b5aa8", "#2f7d4f", "#9b4c72", "#4f6d7a"];
  return colors[index % colors.length];
}

function loadPlanLayerHeightMm(placement) {
  return (placement.layer ?? 0) * Math.max(
    LOAD_PLAN_LAYER_RISE_MM,
    Math.min(900, placement.footprint.verticalMm * 0.55 + placement.footprint.maxPipeOdMm * 1.5),
  );
}

function pointDistance2d(a, b) {
  return Math.hypot(a.x - b.x, a.y - b.y);
}

function drawTruckLoadPlan(plan, elapsed = 0, playing = false) {
  if (!loadPlanCanvas) return;
  const { ctx, width, height } = resizeCanvas(loadPlanCanvas);
  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = "#f8fbfa";
  ctx.fillRect(0, 0, width, height);

  const tray = plan?.tray ?? selectedLoadPlanTray();
  const rack = plan?.rack ?? selectedLoadPlanRack();

  if (!plan?.placements.length && !plan?.rejected.length) {
    ctx.fillStyle = "#17282c";
    ctx.font = "950 16px Arial, sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("Select spools to make a yard load layout", width / 2, height / 2);
    return;
  }

  const groups = loadPlanLayerGroups(plan, tray, rack);
  const margin = Math.max(14, Math.min(24, width * 0.03));
  const footerReserve = plan.rejected.length ? 68 : 30;
  const sideBySide = width >= 780;
  const topArea = sideBySide
    ? {
      x: margin,
      y: 36,
      width: Math.max(310, width * 0.56 - margin * 1.4),
      height: Math.max(190, height - 36 - footerReserve),
    }
    : {
      x: margin,
      y: 36,
      width: width - margin * 2,
      height: Math.max(150, (height - 36 - footerReserve) * 0.55),
    };
  const modelArea = sideBySide
    ? {
      x: topArea.x + topArea.width + 12,
      y: topArea.y,
      width: Math.max(220, width - (topArea.x + topArea.width + 12) - margin),
      height: topArea.height,
    }
    : {
      x: margin,
      y: topArea.y + topArea.height + 10,
      width: width - margin * 2,
      height: Math.max(118, height - (topArea.y + topArea.height + 10) - footerReserve),
    };
  const tiles = loadPlanTopViewTiles(topArea.width, topArea.height, groups, false)
    .map((tile) => ({
      ...tile,
      x: tile.x + topArea.x,
      y: tile.y + topArea.y,
    }));

  ctx.save();
  ctx.fillStyle = "#17282c";
  ctx.font = "950 15px Arial, sans-serif";
  ctx.textAlign = "left";
  ctx.fillText("Top-view load layout", topArea.x, 24);
  ctx.textAlign = "right";
  ctx.fillStyle = "#607176";
  ctx.font = "850 11px Arial, sans-serif";
  ctx.fillText("3D guide shows loading height", modelArea.x + modelArea.width, 24);
  ctx.restore();

  for (const tile of tiles) {
    drawLoadPlanTopViewTile(ctx, tile);
  }
  drawLoadPlanIsoModel(ctx, plan, modelArea);
  drawLoadPlanRejected(ctx, plan, tiles, width, height);

  ctx.save();
  ctx.fillStyle = "#5b6b70";
  ctx.font = "850 11px Arial, sans-serif";
  ctx.textAlign = "left";
  ctx.fillText("Use this as a basic yard guide only. Check the real tray, overhang and tie-downs before loading.", Math.max(16, tiles[0]?.x ?? 20), height - 14);
  ctx.restore();
}

function truncateLoadPlanName(value, maxLength) {
  const text = String(value ?? "").trim();
  return text.length > maxLength ? `${text.slice(0, maxLength - 1)}...` : text;
}

function updateLoadPlanSummary(plan) {
  if (!loadPlanSummary) return;
  if (!plan?.placements.length && !plan?.rejected.length) {
    loadPlanSummary.textContent = "Select spools, then press Make layout.";
    return;
  }

  const tray = plan.tray;
  const fitted = `${plan.placements.length}/${plan.placements.length + plan.rejected.length} fit`;
  const trayHasLoad = plan.placements.some((placement) => placement.zone === "tray");
  const rackHasLoad = plan.placements.some((placement) => placement.zone === "rack");
  const usedParts = [];
  const unusedParts = [];
  if (trayHasLoad) usedParts.push(`${formatLength(plan.usedLengthMm)} of ${formatLength(tray.lengthMm)} mm tray`);
  else unusedParts.push("tray unused");
  if (plan.rack && rackHasLoad) usedParts.push(`${formatLength(plan.rackUsedLengthMm)} of ${formatLength(plan.rack.lengthMm)} mm roof racks`);
  else if (plan.rack) unusedParts.push("roof racks unused");
  const used = plan.placements.length
    ? `using ${usedParts.join(" and ")}${unusedParts.length ? `; ${unusedParts.join(", ")}` : ""}`
    : plan.rack ? "no spool fits inside this tray or roof-rack footprint" : "no spool fits inside this tray footprint";
  const order = plan.placements
    .map((placement) => {
      const where = placement.zone === "rack" ? "roof racks" : "tray";
      const layer = placement.layer ? ` layer ${placement.layer + 1}` : "";
      const lay = placement.footprint?.label ? ` ${placement.footprint.label}` : "";
      return `${placement.order}. ${placement.item.name} on ${where}${layer}${lay}${placement.rotation ? ` rotated ${placement.rotation} deg` : ""}`;
    })
    .join("  ");
  const rejected = plan.rejected.length ? ` Not fitting: ${plan.rejected.map((item) => item.name).join(", ")}.` : "";
  loadPlanSummary.textContent = `${tray.label}: ${fitted}, ${used}. Load order: ${order}.${rejected} Basic yard guide only - check the real tray, overhang and tie-down points before loading.`;
}

function playTruckLoadAnimation() {
  const items = selectedLoadPlanItems();
  if (!items.length) {
    currentLoadPlan = createTruckLoadPlan([]);
    renderLoadPlan(currentLoadPlan);
    if (loadPlanSummary) {
      loadPlanSummary.textContent = "Tick one or more spools on the left, then press Make layout.";
    }
    return;
  }

  const plan = createTruckLoadPlan(items);
  currentLoadPlan = plan;
  if (!plan) {
    drawLoadPlanEmpty();
    return;
  }

  updateLoadPlanSummary(plan);
  startTruckLoadAnimation(plan);
}

function startTruckLoadAnimation(plan) {
  if (!plan) return;
  if (loadPlanAnimationFrame) {
    cancelAnimationFrame(loadPlanAnimationFrame);
    loadPlanAnimationFrame = 0;
  }

  loadPlanViewMode = "model";
  setLoadPlanSpin(false);
  updateLoadPlanViewControls();
  const startTime = performance.now();
  const duration = Math.max(900, plan.totalDuration + 360);

  const tick = (now) => {
    const elapsed = now - startTime;
    renderLoadPlan(plan, elapsed, true);
    if (elapsed < duration) {
      loadPlanAnimationFrame = requestAnimationFrame(tick);
      return;
    }
    loadPlanAnimationFrame = 0;
    renderLoadPlan(plan, duration, false);
  };

  loadPlanAnimationFrame = requestAnimationFrame(tick);
}

function redrawLoadPlanIfOpen() {
  if (!loadPlanDialog || loadPlanDialog.hidden) return;
  if (currentLoadPlan) {
    renderLoadPlan(currentLoadPlan);
  } else {
    renderLoadPlanProjectChoices();
  }
}

async function startNewDrawing() {
  clearPendingProjectCommentPhoto();
  let nextProjectDefaults = null;
  if (hasDrawingContent()) {
    const choice = await openNewDrawingDialog();
    if (choice === "cancel") return;
    if (choice === "save") {
      const saved = await saveBrowserProject({ silent: true });
      if (!saved) return;
      nextProjectDefaults = nextProjectInfoForNewSpool(state.projectInfo);
    }
  }

  persistUserDrawingDefaults();
  state = blankState();
  currentCloudProjectOwnerId = null;
  currentCloudProjectCompanyId = null;
  cloudPermissionReadOnly = false;
  resetCloudSaveTracking();
  projectComments = [];
  projectCommentsProjectId = null;
  nextFittingId = 1;
  nextNoteId = 1;
  three.userMovedCamera = false;
  updateControls();
  updateAll({ save: false });
  await promptForProjectDetails({ force: true, defaults: nextProjectDefaults });
}

function loadSampleDrawing() {
  clearPendingProjectCommentPhoto();
  loadStateIntoWorkspace(sampleState());
}

function loadStateIntoWorkspace(nextState, options = {}) {
  state = nextState;
  currentCloudProjectOwnerId = null;
  currentCloudProjectCompanyId = null;
  cloudPermissionReadOnly = false;
  resetCloudSaveTracking();
  projectComments = [];
  projectCommentsProjectId = null;
  setNextIdsFromState(state);
  three.userMovedCamera = false;
  updateControls();
  updateAll();
  if (options.openChecks === true) {
    applyAppMode("review", { keepTool: false });
    showHealthPanel();
  }
}

function regressionSampleByKey(key) {
  return REGRESSION_SAMPLES.find((sample) => sample.key === key) ?? REGRESSION_SAMPLES[0];
}

function activeRegressionSummaryMarkup() {
  const segmentData = segments();
  const quantities = quantitySummary(segmentData);
  const items = drawingHealthItems();
  const counts = healthCounts(items);
  return `
    <div>
      <strong>${escapeHtml(APP_VERSION)}</strong>
      <span>Current build</span>
    </div>
    <div>
      <strong>${segmentData.length}</strong>
      <span>Runs</span>
    </div>
    <div>
      <strong>${quantities.reducers.length}</strong>
      <span>Reducers</span>
    </div>
    <div>
      <strong>${counts.error ?? 0}/${counts.warning ?? 0}</strong>
      <span>Errors / warnings</span>
    </div>
  `;
}

function regressionAutoChecksMarkup() {
  const results = runRegressionAutoChecks();
  const passedCount = results.filter((result) => result.passed).length;
  return `
    <div class="regression-auto-panel">
      <div class="regression-auto-head">
        <div>
          <strong>Automatic drawing trust checks</strong>
          <span>Connections, flange drilling, offsets, sockets, save/open data and stainless 3D materials.</span>
        </div>
        <b>${passedCount}/${results.length} passed</b>
      </div>
      <div class="regression-auto-grid">
        ${results.map((result) => `
          <article class="regression-auto-check ${result.passed ? "pass" : "fail"}">
            <div>
              <strong>${escapeHtml(result.title)}</strong>
              <span>${escapeHtml(result.sampleTitle)}</span>
            </div>
            <b>${result.passed ? "PASS" : "CHECK"}</b>
            <small>${escapeHtml(result.detail)}</small>
          </article>
        `).join("")}
      </div>
    </div>
  `;
}

function renderRegressionDialog() {
  if (!regressionSummary || !regressionSampleList || !regressionChecklist) return;

  regressionSummary.innerHTML = activeRegressionSummaryMarkup();
  regressionSampleList.innerHTML = REGRESSION_SAMPLES.map((sample) => `
    <article class="regression-sample-card">
      <div>
        <strong>${escapeHtml(sample.title)}</strong>
        <span>${escapeHtml(sample.detail)}</span>
      </div>
      <ul>
        ${sample.checks.map((check) => `<li>${escapeHtml(check)}</li>`).join("")}
      </ul>
      <button type="button" class="primary-button" data-regression-sample="${escapeHtml(sample.key)}">Load test spool</button>
    </article>
  `).join("");
  regressionChecklist.innerHTML = `
    ${regressionAutoChecksMarkup()}
    <strong>Manual checks after loading samples</strong>
    <div class="regression-check-grid">
      ${REGRESSION_MANUAL_CHECKS.map((check, index) => `
        <label>
          <input type="checkbox" data-regression-check="${index}" />
          <span>${escapeHtml(check)}</span>
        </label>
      `).join("")}
    </div>
  `;
}

function openRegressionDialog() {
  closeActionMenu();
  renderRegressionDialog();
  if (regressionDialog) regressionDialog.hidden = false;
}

function closeRegressionDialog() {
  if (regressionDialog) regressionDialog.hidden = true;
}

async function loadRegressionSample(key) {
  const sample = regressionSampleByKey(key);
  if (!sample) return;
  if (hasDrawingContent()) {
    const proceed = await confirmAppAction(`Load ${sample.title}? This replaces the current drawing on this device. Save first if you need to keep it.`, {
      title: "Load test spool",
      confirmLabel: "Load sample",
      tone: "warning",
    });
    if (!proceed) return;
  }
  closeRegressionDialog();
  const nextState = sample.build();
  loadStateIntoWorkspace(nextState, { openChecks: true });
  cursorReadout.textContent = `Loaded test kit: ${sample.title}`;
  if (isTabletLayout()) {
    showMobilePanel("inspector");
  }
}

function setupRegressionDialog() {
  regressionChecklistButton?.addEventListener("click", openRegressionDialog);
  regressionCloseButton?.addEventListener("click", closeRegressionDialog);
  regressionDialog?.addEventListener("pointerdown", (event) => {
    if (event.target === regressionDialog) closeRegressionDialog();
  });
  regressionSampleList?.addEventListener("click", (event) => {
    const button = event.target instanceof Element ? event.target.closest("[data-regression-sample]") : null;
    if (!button || !regressionSampleList.contains(button)) return;
    loadRegressionSample(button.dataset.regressionSample);
  });
}

function defaultDrawingAssistantState() {
  return {
    mode: "scale",
    fileKind: "",
    fileName: "",
    objectUrl: "",
    image: null,
    points: [],
    segments: [],
    scalePoints: [],
    mmPerPx: null,
  };
}

function ensureDrawingAssistantState() {
  if (!drawingAssistantState) drawingAssistantState = defaultDrawingAssistantState();
  return drawingAssistantState;
}

function openDrawingAssistantDialog() {
  if (!drawingAssistantDialog) return;
  closeActionMenu();
  closeHomeDashboard();
  closeProjectLibrary();
  closeHelpDialog();
  closeToolSettingsDialog();
  ensureDrawingAssistantState();
  drawingAssistantDialog.hidden = false;
  setDrawingAssistantMode(drawingAssistantState.mode || "scale");
  renderDrawingAssistantSegments();
  updateDrawingAssistantStatus();
  window.requestAnimationFrame(renderDrawingAssistant);
}

function closeDrawingAssistantDialog() {
  if (drawingAssistantDialog) drawingAssistantDialog.hidden = true;
}

function setDrawingAssistantMode(mode) {
  const nextMode = mode === "trace" ? "trace" : "scale";
  ensureDrawingAssistantState().mode = nextMode;
  drawingAssistantModeButtons.forEach((button) => {
    const active = button.dataset.drawingAssistantMode === nextMode;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", String(active));
  });
  updateDrawingAssistantStatus();
  renderDrawingAssistant();
}

function drawingAssistantCanvasInfo() {
  if (!drawingAssistantCanvas) return null;
  const rect = drawingAssistantCanvas.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  const width = Math.max(320, rect.width || 900);
  const height = Math.max(240, rect.height || 560);
  const pixelWidth = Math.round(width * dpr);
  const pixelHeight = Math.round(height * dpr);
  if (drawingAssistantCanvas.width !== pixelWidth || drawingAssistantCanvas.height !== pixelHeight) {
    drawingAssistantCanvas.width = pixelWidth;
    drawingAssistantCanvas.height = pixelHeight;
  }
  const ctx = drawingAssistantCanvas.getContext("2d");
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return { ctx, width, height };
}

function drawingAssistantImageRect(width, height) {
  const image = drawingAssistantState?.image;
  if (!image) return null;
  const scale = Math.min(width / image.naturalWidth, height / image.naturalHeight);
  const drawWidth = image.naturalWidth * scale;
  const drawHeight = image.naturalHeight * scale;
  return {
    x: (width - drawWidth) * 0.5,
    y: (height - drawHeight) * 0.5,
    width: drawWidth,
    height: drawHeight,
  };
}

function renderDrawingAssistant() {
  if (!drawingAssistantCanvas || !drawingAssistantDialog || drawingAssistantDialog.hidden) return;
  const assistant = ensureDrawingAssistantState();
  const info = drawingAssistantCanvasInfo();
  if (!info) return;
  const { ctx, width, height } = info;
  ctx.clearRect(0, 0, width, height);

  const hasFile = Boolean(assistant.fileKind);
  if (drawingAssistantEmpty) drawingAssistantEmpty.hidden = hasFile || assistant.points.length > 0;
  if (drawingAssistantPdfFrame) {
    drawingAssistantPdfFrame.hidden = assistant.fileKind !== "pdf";
  }

  if (assistant.fileKind === "image" && assistant.image) {
    ctx.fillStyle = "#0b1218";
    ctx.fillRect(0, 0, width, height);
    const rect = drawingAssistantImageRect(width, height);
    if (rect) {
      ctx.drawImage(assistant.image, rect.x, rect.y, rect.width, rect.height);
      ctx.fillStyle = "rgba(0, 0, 0, 0.08)";
      ctx.fillRect(rect.x, rect.y, rect.width, rect.height);
    }
  } else if (assistant.fileKind !== "pdf") {
    ctx.fillStyle = isDarkAppTheme() ? "rgba(6, 16, 24, 0.88)" : "rgba(251, 250, 244, 0.88)";
    ctx.fillRect(0, 0, width, height);
  }

  drawDrawingAssistantScale(ctx, assistant);
  drawDrawingAssistantTrace(ctx, assistant);
}

function drawDrawingAssistantScale(ctx, assistant) {
  if (!assistant.scalePoints.length) return;
  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.strokeStyle = "#f97316";
  ctx.fillStyle = "#f97316";
  ctx.lineWidth = 3;
  if (assistant.scalePoints.length === 2) {
    drawLine(ctx, assistant.scalePoints[0], assistant.scalePoints[1]);
    const midpoint = {
      x: (assistant.scalePoints[0].x + assistant.scalePoints[1].x) * 0.5,
      y: (assistant.scalePoints[0].y + assistant.scalePoints[1].y) * 0.5,
    };
    drawAssistantLabel(ctx, midpoint, `${formatLength(Number(drawingAssistantScaleInput?.value) || 0)} mm scale`, "#f97316");
  }
  assistant.scalePoints.forEach((point, index) => {
    ctx.beginPath();
    ctx.arc(point.x, point.y, 8, 0, Math.PI * 2);
    ctx.fill();
    drawAssistantLabel(ctx, { x: point.x + 12, y: point.y - 12 }, `S${index + 1}`, "#f97316");
  });
  ctx.restore();
}

function drawDrawingAssistantTrace(ctx, assistant) {
  const points = assistant.points;
  if (!points.length) return;
  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.lineWidth = 5;
  ctx.strokeStyle = "#13d8ff";
  ctx.fillStyle = "#13d8ff";
  if (points.length > 1) {
    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);
    for (const point of points.slice(1)) ctx.lineTo(point.x, point.y);
    ctx.stroke();
  }

  points.forEach((point, index) => {
    ctx.beginPath();
    ctx.fillStyle = index === points.length - 1 ? "#ffd46b" : "#13d8ff";
    ctx.strokeStyle = "#06202a";
    ctx.lineWidth = 3;
    ctx.arc(point.x, point.y, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    drawAssistantLabel(ctx, { x: point.x + 12, y: point.y - 12 }, String(index + 1), "#06202a");
  });

  assistant.segments.forEach((segment, index) => {
    const start = points[index];
    const end = points[index + 1];
    if (!start || !end) return;
    const midpoint = { x: (start.x + end.x) * 0.5, y: (start.y + end.y) * 0.5 };
    drawAssistantLabel(ctx, midpoint, `${axisLabel(segment.axis)} ${formatLength(segment.lengthMm)} mm`, "#0f766e");
  });
  ctx.restore();
}

function drawAssistantLabel(ctx, point, text, color = "#0f766e") {
  ctx.save();
  ctx.font = "900 12px Inter, system-ui, sans-serif";
  const value = String(text ?? "");
  const width = ctx.measureText(value).width + 12;
  const height = 22;
  const x = point.x - width * 0.5;
  const y = point.y - height * 0.5;
  roundRect(ctx, x, y, width, height, 6);
  ctx.fillStyle = "rgba(255, 255, 255, 0.92)";
  ctx.fill();
  ctx.strokeStyle = "rgba(31, 42, 47, 0.18)";
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = color;
  ctx.textBaseline = "middle";
  ctx.textAlign = "center";
  ctx.fillText(value, point.x, point.y + 1);
  ctx.restore();
}

function drawingAssistantPointer(event) {
  const rect = drawingAssistantCanvas.getBoundingClientRect();
  return {
    x: event.clientX - rect.left,
    y: event.clientY - rect.top,
  };
}

function handleDrawingAssistantPointer(event) {
  if (!drawingAssistantDialog || drawingAssistantDialog.hidden || event.button !== 0) return;
  const assistant = ensureDrawingAssistantState();
  const point = drawingAssistantPointer(event);
  if (assistant.mode === "scale") {
    assistant.scalePoints = [...assistant.scalePoints, point].slice(-2);
    updateDrawingAssistantStatus();
    renderDrawingAssistant();
    event.preventDefault();
    return;
  }

  assistant.points.push(point);
  if (assistant.points.length > 1) {
    const previous = assistant.points[assistant.points.length - 2];
    assistant.segments.push({
      axis: guessDrawingAssistantAxis(previous, point),
      lengthMm: drawingAssistantMeasuredLength(previous, point),
      manual: false,
    });
  }
  updateDrawingAssistantStatus();
  renderDrawingAssistantSegments();
  renderDrawingAssistant();
  event.preventDefault();
}

function guessDrawingAssistantAxis(start, end) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  if (Math.abs(dy) > Math.abs(dx) * 1.35) return dy < 0 ? "zp" : "zn";
  if (Math.abs(dx) > Math.abs(dy) * 1.15) return dx >= 0 ? "xp" : "xn";
  return dx >= 0 ? "yp" : "yn";
}

function axisLabel(axisKey) {
  return axisByKey.get(axisKey)?.label ?? "+X";
}

function drawingAssistantMeasuredLength(start, end) {
  const distancePx = Math.hypot(end.x - start.x, end.y - start.y);
  const mmPerPx = Number(ensureDrawingAssistantState().mmPerPx);
  return normalizeLength(Number.isFinite(mmPerPx) && mmPerPx > 0 ? distancePx * mmPerPx : 1000);
}

function updateDrawingAssistantStatus() {
  if (!drawingAssistantStatus) return;
  const assistant = ensureDrawingAssistantState();
  const file = assistant.fileName ? `${assistant.fileName}. ` : "";
  const scale = assistant.mmPerPx ? `Scale ${assistant.mmPerPx.toFixed(2)} mm/px. ` : "Scale not set. ";
  const trace = assistant.points.length
    ? `${assistant.points.length} point${assistant.points.length === 1 ? "" : "s"} traced / ${assistant.segments.length} run${assistant.segments.length === 1 ? "" : "s"}.`
    : assistant.mode === "scale"
    ? "Click two points on a known dimension."
    : "Click centreline points in run order.";
  drawingAssistantStatus.textContent = `${file}${scale}${trace}`;
}

function renderDrawingAssistantSegments() {
  if (!drawingAssistantSegments) return;
  const assistant = ensureDrawingAssistantState();
  if (!assistant.segments.length) {
    drawingAssistantSegments.innerHTML = `<div class="drawing-assistant-placeholder">No traced pipe legs yet. Switch to Trace and click points along the pipe centreline.</div>`;
    return;
  }

  drawingAssistantSegments.innerHTML = assistant.segments.map((segment, index) => `
    <div class="drawing-assistant-leg" data-assistant-leg="${index}">
      <strong>Leg ${index + 1}</strong>
      <label>
        Axis
        <select data-assistant-axis="${index}">
          ${AXES.map((axis) => `<option value="${axis.key}"${axis.key === segment.axis ? " selected" : ""}>${axis.label}</option>`).join("")}
        </select>
      </label>
      <label>
        Length mm
        <input data-assistant-length="${index}" type="number" min="${MIN_LENGTH_MM}" max="${MAX_LENGTH_MM}" step="${LENGTH_INCREMENT_MM}" value="${Math.round(segment.lengthMm)}" />
      </label>
      <small>${segment.manual ? "Typed from drawing." : assistant.mmPerPx ? "Estimated from picked scale." : "Enter the drawing measurement manually."}</small>
    </div>
  `).join("");

  drawingAssistantSegments.querySelectorAll("[data-assistant-axis]").forEach((select) => {
    select.addEventListener("change", () => {
      const index = Number(select.dataset.assistantAxis);
      if (!assistant.segments[index]) return;
      assistant.segments[index].axis = select.value;
      renderDrawingAssistant();
    });
  });
  drawingAssistantSegments.querySelectorAll("[data-assistant-length]").forEach((input) => {
    input.addEventListener("input", () => {
      const index = Number(input.dataset.assistantLength);
      if (!assistant.segments[index]) return;
      assistant.segments[index].lengthMm = normalizeLength(input.value);
      assistant.segments[index].manual = true;
      renderDrawingAssistant();
    });
  });
}

function applyDrawingAssistantScale() {
  const assistant = ensureDrawingAssistantState();
  if (assistant.scalePoints.length < 2) {
    showAppNotice("Pick two points on a known dimension first.");
    return;
  }
  const distanceMm = normalizeLength(drawingAssistantScaleInput?.value);
  const pixelDistance = Math.hypot(
    assistant.scalePoints[1].x - assistant.scalePoints[0].x,
    assistant.scalePoints[1].y - assistant.scalePoints[0].y,
  );
  if (pixelDistance < 4) {
    showAppNotice("Those scale points are too close together.");
    return;
  }
  assistant.mmPerPx = distanceMm / pixelDistance;
  assistant.segments = assistant.segments.map((segment, index) => {
    if (segment.manual) return segment;
    const start = assistant.points[index];
    const end = assistant.points[index + 1];
    return start && end ? { ...segment, lengthMm: drawingAssistantMeasuredLength(start, end) } : segment;
  });
  setDrawingAssistantMode("trace");
  updateDrawingAssistantStatus();
  renderDrawingAssistantSegments();
  renderDrawingAssistant();
}

function clearDrawingAssistantScalePicks() {
  const assistant = ensureDrawingAssistantState();
  assistant.scalePoints = [];
  renderDrawingAssistant();
  updateDrawingAssistantStatus();
}

function undoDrawingAssistantPoint() {
  const assistant = ensureDrawingAssistantState();
  if (!assistant.points.length) return;
  assistant.points.pop();
  assistant.segments.pop();
  renderDrawingAssistantSegments();
  renderDrawingAssistant();
  updateDrawingAssistantStatus();
}

function clearDrawingAssistantTrace() {
  const assistant = ensureDrawingAssistantState();
  assistant.points = [];
  assistant.segments = [];
  renderDrawingAssistantSegments();
  renderDrawingAssistant();
  updateDrawingAssistantStatus();
}

function loadDrawingAssistantDemoTrace() {
  const assistant = ensureDrawingAssistantState();
  assistant.fileKind = "";
  assistant.fileName = "Demo trace";
  assistant.image = null;
  assistant.points = [
    { x: 130, y: 360 },
    { x: 305, y: 260 },
    { x: 470, y: 330 },
    { x: 470, y: 165 },
    { x: 640, y: 165 },
  ];
  assistant.mmPerPx = 12;
  assistant.scalePoints = [
    { x: 130, y: 410 },
    { x: 380, y: 410 },
  ];
  if (drawingAssistantScaleInput) drawingAssistantScaleInput.value = "3000";
  assistant.segments = [
    { axis: "xp", lengthMm: 3000, manual: true },
    { axis: "yp", lengthMm: 2500, manual: true },
    { axis: "zp", lengthMm: 1800, manual: true },
    { axis: "xp", lengthMm: 2200, manual: true },
  ];
  if (drawingAssistantPdfFrame) {
    drawingAssistantPdfFrame.hidden = true;
    drawingAssistantPdfFrame.removeAttribute("src");
  }
  setDrawingAssistantMode("trace");
  renderDrawingAssistantSegments();
  renderDrawingAssistant();
  updateDrawingAssistantStatus();
}

async function loadDrawingAssistantFile(file) {
  if (!file) return;
  const assistant = ensureDrawingAssistantState();
  if (assistant.objectUrl) URL.revokeObjectURL(assistant.objectUrl);
  assistant.objectUrl = URL.createObjectURL(file);
  assistant.fileName = file.name;
  assistant.points = [];
  assistant.segments = [];
  assistant.scalePoints = [];
  assistant.mmPerPx = null;
  assistant.image = null;

  if (file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf")) {
    assistant.fileKind = "pdf";
    if (drawingAssistantPdfFrame) {
      drawingAssistantPdfFrame.src = assistant.objectUrl;
      drawingAssistantPdfFrame.hidden = false;
    }
    setDrawingAssistantMode("scale");
    renderDrawingAssistantSegments();
    renderDrawingAssistant();
    updateDrawingAssistantStatus();
    return;
  }

  if (!file.type.startsWith("image/")) {
    showAppNotice("Please upload an image, screenshot, photo or PDF.");
    return;
  }

  assistant.fileKind = "image";
  if (drawingAssistantPdfFrame) {
    drawingAssistantPdfFrame.hidden = true;
    drawingAssistantPdfFrame.removeAttribute("src");
  }
  const image = new Image();
  await new Promise((resolve, reject) => {
    image.addEventListener("load", resolve, { once: true });
    image.addEventListener("error", reject, { once: true });
    image.src = assistant.objectUrl;
  });
  assistant.image = image;
  setDrawingAssistantMode("scale");
  renderDrawingAssistantSegments();
  renderDrawingAssistant();
  updateDrawingAssistantStatus();
}

async function buildSpoolFromDrawingAssistant() {
  if (!ensureDrawingEditable("build a spool from an imported drawing")) return;
  const assistant = ensureDrawingAssistantState();
  if (assistant.points.length < 2 || assistant.segments.length < 1) {
    showAppNotice("Trace at least two centreline points first.");
    return;
  }
  if (assistant.segments.length !== assistant.points.length - 1) {
    showAppNotice("The traced points and pipe legs do not line up yet.");
    return;
  }
  const invalid = assistant.segments.find((segment) => !axisByKey.has(segment.axis) || !Number.isFinite(Number(segment.lengthMm)));
  if (invalid) {
    showAppNotice("Check every leg has an axis and length.");
    return;
  }
  if (hasDrawingContent()) {
    const replace = await confirmAppAction("Replace the current spool geometry with this imported trace?", {
      title: "Replace drawing",
      confirmLabel: "Replace",
      tone: "warning",
    });
    if (!replace) return;
  }

  const snapshot = createUndoSnapshot();
  const points = [{ x: 0, y: 0, z: 0 }];
  for (const segment of assistant.segments) {
    const axis = axisByKey.get(segment.axis);
    const previous = points[points.length - 1];
    points.push(addPoints(previous, axis.vector, normalizeLength(segment.lengthMm)));
  }
  state.points = points;
  state.edges = assistant.segments.map((segment, index) => ({
    from: index,
    to: index + 1,
    pipeSizeNb: normalizePipeSize(state.pipeSizeNb),
  }));
  state.fittings = [];
  state.notes = [];
  state.measurements = [];
  state.nodeTypes = {};
  state.reducerSideOverrides = {};
  state.dimensionOffsets = {};
  state.activePoint = points.length - 1;
  state.selectedPoint = points.length - 1;
  state.selectedFitting = null;
  state.selectedNote = null;
  state.selectedMeasurement = null;
  clearSelectedSegments();
  state.previewCandidate = null;
  state.pointer = null;
  state.projectInfoPrompted = state.projectInfoPrompted === true || hasProjectInfo();
  setNextIdsFromState(state);
  recordHistory({ type: "snapshot", snapshot });
  three.userMovedCamera = false;
  updateControls();
  updateAll();
  closeDrawingAssistantDialog();
}

