  releaseTrackedTouchPointer(event);
  if (!wasPinching) return false;

  if (activeTouchPointers.size >= 2) {
    beginPinchGesture();
  } else {
    pinchGesture = null;
    updateAll();
  }

  event.preventDefault();
  return true;
