document.addEventListener("keydown", (event) => {
  const isEnterKey = event.key === "Enter" || event.code === "NumpadEnter";
  if (event.key === "Shift" && !isEditingField(event.target)) {
    setShiftAngleSnap(true);
  }
  const key = event.key.toLowerCase();
  const controlOrMeta = event.ctrlKey || event.metaKey;
  if (controlOrMeta && (key === "y" || (key === "z" && event.shiftKey))) {
    event.preventDefault();
    redo();
  } else if (controlOrMeta && key === "z") {
    event.preventDefault();
    undo();
  } else if (isEnterKey && shouldStopDrawingOnEnter(event.target)) {
    event.preventDefault();
    stopDrawingMode();
  } else if ((event.key === "Delete" || event.key === "Backspace") && !isEditingField(event.target)) {
    event.preventDefault();
    deleteSelection();
  } else if (event.key === "Escape") {
    if (focusModeActive) {
      setFocusMode(false);
      return;
    }
    if (actionMenuOpen()) {
      closeActionMenu();
      return;
    }
    if (appFullscreenPanel || browserFullscreenElement()) {
      closePanelFullscreen();
      return;
    }
    if (loadPlanDialog && !loadPlanDialog.hidden) {
      closeLoadPlanDialog();
      return;
    }
    if (newDrawingDialog && !newDrawingDialog.hidden) {
      closeNewDrawingDialog("cancel");
      return;
    }
    if (authDialog && !authDialog.hidden) {
      closeAuthDialog();
      return;
    }
    if (toolSettingsDialog && !toolSettingsDialog.hidden) {
      closeToolSettingsDialog();
      return;
    }
    if (fieldInputDialog && !fieldInputDialog.hidden) {
      closeFieldInputDialog(null);
      return;
    }
    if (appConfirmDialog && !appConfirmDialog.hidden) {
      closeAppConfirmDialog(false);
      return;
    }
    if (noteDialog && !noteDialog.hidden) {
      closeNoteDialog(null);
      return;
    }
    if (drawingAssistantDialog && !drawingAssistantDialog.hidden) {
      closeDrawingAssistantDialog();
      return;
    }
    if (helpDialog && !helpDialog.hidden) {
      closeHelpDialog();
      return;
    }
    if (tutorialDialog && !tutorialDialog.hidden) {
      closeTutorialDialog();
      return;
    }
    if (projectJobQuickPick && !projectJobQuickPick.hidden) {
      closeProjectJobPicker();
      return;
    }
    if (measurementDraft) {
      measurementDraft = null;
      state.pointer = null;
      cursorReadout.textContent = "Measurement cancelled";
      drawIso();
      return;
    }
    closeDrawingContextMenu();
    closeProjectLibrary();
    state.selectedFitting = null;
    state.selectedMeasurement = null;
    clearSelectedSegments();
    setTool("draw");
    updateAll({ save: false });
  }
}, true);

document.addEventListener("keyup", (event) => {
  if (event.key === "Shift") {
    setShiftAngleSnap(false);
  }
});

function isEditingField(target) {
  if (!(target instanceof HTMLElement)) return false;
  return target.matches("input, select, textarea") || target.isContentEditable;
}

function shouldStopDrawingOnEnter(target) {
  if (!(DRAW_STOP_TOOLS.has(state.activeTool) || pendingDraw)) return false;
  if (keyboardBlockingOverlayOpen()) return false;
  if (!(target instanceof HTMLElement)) return true;
  if (target.isContentEditable || target instanceof HTMLTextAreaElement) return false;
  if (target instanceof HTMLInputElement) {
    const textTypes = new Set(["", "text", "search", "email", "password", "tel", "url"]);
    if (textTypes.has(target.type.toLowerCase())) return false;
  }
  return true;
}

function keyboardBlockingOverlayOpen() {
  return Boolean(
    actionMenuOpen() ||
    (projectDialog && !projectDialog.hidden) ||
    (newDrawingDialog && !newDrawingDialog.hidden) ||
    (authDialog && !authDialog.hidden) ||
    (homeDashboardDialog && !homeDashboardDialog.hidden) ||
    (projectLibraryDialog && !projectLibraryDialog.hidden) ||
    (regressionDialog && !regressionDialog.hidden) ||
    (toolSettingsDialog && !toolSettingsDialog.hidden) ||
    (fieldInputDialog && !fieldInputDialog.hidden) ||
    (appConfirmDialog && !appConfirmDialog.hidden) ||
    (noteDialog && !noteDialog.hidden) ||
    (helpDialog && !helpDialog.hidden) ||
    (tutorialDialog && !tutorialDialog.hidden) ||
    (loadPlanDialog && !loadPlanDialog.hidden) ||
    (projectJobQuickPick && !projectJobQuickPick.hidden) ||
    !drawingContextMenu.hidden,
  );
}

document.addEventListener("pointerdown", (event) => {
  if (drawingContextMenu.hidden) return;
  if (drawingContextMenu.contains(event.target) || event.target === drawCanvas) return;
  closeDrawingContextMenu();
});

